["Here is a basic example of how you might implement such a system using C11's threading features and a simple hash table for efficient lookup. This code does not include all the optimizations mentioned (like lock-free data structures or memory pool), but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    // Define your structure here
} NFAPI_MESSAGE_PDU_T;

// Hash table entry
typedef struct hash_entry_t {
    uint64_t ue_id;
    atomic_uint_fast64_t timestamp;
    NFAPI_MESSAGE_PDU_T* message;
    struct hash_entry_t *next;
} hash_entry_t;

// Hash table
typedef struct {
    size_t capacity;
    atomic_int lock;
    hash_entry_t **table;
} hash_table_t;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

hash_table_t *create_hash_table(size_t capacity) {
    // Initialize the hash table
    hash_table_t *new_table = malloc(sizeof(hash_table_t));
    if (!new_table) return NULL;

    new_table->capacity = capacity;
    atomic_init(&new_table->lock, 0);
    new_table->table = calloc(capacity, sizeof(hash_entry_t*));
    if (!new_table->table) {
        free(new_table);
        return NULL;
    }

    return new_table;
}

void destroy_hash_table(hash_table_t *table) {
    // Free all entries and the table itself
    for (size_t i = 0; i < table->capacity; ++i) {
        hash_entry_t *entry = table->table[i];
        while (entry) {
            hash_entry_t *next = entry->next;
            free(entry);
            entry = next;
        }
    }

    free(table->table);
    free(table);
}

void add_message(_Atomic(hash_table_t*) table, uint64_t ue_id, NFAPI_MESSAGE_PDU_T *message) {
    // Acquire the lock and add the message to the hash table
    while (atomic_flag_test_and_set(&(*table)->lock));

    size_t index = ue_id % (*table)->capacity;
    hash_entry_t *new_entry = malloc(sizeof(hash_entry_t));
    if (new_entry) {
        new_entry->ue_id = ue_id;
        atomic_init(&new_entry->timestamp, time(NULL));
        new_entry->message = message;

        // Add the entry to the hash table
        new_entry->next = (*table)->table[index];
        (*table)->table[index] = new_entry;
    } else {
        // Handle memory allocation failure
    }

    atomic_flag_clear(&(*table)->lock);
}

NFAPI_MESSAGE_PDU_T *get_message(_Atomic(hash_table_t*) table, uint64_t ue_id) {
    // Acquire the lock and retrieve the message from the hash table
    while (atomic_flag_test_and_set(&(*table)->lock));

    size_t index = ue_id % (*table)->capacity;
    hash_entry_t *entry = (*table)->table[index];
    NFAPI_MESSAGE_PDU_T *message = NULL;

    // Search for the message in the linked list
    while (entry) {
        if (entry->ue_id == ue_id) {
            message = entry->message;
            break;
        }

        entry = entry->next;
    }

    atomic_flag_clear(&(*table)->lock);
    return message;
}
```
This code is a basic example and does not include all the optimizations mentioned (like lock-free data structures or memory pool), but it should give you a good starting point. It also doesn't handle updating existing messages, which would require additional logic to find and replace the old entry with the new one. 

Please note that this code is just an example and may not be suitable for your specific use case without further modifications. Always test thoroughly when implementing such systems.
