#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    long* offsets;
    int* keys;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    Record** records;
} RecordsManager;

RecordsManager* createRecordsManager(size_t initialCapacity) {
    RecordsManager* manager = malloc(sizeof(RecordsManager));
    if (manager == NULL) return NULL;

    manager->capacity = initialCapacity;
    manager->count = 0;
    manager->records = calloc(initialCapacity, sizeof(Record*));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }

    return manager;
}

void addRecord(RecordsManager* manager, Record* record) {
    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        Record** newArray = realloc(manager->records, newCapacity * sizeof(Record*));
        if (newArray == NULL) return;

        manager->records = newArray;
        manager->capacity = newCapacity;
    }

    manager->records[manager->count++] = record;
}

void freeRecordsManager(RecordsManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        Record* record = manager->records[i];
        free(record->offsets);
        free(record->keys);
        free(record);
    }

    free(manager->records);
    free(manager);
}
```
This code creates a `RecordsManager` structure that manages an array of `Record` structures. It uses dynamic memory allocation to ensure the total memory usage does not exceed a specified limit. The `addRecord` function handles resizing the data structure as needed. 

