['Here is an example of how you might approach this problem using C, POSIX threads (pthreads), and asynchronous I/O (aio). This code does not include the logging mechanism or command-line argument parsing for simplicity. 

```c
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <aio.h>
#include <pthread.h>

#define BUF_SIZE 4096
#define MAX_CONCURRENT_FILES 128

typedef struct {
    int fd;
    char buf[BUF_SIZE];
} FileData;

void* processFile(void* arg) {
    FileData* file = (FileData*)arg;
    ssize_t bytesRead = 0;
    off_t offset = 0;
    struct aiocb aio;

    while ((bytesRead = pread(file->fd, file->buf, BUF_SIZE, offset)) > 0) {
        // Process the data in file->buf here.

        offset += bytesRead;
    }

    close(file->fd);
    free(arg);
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t threads[MAX_CONCURRENT_FILES];
    int threadCount = 0;

    for (int i = 1; i < argc; ++i) {
        FileData* file = malloc(sizeof(FileData));
        if ((file->fd = open(argv[i], O_RDONLY)) == -1) {
            perror("open");
            free(file);
            continue;
        }

        pthread_create(&threads[threadCount++ % MAX_CONCURRENT_FILES], NULL, processFile, file);
    }

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```
This code reads files asynchronously using POSIX threads and the aio library. It uses pread to read from each file in chunks of BUF_SIZE bytes, which can be adjusted based on your expected I/O throughput. The program also limits the number of concurrently open files to MAX_CONCURRENT_FILES to prevent running out of file descriptors or memory.

Please note that this is a simplified example and does not include error handling for edge cases, logging mechanism, command-line argument parsing, tuning options for concurrency level based on available system resources and expected load, gracefully handle interruptions and ensure that partial results are not lost. You would need to add these features according to your specific requirements.
']

