["Here is a basic outline of how you might implement this in C. This code does not include all the features mentioned, but it should give you an idea of how to start implementing such a library. 

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    sem_t *sem;
    int value;
} Semaphore;

Semaphore* createSemaphore(int value) {
    Semaphore *s = malloc(sizeof(Semaphore));
    s->value = value;
    s->sem = malloc(sizeof(sem_t));
    sem_init(s->sem, 0, value);
    return s;
}

void deleteSemaphore(Semaphore *s) {
    sem_destroy(s->sem);
    free(s->sem);
    free(s);
}

int reserveSemaphore(Semaphore *s, int timeout) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout;
    return sem_timedwait(s->sem, &ts);
}

void releaseSemaphore(Semaphore *s) {
    sem_post(s->sem);
}
```
This is a very basic implementation and does not include many features such as logging or cleanup. It also doesn't handle concurrent access to the semaphores, which would require additional synchronization primitives (e.g., mutexes). 

