    // Define your configuration fields here.
}

fn load_config(path: &str) -> Result<Config, Box<dyn std::error::Error>> {
    let mut file = File::open(path)?;
    let mut data = String::new();
    file.read_to_string(&mut data)?;

    // Validate the JSON against the schema.
    let schema_data = schemars::schema_for::<Config>().unwrap();
    let schema = serde_json::from_str::<serde_json::Value>(&schema_data).unwrap();
    let json: serde_json::Value = serde_json::from_str(&data)?;
    schemars::validate_with_schema(&schema, &json)?;

    // Deserialize the JSON into a Config struct.
    let config: Config = serde_json::from_str(&data)?;

    info_log(format_args_1, "Config loaded successfully");

    Ok(config)
}
