        for (const auto& file : imageFiles) {
            try {
                cv::Mat img = cv::imread(file, cv::IMREAD_GRAYSCALE);
                if (img.empty()) {
                    BOOST_LOG_TRIVIAL(error) << "Failed to load image: " << file;
                    continue;
