['Here is a basic implementation of such a method in C# using async/await pattern, Entity Framework Core for database operations, and Polly for resilience and retry policies. This code assumes that you have a `Record` class representing your data model and a `DataValidationService` class for validating the records:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Polly;

public class BatchInsertSummary
{
    public int SuccessCount { get; set; }
    public int FailureCount { get; set; }
}

public class Record
{
    // Define your record properties here
}

public class DataValidationService
{
    // Implement your data validation service methods here
}

public class BatchInsertManager
{
    private readonly string _connectionString;
    private readonly int _batchSizeThreshold;
    private readonly DataValidationService _dataValidationService;

    public BatchInsertManager(string connectionString, int batchSizeThreshold)
    {
        _connectionString = connectionString;
        _batchSizeThreshold = batchSizeThreshold;
        _dataValidationService = new DataValidationService(); // Replace with your actual validation service instance
    }

    public async Task<BatchInsertSummary> BatchInsertAsync(List<Record> records, string tableName)
    {
        var summary = new BatchInsertSummary();
        using (var context = new YourDbContext(_connectionString)) // Replace with your actual DbContext class and constructor
        {
            foreach (var batch in records.Batch(_batchSizeThreshold))
            {
                var tasks = batch.Select(async record =>
                {
                    try
                    {
                        await Policy
                            .Handle<Exception>() // Handle any exception that might occur during the validation and insertion process
                            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt))) // Retry policy with exponential backoff
                            .ExecuteAsync(async () =>
                            {
                                await _dataValidationService.ValidateRecordAsync(record); // Replace with your actual validation method
                                context.Set<Record>().Add(record);
                                await context.SaveChangesAsync();
                            });
                        Interlocked.Increment(ref summary.SuccessCount);
                    }
                    catch (Exception)
                    {
                        Interlocked.Increment(ref summary.FailureCount);
                    }
                });

                await Task.WhenAll(tasks); // Execute all tasks concurrently
            }
        }

        return summary;
    }
}
```
This code uses the `Batch` extension method from MoreLINQ to partition the records into batches, and then executes each batch asynchronously. It also uses Polly for resilience and retry policies in case of failures during validation or insertion. The summary of the operations is returned at the end.
']

