["Here is a high-level example using Node.js with Express framework for the web API endpoint, Joi for data validation, MongoDB as database, and Winston for logging. This code does not include all the mentioned constraints but it gives you an idea of how you can implement them in your application:

```javascript
const express = require('express');
const router = express.Router();
const Joi = require('joi');
const mongoose = require('mongoose');
const winston = require('winston');

// Define a schema for validation
const schema = Joi.object({
    name: Joi.string().required(),
    email: Joi.string().email().required()
});

// Connect to MongoDB
mongoose.connect('mongodb://localhost/test', { useNewUrlParser: true, useUnifiedTopology: true });
const db = mongoose.connection;
db.on('error', (err) => winston.error(`Database connection error: ${err}`));
db.once('open', () => console.log('Connected to MongoDB'));

// Define a schema for MongoDB
const userSchema = new mongoose.Schema({
    name: String,
    email: String,
    __v: { type: Number, select: false} // Version key for optimistic concurrency control
});

// Create a model from the schema
const User = mongoose.model('User', userSchema);

router.put('/users/:id', async (req, res) => {
    try {
        const { error } = schema.validate(req.body); // Validate incoming data
        if (error) return res.status(400).send({ message: 'Invalid request body' });

        const user = await User.findOneAndUpdate(
            { _id: req.params.id, __v: req.body.__v - 1 }, // Check version for concurrency control
            req.body,
            { new: true }
        );

        if (!user) return res.status(409).send({ message: 'Conflict' }); // If no user found or version mismatch

        res.json(user);
    } catch (err) {
        winston.error(`Error updating user: ${err}`);
        res.status(500).send({ message: 'Internal server error' });
    }
});

router.delete('/users/:id', async (req, res) => {
    try {
        const user = await User.findByIdAndDelete(req.params.id);

        if (!user) return res.status(404).send({ message: 'User not found' }); // If no user found

        winston.info(`Deleted user with id ${user._id}`);
        res.json({ name: '', email: '' }); // Return new resource with default values
    } catch (err) {
        winston.error(`Error deleting user: ${err}`);
        res.status(500).send({ message: 'Internal server error' });
    }
});

module.exports = router;
```
This is a basic example and does not cover all the mentioned constraints, but it should give you an idea of how to implement them in your application. For each constraint, you would need to add more code or adjust this existing code accordingly.
