['```csharp
using System;
using System.IO;
using System.Xml;
using System.Diagnostics;
using System.Threading;
using System.Configuration;

public class DirectoryManager
{
    private static readonly object _lock = new object();
    private static string _directoryPath;

    public void CreateDirectoryAndUpdateEnvironmentVariable()
    {
        Stopwatch stopwatch = new Stopwatch();
        stopwatch.Start();

        lock (_lock)
        {
            if (string.IsNullOrEmpty(_directoryPath))
            {
                string uniqueId = DateTime.Now.ToString("yyyyMMddHHmmssffff");
                _directoryPath = $"{AppDomain.CurrentDomain.BaseDirectory}\\{uniqueId}";

                try
                {
                    Directory.CreateDirectory(_directoryPath);
                    Environment.SetEnvironmentVariable("DIRECTORY_PATH", _directoryPath, EnvironmentVariableTarget.Process);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error creating directory: {ex}");
                }
            }
        }

        stopwatch.Stop();
        if (stopwatch.ElapsedMilliseconds > 10)
        {
            Console.WriteLine("Function took longer than 10 milliseconds to execute.");
        }
    }

    public string GetFirstElementFromXml(string xmlFilePath, string tagName)
    {
        Stopwatch stopwatch = new Stopwatch();
        stopwatch.Start();

        XmlDocument doc = new XmlDocument();
        try
        {
            doc.Load(xmlFilePath);
            var nodes = doc.GetElementsByTagName(tagName);
            if (nodes.Count == 0)
            {
                Console.WriteLine("No matching element found.");
                return null;
            }
            else if (nodes.Count > 1)
            {
                Console.WriteLine("Multiple elements found.");
                return null;
            }
            else
            {
                stopwatch.Stop();
                if (stopwatch.ElapsedMilliseconds > 10)
                {
                    Console.WriteLine("Function took longer than 10 milliseconds to execute.");
                }
                return nodes[0].InnerXml;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex}");
            return null;
        }
