<?php
function manageUserAccounts($request) {
    // Set timeout limit to 2 seconds
    set_time_limit(2);

    $db = new PDO('mysql:host=localhost;dbname=test', $user, $pass);
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    try {
        // Validate request fields
        $id = $request['id'] ?? null;
        $name = $request['name'] ?? null;
        $email = $request['email'] ?? null;
        $password = $request['password'] ?? null;
        $sub_action = $request['sub_action'] ?? null;

        if (!$id && $sub_action != 'create') {
            return json_encode(['message' => 'error']);
        }

        // Perform action based on sub_action
        switch ($sub_action) {
            case 'create':
                // Validate fields and create user account
                $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
                $stmt->execute([$name, $email, $password]);
                break;

            case 'update':
                // Validate fields and update user account
                $stmt = $db->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
                $stmt->execute([$name, $email, $password, $id]);
                break;

            case 'delete':
                // Validate and delete user account
                $stmt = $db->prepare("DELETE FROM users WHERE id = ?");
                $stmt->execute([$id]);
                break;

            case 'retrieve':
                // Retrieve user account data
                $stmt = $db->prepare("SELECT * FROM users WHERE id = ?");
                $stmt->execute([$id]);
                $userData = $stmt->fetch(PDO::FETCH_ASSOC);
                return json_encode(['message' => 'success', 'data' => $userData]);

            default:
                return json_encode(['message' => 'error']);
        }

    } catch (Exception $e) {
        // Handle exceptions and return error message
        if (strpos($e->getMessage(), 'timed out') !== false) {
            return json_encode(['message' => 'timeout']);
        } else {
            return json_encode(['message' => 'error', 'data' => $e->getMessage()]);
        }
    }

    // Return success message
    return json_encode(['message' => 'success']);
}
?>
```
