  try {
    const complaint = await Complaint.findById(req.params.id);
    client.setex(`complaint_${req.params.id}`, 60, JSON.stringify(complaint)); // Cache for 1 minute
    res.send(complaint);
  } catch (err) {
    res.status(500).send(err);
  }
});

