app.controller('MyController', ['$scope', '$window', '$timeout', function($scope, $window, $timeout) {
  $scope.processForwardList = function(forwardList, resourceId, url, timeoutValue) {
    var matchedFieldName;

    // Iterate through the forward list and find a matching field name
    for (var i = 0; i < forwardList.length; i++) {
      if (resourceId[forwardList[i]]) {
        matchedFieldName = forwardList[i];
        break;
      }
    }

    // If no matching field name is found, log a warning and return
    if (!matchedFieldName) {
      $timeout(function() {
        $window.console.warn('No matching field names were found within the specified timeout period');
        return;
      }, timeoutValue);
    }

    // If a matching field name is found, send a message to the parent window
    $scope.$on('message:success', function(event, data) {
      if (data.fieldName === matchedFieldName && data.resourceId === resourceId) {
        $window.parent.postMessage({ status: 'success', fieldName: matchedFieldName, value: data.value }, url);
      }
    });

    $scope.$on('message:failure', function(event, data) {
      if (data.fieldName === matchedFieldName && data.resourceId === resourceId) {
        $window.parent.postMessage({ status: 'failure' }, url);
      }
    });

    $timeout(function() {
      $window.parent.postMessage({ fieldName: matchedFieldName, resourceId: resourceId }, url);
    }, timeoutValue);
  };
}]);
