    private static final int MAX_CACHE_SIZE = 1024 * 1024; // 1MB
    private LruCache<String, Bitmap> mMemoryCache;
    private File cacheDir;

    public ThemeCacheManager(Context context) {
        // Get the default theme directory and verify it.
        String dirPath = getDefaultThemeDirectory();
        if (dirPath == null || !verifyThemeDirectory(dirPath)) {
            throw new IllegalStateException("Invalid theme directory");
        }

        cacheDir = new File(dirPath);
        mMemoryCache = new LruCache<String, Bitmap>(MAX_CACHE_SIZE) {
            @Override
            protected int sizeOf(String key, Bitmap bitmap) {
                return bitmap.getByteCount();
            }

            @Override
            protected void entryRemoved(boolean evicted, String key, Bitmap oldValue, Bitmap newValue) {
                super.entryRemoved(evicted, key, oldValue, newValue);

                // Recycle bitmaps when they are removed from the cache.
                if (oldValue != null && !oldValue.isRecycled()) {
                    oldValue.recycle();
                }
            }
        };
    }

