        return 1;
    }

    // Deserialize the byte array using the ObjectInputStream class
    jmethodID mid = (*env)->GetStaticMethodID(env, cls, "readObject", "([B)Ljava/lang/Object;");
    if (mid == NULL) {
        printf("Failed to find the readObject method.\n");
        return 1;
    }

    // Create a new jobjectArray for the byte array and copy the serialized object into it
    jbyteArray byteArray = (*env)->NewByteArray(env, objectSize);
    (*env)->SetByteArrayRegion(env, byteArray, 0, objectSize, (jbyte*)serializedObject);

    // Call the readObject method to deserialize the byte array
    jobject obj = (*env)->CallStaticObjectMethod(env, cls, mid, byteArray);
    if ((*env)->ExceptionCheck(env)) {
        printf("Failed to deserialize the object. Error: %p\n", (*env)->ExceptionOccurred(env));
        return 1;
    }

    // Clean up and detach the thread from the JavaVM
