        {
            Log("Web config file not found at: " + webConfigFilePath);
            return;
        }

        var memoryUsagePercentage = GetMemoryUsage();
        var diskSpacePercentage = GetDiskSpaceUsage();

        if (memoryUsagePercentage > 90 || diskSpacePercentage > 90)
        {
            Log("System resources are running low. Aborting operation.");
            return;
        }

        lock (_lock)
        {
            if (!Directory.Exists(appDir))
            {
                Directory.CreateDirectory(appDir);
            }
            else
            {
                Log("Application already exists at: " + appDir);
                return;
            }
        }

        var processStartInfo = new ProcessStartInfo
        {
            FileName = webConfigFilePath,
            UseShellExecute = true
