public static string ProcessAndHandleMessage(string encryptedBase64Message, ConnectionObject connection, byte[] tripleDesKey)
{
    if (String.IsNullOrEmpty(connection?.ServiceTitle))
    {
        throw new ArgumentException("Invalid service title");
    }

    if (String.IsNullOrEmpty(connection?.DecryptionPassword))
    {
        connection.ErrorCallback("Invalid decryption password");
        return String.Empty;
    }

    if (tripleDesKey == null)
    {
        throw new ArgumentException("Triple DES key cannot be null");
    }

    try
    {
        byte[] encryptedMessage = Convert.FromBase64String(encryptedBase64Message);

        using (TripleDES tripleDes = TripleDES.Create())
        {
            ICryptoTransform decryptor = tripleDes.CreateDecryptor(tripleDesKey, tripleDesKey[8..16]);

            byte[] decryptedBytes;

            using (MemoryStream memoryStream = new MemoryStream(encryptedMessage))
            using (CryptoStream cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
            {
                decryptedBytes = new byte[encryptedMessage.Length];
                int byteCount = cryptoStream.Read(decryptedBytes, 0, encryptedMessage.Length);

                if (byteCount < encryptedMessage.Length)
                {
                    connection.ErrorCallback("Decryption failed");
                    return String.Empty;
                }
            }

            string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);
            return decryptedMessage;
        }
    }
    catch (CryptographicException ex)
    {
        connection.ErrorCallback("Decryption failed: " + ex.Message);
        return String.Empty;
    }
}
```
This code uses the TripleDES encryption algorithm to decrypt a message. It also includes basic error handling and validation for the inputs. Note that this is a very simplified example, and real-world usage would require more robust error handling and security measures.
']

