#include <jansson.h>
#include <time.h>

bool validate_token(const char* token) {
    json_error_t error;
    json_t *root = json_loads(token, 0, &error);

    if(!json_is_object(root)) {
        json_decref(root);
        return false;
    }

    // Check for sub claim
    json_t* sub = json_object_get(root, "sub");
    if (!json_is_string(sub) || !json_string_length(sub)) {
        json_decref(root);
        return false;
    }

    // Check for iat claim
    json_t* iat = json_object_get(root, "iat");
    if (!json_is_integer(iat) || json_integer_value(iat) > time(NULL)) {
        json_decref(root);
        return false;
    }

    // Check for exp claim
    json_t* exp = json_object_get(root, "exp");
    if (!json_is_integer(exp) || json_integer_value(exp) <= time(NULL)) {
        json_decref(root);
        return false;
    }

    // Check for jti claim (optional)
    json_t* jti = json_object_get(root, "jti");
    if (jti && (!json_is_string(jti) || !json_string_length(jti))) {
        json_decref(root);
        return false;
    }

    // Check for jti uniqueness within the current session
