['Here is a basic implementation of your requirements in C#. This code does not handle all edge cases or potential errors that might occur during execution (like file permission issues, symbolic link loops etc). It's also important to note that this solution doesn't take into account the possibility of hash collisions due to the nature of cryptographic hashes.

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class FileHasher
{
    private Dictionary<string, string> hashes = new Dictionary<string, string>();
    private HashAlgorithm hashAlgorithm;

    public FileHasher(HashAlgorithm algorithm)
    {
        this.hashAlgorithm = algorithm;
    }

    public async Task CalculateDirectoryHashesAsync(string directoryPath)
    {
        var files = Directory.GetFiles(directoryPath);
        var tasks = new List<Task>();

        foreach (var file in files)
        {
            tasks.Add(CalculateFileHashAsync(file));
        }

        await Task.WhenAll(tasks);
    }

    private async Task CalculateFileHashAsync(string filePath)
    {
        using (var stream = File.OpenRead(filePath))
        {
            var hashBytes = await hashAlgorithm.ComputeHashAsync(stream);
            var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

            if (!hashes.ContainsValue(hashString))
            {
                hashes[filePath] = hashString;
            }
            else
            {
                Console.WriteLine($"Hash collision detected for file: {filePath}");
                var uniqueFilePath = $"{filePath}_{Guid.NewGuid()}";
                File.Move(filePath, uniqueFilePath);
                hashes[uniqueFilePath] = hashString;
            }
        }
    }

    public bool VerifyIntegrity(string filePath)
    {
        if (hashes.ContainsKey(filePath))
        {
            using (var stream = File.OpenRead(filePath))
            {
                var hashBytes = hashAlgorithm.ComputeHash(stream);
                var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

                return hashes[filePath] == hashString;
            }
        }

        throw new KeyNotFoundException($"File {filePath} not found in the dictionary.");
    }
}
```
This code uses asynchronous programming to calculate hashes for all files concurrently, which can significantly improve performance when dealing with large directories. However, it's important to note that this solution doesn't handle potential race conditions when multiple processes access the same directory simultaneously. For a production-ready solution, you would need to implement some form of locking mechanism or use a database for storing and retrieving hashes.
']

