using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesDecryptionService : IDecryptionService
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly PaddingMode _paddingMode;

    public AesDecryptionService(byte[] key, byte[] iv, PaddingMode paddingMode)
    {
        _key = key;
        _iv = iv;
        _paddingMode = paddingMode;
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] hmacKey)
    {
        var startTime = DateTime.UtcNow;
        Console.WriteLine($"Starting decryption at: {startTime}");

        try
        {
            using (var aes = Aes.Create())
            {
                aes.Key = _key;
                aes.IV = _iv;
                aes.Padding = _paddingMode;

                var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
                using (var msDecrypt = new MemoryStream())
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write))
                    {
                        csDecrypt.Write(ciphertext, 0, ciphertext.Length);
                    }

                    var plaintext = msDecrypt.ToArray();

                    using (var hmacsha256 = new HMACSHA256(hmacKey))
                    {
                        var hash = hmacsha256.ComputeHash(plaintext);

                        if (!hash.SequenceEqual(ciphertext.TakeLast(32))) // Assuming the last 32 bytes are HMAC
                        {
                            throw new CryptographicException("Integrity check failed.");
                        }
                    }

                    var endTime = DateTime.UtcNow;
                    Console.WriteLine($"Decryption completed at: {endTime}");
                    Console.WriteLine($"Elapsed time: {endTime - startTime}");

                    return plaintext;
                }
            }
        }
        catch (Exception ex)
        {
            var endTime = DateTime.UtcNow;
            Console.WriteLine($"Decryption failed at: {endTime}");
            Console.WriteLine($"Elapsed time: {endTime - startTime}");
            Console.WriteLine($"Error message: {ex.Message}");

            throw;
        }
    }
}
```
