["Here's a basic implementation of such a file upload handler in JavaScript using the `axios` library for HTTP requests, `bluebird` for promises, and `lodash` for utility functions. This code does not include integration with an external cloud storage service as it would require specific API keys or other credentials that are not provided here.

```javascript
const axios = require('axios');
const Promise = require('bluebird');
const _ = require('lodash');

class FileUploadHandler {
  constructor(file, options) {
    this.file = file;
    this.options = _.defaultsDeep({}, options, {
      maxConcurrent: 5,
      chunkSize: 1024 * 1024, // 1MB
      retries: 3,
      validate: {
        types: ['image/jpeg', 'image/png'],
        size: 1024 * 1024 * 5, // 5MB
      },
    });

    this.validate();
  }

  validate() {
    if (!this.options.validate.types.includes(this.file.type)) {
      throw new Error('Invalid file type');
    }

    if (this.file.size > this.options.validate.size) {
      throw new Error('File size exceeds limit');
    }
  }

  splitIntoChunks() {
    const chunks = [];
    for (let i = 0; i < this.file.size; i += this.options.chunkSize) {
      chunks.push(this.file.slice(i, Math.min(this.file.size, i + this.options.chunkSize)));
    }

    return chunks;
  }

  uploadChunk(chunk, retry = 0) {
    // Replace with actual cloud storage API call
    return axios.post('/upload', chunk).catch((error) => {
      if (retry < this.options.retries) {
        return this.uploadChunk(chunk, retry + 1);
      } else {
        throw error;
      }
    });
  }

  upload() {
    const chunks = this.splitIntoChunks();

    let concurrent = 0;
    return new Promise((resolve) => {
      const scheduleUpload = () => {
        while (concurrent < this.options.maxConcurrent && chunks.length > 0) {
          const chunk = chunks.shift();
          ++concurrent;

          this.uploadChunk(chunk).then(() => {
            --concurrent;
            scheduleUpload();
          }).catch((error) => {
            console.log('Failed to upload chunk', error);
            --concurrent;
            chunks.unshift(chunk); // Retry failed chunk later
            scheduleUpload();
          });
        }

        if (concurrent === 0 && chunks.length === 0) {
          resolve();
        }
      };

      scheduleUpload();
    });
  }
}
```

This code does not include logging, progress monitoring, or handling interruptions. These features would require additional implementation and may vary depending on the specific requirements of your application. Also, this is a basic example and might need to be adjusted based on the actual API of the cloud storage service you are using.
"]

