['Here is an example of how you might implement this in C using POSIX threads and getaddrinfo for DNS resolution. This code does not include error checking or handling for edge cases such as empty input or non-resolvable hostnames. It also doesn't handle memory management properly, which could lead to memory leaks if the function is called multiple times without freeing previously allocated memory.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <pthread.h>

void* get_ip(void *hostname) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[100];
    void *ptr;

    memset (&hints, 0, sizeof (hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo ((char*)hostname, NULL, &hints, &res);
    if (errcode != 0) {
        perror ("getaddrinfo");
        return NULL;
    }

    printf ("Host: %s\n",(char*)hostname);
    while (res) {
        inet_ntop (res->ai_family, res->ai_addr->sa_data, addrstr, 100);

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
                break;
            case AF_INET6:
                ptr = &((struct sockaddr_in6 *) res->ai_addr)->sin6_addr;
                break;
        }
        inet_ntop (res->ai_family, ptr, addrstr, 100);
        printf ("IPv%d address: %s (%s)\n", res->ai_family == PF_INET6 ? 6 : 4,
                addrstr, res->ai_canonname);
        res = res->ai_next;
    }

    freeaddrinfo(res);
    return NULL;
}

int main() {
    char hostname[1024];
    pthread_t thread;

    while (fgets(hostname, sizeof hostname, stdin)) {
        // Remove trailing newline
        hostname[strcspn(hostname, "\n")] = 0;

        if (pthread_create(&thread, NULL, get_ip, hostname) != 0) {
            perror("Failed to create thread");
            return 1;
        }

        pthread_join(thread, NULL);
    }

    return 0;
}
```
This code reads a list of hostnames from standard input and creates a new thread for each one. Each thread then resolves the hostname to an IP address using getaddrinfo. The main thread waits for all threads to finish before reading the next line from standard input. This ensures that we don't block while waiting for DNS resolution, but also allows us to handle multiple hostnames concurrently.
']

