    pthread_mutex_lock(&lock);

    // Add the new message to your array, handling memory allocation failures
    NFAPI_MESSAGE_PDU_T* temp = realloc(messages, sizeof(*messages) * (messageCount + 1));
    if (temp == NULL) {
