namespace CryptoUtils {
    class SecureRandomGenerator {
        static std::mt19937_64 rng;
        static bool isInitialized;

    public:
        SecureRandomGenerator(const std::string& seed) {
            if (!isInitialized) {
                RAND_seed(reinterpret_cast<const unsigned char*>(seed.c_str()), seed.size());
                rng.seed(std::random_device{}());
                isInitialized = true;
            }
        }

        ~SecureRandomGenerator() {
            // No need to release resources as std::mt19937_64 doesn't allocate any memory
        }

        static std::vector<unsigned int> generate(int count) {
            std::vector<unsigned int> numbers;
            for (int i = 0; i < count; ++i) {
                numbers.push_back(rng());
            }
            return numbers;
        }
    };

    // Static member variable initialization
    bool SecureRandomGenerator::isInitialized = false;
    std::mt19937_64 SecureRandomGenerator::rng;
}

int main() {
