['Here is an example of how you might structure such a module in C using OpenSSL library for AES encryption, PBKDF2 for password hashing, and SHA256 for HMAC. This code does not include all the details as it would be too large to fit here but it should give you a good starting point:

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <string.h>

// Define the size of the salt and key
#define SALT_SIZE 8
#define KEY_SIZE 32

typedef struct {
    unsigned char* password;
    unsigned char* salt;
} PasswordInfo;

PasswordInfo* createPassword(unsigned char* password) {
    PasswordInfo* info = malloc(sizeof(PasswordInfo));
    info->password = password;

    // Generate a random salt
    info->salt = malloc(SALT_SIZE);
    RAND_bytes(info->salt, SALT_SIZE);

    return info;
}

void destroyPassword(PasswordInfo* info) {
    // Zero out the password and salt to prevent it from lingering in memory
    memset(info->password, 0, strlen((char*)info->password));
    free(info->password);

    memset(info->salt, 0, SALT_SIZE);
    free(info->salt);

    free(info);
}

unsigned char* deriveKey(PasswordInfo* info) {
    unsigned char* key = malloc(KEY_SIZE);

    // Use PBKDF2 to derive a 32 byte key from the password and salt
    PKCS5_PBKDF2_HMAC_SHA1(info->password, strlen((char*)info->password), info->salt, SALT_SIZE, 1000, KEY_SIZE, key);

    return key;
}

EVP_CIPHER_CTX* initEncrypt(unsigned char* key) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL);

    return ctx;
}

void cleanupEncrypt(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

int encryptData(EVP_CIPHER_CTX* ctx, unsigned char* plaintext, int plaintextLen, unsigned char* ciphertext) {
    int len;

    // Encrypt the data
    EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintextLen);

    return len;
}
```
This is a simplified example and does not include error checking or handling of edge cases. In a real-world application, you would need to add appropriate error handling and consider other factors such as secure memory management, thread safety, etc. Also, the key derivation time can be reduced by increasing the number of iterations in PBKDF2 but this will increase memory usage. You should balance these trade-offs based on your specific requirements.
']

