#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_structures(int num) {
    srand(time(NULL));  // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(num * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structures == NULL) {
        return NULL;  // Failed to allocate memory
    }

    for (int i = 0; i < num; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand();
        structures[i].RNTI = rand();
        structures[i].CRC_INDICATION_REL8_TAG = rand();
        structures[i].CRCFLAG = rand() % 2;  // Randomly set CRCFLAG to either 0 or 1
    }

    return structures;
}
