Event* readEventsFromFile(const char* filename, int* eventCount) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open the file");
        return NULL;
    }

    Event* events = malloc(sizeof(Event));
    *eventCount = 0;

    while (!feof(file)) {
        time_t timestamp;
        int status;
        char details[256]; // Assuming the detail line won't exceed 256 characters.

        if (fscanf(file, "%ld %d %s", &timestamp, &status, details) != 3) {
            fclose(file);
            free(events);
            perror("Failed to read event from file");
            return NULL;
        }

        events = realloc(events, (*eventCount + 1) * sizeof(Event));
        Event* newEvent = &events[*eventCount];
        newEvent->timestamp = timestamp;
        newEvent->status = status;
        newEvent->details = malloc(strlen(details) + 1);
        strcpy(newEvent->details, details);

        (*eventCount)++;
    }

    fclose(file);
    return events;
}
