['Here is a basic implementation in C using pthreads for thread safety and glib for hash tables. This code does not include all of your requirements but it should give you a good starting point. 

```c
#include <stdio.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    int value;
} Record;

GHashTable* hash_table;
int max_memory = 0; // in bytes
int current_memory = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_record(long offset, int key, Record record) {
    pthread_mutex_lock(&lock);

    if (current_memory + sizeof(Record) > max_memory) {
        printf("Memory allocation failed: Max memory limit exceeded.\n");
        return;
    }

    current_memory += sizeof(Record);
    g_hash_table_insert(hash_table, GINT_TO_POINTER(key), record);

    pthread_mutex_unlock(&lock);
}

void* get_record(int key) {
    pthread_mutex_lock(&lock);

    void* result = g_hash_table_lookup(hash_table, GINT_TO_POINTER(key));

    pthread_mutex_unlock(&lock);

    return result;
}

void serialize() {
    FILE* file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Failed to open file for writing.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    GHashTableIter iter;
    gpointer key, value;
    g_hash_table_iter_init(&iter, hash_table);
    while (g_hash_table_iter_next(&iter, &key, &value)) {
        fwrite(value, sizeof(Record), 1, file);
    }

    pthread_mutex_unlock(&lock);

    fclose(file);
}

void deserialize() {
    FILE* file = fopen("data.bin", "rb");
    if (file == NULL) {
        printf("Failed to open file for reading.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    Record record;
    while (fread(&record, sizeof(Record), 1, file)) {
        g_hash_table_insert(hash_table, GINT_TO_POINTER(record.value), record);
    }

    pthread_mutex_unlock(&lock);

    fclose(file);
}
```
This code does not include the garbage collection or flexible configuration options you requested. It also doesn't handle concurrent access from multiple threads, which would require a more complex solution using locks or other synchronization primitives. 

Please note that this is a simplified example and may need to be adapted for your specific use case. For instance, the serialization/deserialization functions assume that each record fits into memory as a single unit, which might not be true in all cases. You would need to adjust these functions based on how you plan to store records in the file.
']

