ConfigurationProfile* generateConfig(NetworkTopology* topology, bool includeConnectedOnly) {
    pthread_mutex_lock(&lock); // Lock to ensure thread-safety.

    if (topology == NULL || topology->num_nodes == 0) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    ConfigurationProfile* profile = malloc(sizeof(ConfigurationProfile));
    if (profile == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL; // Insufficient memory.
    }

    profile->num_nodes = 0;
    profile->nodes = malloc(topology->num_nodes * sizeof(Node*));
    if (profile->nodes == NULL) {
        free(profile);
        pthread_mutex_unlock(&lock);
        return NULL; // Insufficient memory.
    }

    for (int i = 0; i < topology->num_nodes; ++i) {
        Node* node = malloc(sizeof(Node));
        if (node == NULL) {
            free(profile);
            pthread_mutex_unlock(&lock);
            return NULL; // Insufficient memory.
        }

        // Initialize the node properties...

        profile->nodes[i] = node;
        profile->num_nodes++;
    }

    pthread_mutex_unlock(&lock);
    return profile;
}
