["Here is an example of how you might implement this function using OpenSSL library in C. This code assumes that you have already included necessary headers and linked against OpenSSL library. 

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdlib.h>

#define MAX_PASSWORD_LEN 128
#define MAX_SALT_LEN 32
#define MAX_KEY_LEN EVP_MAX_KEY_LENGTH
#define MAX_IV_LEN EVP_MAX_IV_LENGTH

typedef struct {
    unsigned char *key;
    unsigned char *iv;
} AES_CBC_CTX;

AES_CBC_CTX* init_aes_cbc(const char *password, size_t passwordLen) {
    if (passwordLen > MAX_PASSWORD_LEN || !password) {
        return NULL;
    }

    AES_CBC_CTX *ctx = malloc(sizeof(AES_CBC_CTX));
    ctx->key = malloc(MAX_KEY_LEN);
    ctx->iv = malloc(MAX_IV_LEN);

    if (!RAND_bytes(ctx->iv, MAX_IV_LEN) || !EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (const unsigned char*)password, passwordLen, 1, ctx->key, ctx->iv)) {
        free(ctx->key);
        free(ctx->iv);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void destroy_aes_cbc(AES_CBC_CTX *ctx) {
    if (!ctx) {
        return;
    }

    memset(ctx->key, 0, MAX_KEY_LEN);
    free(ctx->key);

    memset(ctx->iv, 0, MAX_IV_LEN);
    free(ctx->iv);

    free(ctx);
}
```
This code provides a simple way to initialize an AES-256-CBC cipher with a given password. The `init_aes_cbc` function allocates memory for the derived key and initialization vector, then derives these values from the provided password using OpenSSL's `EVP_BytesToKey` function.

The `destroy_aes_cbc` function is used to safely dispose of cryptographic resources when the cipher is no longer in use. It zeroizes the key and IV before freeing them, preventing sensitive data from remaining in memory after they are no longer needed.

