#include <time.h>

typedef struct {
    int value;
    long* offsets;
    int* keys;
} Record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    Record** records;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->records = calloc(initial_capacity, sizeof(Record*));
    if (table->records == NULL) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void insert(HashTable* table, Record* record) {
    if (table->count == table->capacity) {
        // Resize the hash table and rehash all records
        pthread_mutex_lock(&table->lock);

        size_t new_capacity = table->capacity * 2;
        Record** new_records = calloc(new_capacity, sizeof(Record*));
        if (new_records == NULL) {
            pthread_mutex_unlock(&table->lock);
            return;
        }

        for (size_t i = 0; i < table->count; ++i) {
            size_t hash = record->value % new_capacity; // Simple hash function

            while (new_records[hash] != NULL) {
                hash = (hash + 1) % new_capacity;
            }

            new_records[hash] = table->records[i];
        }

        free(table->records);
        table->records = new_records;
        table->capacity = new_capacity;

        pthread_mutex_unlock(&table->lock);
    }

    size_t hash = record->value % table->capacity; // Simple hash function

    while (table->records[hash] != NULL) {
        hash = (hash + 1) % table->capacity;
    }

    table->records[hash] = record;
}

// Other functions like delete, search etc. would be similar to insert function
