#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AES_params;

void handleErrors(void) { /* Error handling code */ }

int aes_init(AES_params *params, const char* password, int keylen, const unsigned char* salt, int ivlen) {
    if(!RAND_bytes(params->iv, ivlen)) return 0;

    /* Derive the key from the password */
    if(!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt), 1000, EVP_sha256(), keylen, params->key)) return 0;

    /* Initialize the encryption context */
    if(!(params->ctx = EVP_CIPHER_CTX_new())) handleErrors();

    return 1;
}

int aes_encrypt(AES_params *params, unsigned char* plaintext, int len, unsigned char* ciphertext) {
    if(!EVP_EncryptInit_ex(params->ctx, EVP_aes_256_cbc(), NULL, params->key, params->iv)) handleErrors();

    /* Encrypt the plaintext */
    int ciphertext_len;
    if(!EVP_EncryptUpdate(params->ctx, ciphertext, &ciphertext_len, plaintext, len)) handleErrors();

    return ciphertext_len;
}

int aes_decrypt(AES_params *params, unsigned char* ciphertext, int len, unsigned char* plaintext) {
    if(!EVP_DecryptInit_ex(params->ctx, EVP_aes_256_cbc(), NULL, params->key, params->iv)) handleErrors();

    /* Decrypt the ciphertext */
    int plaintext_len;
    if(!EVP_DecryptUpdate(params->ctx, plaintext, &plaintext_len, ciphertext, len)) handleErrors();

    return plaintext_len;
}

void aes_cleanup(AES_params *params) {
    EVP_CIPHER_CTX_free(params->ctx);
}
```
