void connectAndFetchEmployeeDetails(char* dbPath, char* supervisorId) {
    sqlite3 *db;
    int rc = sqlite3_open(dbPath, &db);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        exit(-1);
    }

    // Prepare parameterized query to fetch employee details where supervisor's ID matches input
    char *query = "SELECT names, cities, addresses FROM employees WHERE supervisorId = ?";
    sqlite3_stmt *res;
    rc = sqlite3_prepare_v2(db, query, -1, &res, 0);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(db));
        exit(-1);
    }

    // Bind supervisorId parameter and execute query
    rc = sqlite3_bind_text(res, 1, supervisorId, -1, SQLITE_STATIC);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to bind text: %s\n", sqlite3_errmsg(db));
        exit(-1);
    }

    // Fetch and print employee details
    while ((rc = sqlite3_step(res)) == SQLITE_ROW) {
        char *name = (char *)sqlite3_column_text(res, 0);
        char *city = (char *)sqlite3_column_text(res, 1);
        char *address = (char *)sqlite3_column_text(res, 2);

        printf("Name: %s\nCity: %s\nAddress: %s\n", name, city, address);
    }

    // Finalize and close database connection
    sqlite3_finalize(res);
    sqlite3_close(db);
}
```

