["This task is quite complex and involves multiple aspects such as dynamic memory allocation, concurrent access management, logging, serialization, checkpointing, performance evaluation etc. Here's a simplified version of how you might start implementing some parts of it in C. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    atomic_int size;
    pthread_mutex_t lock;
    Record **records;
} Collection;

Collection *collection = NULL;

void addRecord(int key, long offset) {
    if (collection == NULL) {
        collection = malloc(sizeof(Collection));
        atomic_init(&collection->size, 0);
        pthread_mutex_init(&collection->lock, NULL);
        collection->records = calloc(1, sizeof(Record*));
    } else {
        pthread_mutex_lock(&collection->lock);
    }

    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;

    int currentSize = atomic_load(&collection->size);
    collection->records = realloc(collection->records, (currentSize + 1) * sizeof(Record*));
    collection->records[currentSize] = record;

    atomic_fetch_add(&collection->size, 1);

    if (collection != NULL) {
        pthread_mutex_unlock(&collection->lock);
    }
}
```
This is a simplified version of how you might start implementing some parts of it in C. The actual implementation would be much more complex and would require careful consideration of all the aspects mentioned in the task description. 

