typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

int init_cipher(const char* password, const unsigned char* salt, CipherContext* cipher) {
    int rv = 0;
    unsigned char key[32]; // 256 bits for AES-256

    if (!RAND_bytes(cipher->iv, EVP_MAX_IV_LENGTH)) goto cleanup;

    /* Derive a 256 bit key from the password */
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, strlen((char*)salt), 20000, EVP_sha256(), 32, key)) goto cleanup;

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (cipher->ctx == NULL) goto cleanup;

    /* Initialize the encryption operation. */
    if (!EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, key, cipher->iv)) goto cleanup;

    rv = 1; // success
cleanup:
    OPENSSL_cleanse(key, sizeof(key));
    return rv;
}

void cleanup_cipher(CipherContext* cipher) {
    if (cipher->ctx != NULL) EVP_CIPHER_CTX_free(cipher->ctx);
    OPENSSL_cleanse(cipher->iv, sizeof(cipher->iv));
}
```
This code initializes an AES-256-CBC cipher with a given password using PBKDF2 to derive the key. It also generates a random IV and stores it in the `CipherContext` struct for later use. The cleanup function securely disables the cipher context and frees all associated resources.

