['Here is a basic implementation of your requirements using C with libcurl for HTTP requests, jansson for parsing JSON, and glib for caching and other utilities. This code does not include all the features you requested (like authentication, rate limiting, nested JSON support etc.), but it should give you a good starting point:

```c
#include <stdio.h>
#include <string.h>
#include <curl/curl.h>
#include <jansson.h>
#include <glib.h>

typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

json_t *getConfigDataFromURL(char *url) {
    CURL *curl_handle;
    CURLcode res;

    struct MemoryStruct chunk;

    chunk.memory = malloc(1);  
    chunk.size = 0; 

    curl_global_init(CURL_GLOBAL_ALL);

    /* init the curl session */
    curl_handle = curl_easy_init();

    /* specify URL to get */
    curl_easy_setopt(curl_handle, CURLOPT_URL, url);

    /* send all data to this function  */
    curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);

    /* we pass our 'chunk' struct to the callback function */
    curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)&chunk);

    /* some servers don't like requests that are made without a user-agent field, so we provide one */
    curl_easy_setopt(curl_handle, CURLOPT_USERAGENT, "libcurl-agent/1.0");

    res = curl_easy_perform(curl_handle);

    /* check for errors */
    if(res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
        json_t *root = json_loads(chunk.memory, 0, NULL);
        free(chunk.memory);
        return root;
    }

    /* cleanup curl stuff */
    curl_easy_cleanup(curl_handle);

    return NULL;
}

int main() {
    char *url = "http://example.com/config";
    json_t *root = getConfigDataFromURL(url);

    if (root) {
        // Process the JSON data here...

        json_decref(root);
    } else {
        printf("Failed to retrieve configuration data from URL: %s\n", url);
    }

    return 0;
}
```
This code uses libcurl for HTTP requests and jansson for JSON parsing. It retrieves the JSON data from a remote URL, parses it into a json_t object, and then processes this data as needed. The memory allocated for the JSON string is freed after processing to prevent memory leaks. 

Please note that this code does not include all the features you requested (like authentication, rate limiting, nested JSON support etc.), but it should give you a good starting point. You would need to add these features yourself or use additional libraries as needed.
