["Here is an example of how you might start implementing such a system in C. This code does not cover all the requirements mentioned above but it provides a basic framework for building a modular data processing pipeline. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Data {
    int value;
    struct Data *next;
} Data;

typedef struct Buffer {
    pthread_mutex_t lock;
    Data *head;
    Data *tail;
    size_t size;
    size_t maxSize;
} Buffer;

Buffer* createBuffer(size_t maxSize) {
    Buffer *buffer = malloc(sizeof(Buffer));
    buffer->maxSize = maxSize;
    buffer->head = NULL;
    buffer->tail = NULL;
    buffer->size = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void addData(Buffer *buffer, int value) {
    Data *data = malloc(sizeof(Data));
    data->value = value;
    data->next = NULL;

    pthread_mutex_lock(&buffer->lock);
    if (buffer->head == NULL) {
        buffer->head = data;
        buffer->tail = data;
    } else {
        buffer->tail->next = data;
        buffer->tail = data;
    }
    ++buffer->size;
    pthread_mutex_unlock(&buffer->lock);
}

int getData(Buffer *buffer) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->head == NULL) {
        pthread_mutex_unlock(&buffer->lock);
        return -1; // Return a special value to indicate buffer is empty.
    } else {
        Data *data = buffer->head;
        int value = data->value;
        buffer->head = data->next;
        if (buffer->head == NULL) {
            buffer->tail = NULL;
        }
        --buffer->size;
        pthread_mutex_unlock(&buffer->lock);
        free(data);
        return value;
    }
}
```
This is a simple implementation of a thread-safe queue (Buffer) in C. It supports adding data to the end and retrieving data from the front. 

