#include <stdio.h>
#include <dlfcn.h>

typedef struct {
    void *handle;
    char *(*hash_function)(const char*);
} Module;

Module load_module(const char *path) {
    Module module = {0};

    // Load the module
    module.handle = dlopen(path, RTLD_LAZY);
    if (!module.handle) {
        fprintf(stderr, "Failed to load module: %s\n", dlerror());
        return module;
    }

    // Get the hash function from the module
    module.hash_function = (char *(*)(const char*))dlsym(module.handle, "hash_function");
    if (!module.hash_function) {
        fprintf(stderr, "Failed to get hash function: %s\n", dlerror());
        return module;
    }

    return module;
}

void unload_module(Module *module) {
    if (module->handle) {
        dlclose(module->handle);
        module->handle = NULL;
        module->hash_function = NULL;
    }
}
```
This is a very basic example of how you might load and unload modules at runtime in C. It uses the `dlopen`, `dlsym`, and `dlclose` functions from the dynamic linking library (`libdl`) to open a module, get a function pointer for a hash function, and close the module respectively.

