class RandomUtil {
public:
    RandomUtil(unsigned int seed = std::mt19937::default_seed) : gen_(seed) {}
    ~RandomUtil() {}

    unsigned int getRandomNumber() {
        std::lock_guard<std::mutex> lock(mutex_); // Ensure thread-safety
        return gen_();
    }

    static std::string stringToMD5Hash(const std::string& str) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)str.c_str(), str.size(), digest);    

        return toHexString(digest, MD5_DIGEST_LENGTH);
    }

private:
    std::mt19937 gen_;
    static std::mutex mutex_; // Mutex for thread-safety

    static std::string toHexString(const unsigned char* bytes, size_t len) {
        std::stringstream ss;
        for (size_t i = 0; i < len; ++i) {
            ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(bytes[i]);
        }
        return ss.str();
    }
};

std::mutex RandomUtil::mutex_; // Initialize the mutex
```
