['Here is a basic implementation of such a method in C#. This code does not cover all your requirements but it gives you an idea on how to start implementing them. 

```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;

public class SqlQueryExecutor
{
    private readonly string _connectionString;
    private readonly IConfiguration _configuration;

    public SqlQueryExecutor(IConfiguration configuration)
    {
        _configuration = configuration;
        _connectionString = _configuration.GetConnectionString("DefaultConnection");
    }

    public async Task ExecuteSqlCommandAsync(string commandTemplate, params object[] parameters)
    {
        var sw = Stopwatch.StartNew();
        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();

                using (var command = new SqlCommand(commandTemplate, connection))
                {
                    for (int i = 0; i < parameters.Length; i++)
                    {
                        var parameterValue = parameters[i];

                        if (parameterValue is DateTime dateTimeValue)
                            command.Parameters.AddWithValue($"@p{i}", dateTimeValue);
                        else if (parameterValue is int intValue)
                            command.Parameters.AddWithValue($"@p{i}", intValue);
                        else if (parameterValue is string stringValue)
                            command.Parameters.AddWithValue($"@p{i}", stringValue);
                    }

                    await command.ExecuteNonQueryAsync();
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message);
        }
        finally
        {
            sw.Stop();
            Console.WriteLine($"Execution time: {sw.ElapsedMilliseconds} ms");
        }
    }
}
```
This code uses the `SqlConnection` and `SqlCommand` classes from the `System.Data.SqlClient` namespace to interact with a SQL Server database. It also uses the `Stopwatch` class from the `System.Diagnostics` namespace to measure execution time. 

