['Here is a basic outline for your C# program. This code does not cover all aspects you mentioned due to complexity but it gives an idea about how you can start implementing this kind of distributed session registry in C#. 

```csharp
using System;
using System.Collections.Generic;
using System.Threading;
using StackExchange.Redis; // You need to install this package via NuGet

public class SessionRegistry
{
    private static readonly Lazy<ConnectionMultiplexer> lazyConnection = new Lazy<ConnectionMultiplexer>(() =>
    {
        return ConnectionMultiplexer.Connect("localhost"); // Replace with your Redis connection string
    });

    public static ConnectionMultiplexer Connection
    {
        get
        {
            return lazyConnection.Value;
        }
    }

    private IDatabase _db = Connection.GetDatabase();

    private Dictionary<string, Session> _sessions = new Dictionary<string, Session>();

    public void AddSession(Session session)
    {
        if (_sessions.ContainsKey(session.Id))
            throw new Exception("Duplicate session id");

        // Use Redis transaction to ensure atomicity
        _db.HashSetAsync("sessions", session.Id, session);

        lock(_sessions)
        {
            _sessions[session.Id] = session;
        }
    }

    public Session GetSession(string id)
    {
        if (!_sessions.ContainsKey(id))
            throw new Exception("Session not found");

        return _sessions[id];
    }
}

public class Session
{
    public string Id { get; set; }
    public string UserRole { get; set; }
    public DateTime LastActiveTimestamp { get; set; }
    public int StatusCode { get; set; }
}
```
