['Here is a basic implementation of your request using Node.js with Express framework. This code does not include all the features you requested but it gives an idea about how you can implement them. 

```javascript
const express = require('express');
const bodyParser = require('body-parser');
const rateLimit = require("express-rate-limit");
const Ajv = require('ajv');
const ajv = new Ajv(); // options can be passed, e.g. {allErrors: true}

// Initialize express app
const app = express();
app.use(bodyParser.json());

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 50, // limit each IP to 50 requests per windowMs
});
app.use(limiter);

// Mock data
let resources = [{ id: 1, name: 'Resource 1' }, { id: 2, name: 'Resource 2' }];

// PUT endpoint
app.put('/resources/:id', (req, res) => {
    const schema = {
        type: "object",
        properties: {
            name: { type: "string" },
        },
        required: ["name"],
        additionalProperties: false,
    };

    // Validate request body against schema
    if (!ajv.validate(schema, req.body)) {
        return res.status(400).json({ error: 'Invalid request body' });
    }

    const resourceIndex = resources.findIndex((resource) => resource.id === parseInt(req.params.id));

    if (resourceIndex !== -1) {
        // Update the resource
        resources[resourceIndex] = { ...resources[resourceIndex], ...req.body };

        return res.json({ message: 'Resource updated', data: resources[resourceIndex] });
    } else {
        return res.status(404).json({ error: 'Resource not found' });
    }
});

// DELETE endpoint
app.delete('/resources/:id', (req, res) => {
    const resourceIndex = resources.findIndex((resource) => resource.id === parseInt(req.params.id));

    if (resourceIndex !== -1) {
        // Remove the resource
        resources.splice(resourceIndex, 1);

        return res.json({ message: 'Resource deleted' });
    } else {
        return res.status(404).json({ error: 'Resource not found' });
    }
});

// Start server
app.listen(3000, () => console.log('Server started on port 3000'));
```
