pub fn request_builder(url: &str, disable_certificate_validation: bool) -> Result<hyper::client::RequestBuilder, io::Error> {
    let connector = if disable_certificate_validation {
        HttpsConnector::new()?.disable_tls().unwrap();
    } else {
        HttpsConnector::new()?;
    };

    Ok(hyper::client::Client::builder()
        .connector(HttpConnector::new(connector))
        .build()?
        .get(url))
}

pub fn compile_crate(path: &str) -> (process::ExitStatus, u64) {
    let start = Instant::now();

    let mut hooks = rustc_driver::Hooks::new();
    hooks.register("log", |_, _| {
        info_hook(path);
        0
    });

    let exit_code = catch_with_exit_code(|| {
        rustc_driver::compile(&[path], &hooks)?;
        Ok(())
    }).unwrap();

    let elapsed = start.elapsed().as_secs();
    (exit_code, elapsed)
}

fn info_hook(_: &str) {
    // Implement your logging hook here
}

pub fn main() -> Result<(hyper::client::RequestBuilder, process::ExitStatus), io::Error> {
