['```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using UnityEngine;

public class RandomValueGenerator
{
    private int minValue;
    private int maxValue;
    private string characterSet;

    public RandomValueGenerator(int min, int max, string charSet)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        this.minValue = min;
        this.maxValue = max;
        this.characterSet = charSet;
    }

    public int GenerateRandomInteger(bool inclusive = true)
    {
        if (inclusive)
            return UnityEngine.Random.Range(this.minValue, this.maxValue + 1);

        return UnityEngine.Random.Range(this.minValue + 1, this.maxValue);
    }

    public float GenerateRandomFloat(bool inclusive = true)
    {
        if (inclusive)
            return UnityEngine.Random.Range((float)this.minValue, (float)(this.maxValue + 1));

        return UnityEngine.Random.Range((float)(this.minValue + 1), (float)this.maxValue);
    }

    public string GenerateSecureString(int length)
    {
        if (length <= 0)
            throw new ArgumentException("Length must be greater than zero.");

        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < length; i++)
        {
            int index = UnityEngine.Random.Range(0, this.characterSet.Length);
            builder.Append(this.characterSet[index]);
        }

        return HashString(builder.ToString());
    }

    private string HashString(string input)
    {
        using (SHA256 sha256Hash = SHA256.Create())
        {
            byte[] bytes = sha256Hash.ComputeHash(Encoding.UTF8.GetBytes(input));

            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < bytes.Length; i++)
                builder.Append(bytes[i].ToString("x2"));

            return builder.ToString();
        }
    }

    public override string ToString()
    {
        return $"RandomValueGenerator: [{this.minValue}, {this.maxValue}]";
    }
}
```
']

