["Here is an example of how you might implement this in C++ using `std::unique_ptr` for memory management. This is a simplified version and does not include all the requirements mentioned above. It's important to note that implementing an octree data structure from scratch can be quite complex, especially when considering performance constraints, thread safety, scalability, and integration with other components of the application.

```cpp
#include <memory>
#include <vector>
#include <mutex>

struct OctreeNode {
    std::unique_ptr<OctreeNode[]> children;
    int featureSize;
    int dataCapacity;
};

class Octree {
public:
    Octree(int featureSize, int leafNodes, int dataCapacity) 
        : root_(std::make_unique<OctreeNode>()) {
        root_->featureSize = featureSize;
        root_->dataCapacity = dataCapacity;

        // Allocate memory for the octree based on leaf nodes and feature size.
        root_->children = std::make_unique<OctreeNode[]>(leafNodes * featureSize);
    }

    void addLeafNode() {
        std::lock_guard<std::mutex> lock(mutex_);

        // Reallocate memory if necessary.
        if (++numLeafNodes_ > root_->dataCapacity) {
            auto newRoot = std::make_unique<OctreeNode[]>(root_->dataCapacity * 2);

            for (int i = 0; i < numLeafNodes_; ++i) {
                newRoot[i] = std::move(root_->children[i]);
            }

            root_ = std::move(newRoot);
        }

        // Add a new leaf node.
        root_->children[numLeafNodes_ - 1] = std::make_unique<OctreeNode>();
    }

    void removeLeafNode() {
        std::lock_guard<std::mutex> lock(mutex_);

        if (--numLeafNodes_ < root_->dataCapacity / 2) {
            auto newRoot = std::make_unique<OctreeNode[]>(root_->dataCapacity / 2);

            for (int i = 0; i < numLeafNodes_; ++i) {
                newRoot[i] = std::move(root_->children[i]);
            }

            root_ = std::move(newRoot);
        }
    }

private:
    std::unique_ptr<OctreeNode[]> root_;
    int numLeafNodes_ = 0;
