const bunyan = require('bunyan');
const async = require('async');

// Create logger
let log = bunyan.createLogger({name: 'myapp'});

class LogProcessor {
    constructor(config) {
        this.config = config;
        this.queue = async.queue((logEntry, callback) => {
            try {
                // Filter out logs with a severity level below threshold
                if (this.config.thresholdLevels.includes(logEntry.level)) {
                    logEntry.timestamp = new Date().toISOString();  // Standardize timestamp format

                    // Extract additional metadata fields dynamically based on the log's content and external configuration
                    for (let field of this.config.dynamicFields) {
                        if (logEntry[field]) {
                            logEntry['extracted_' + field] = logEntry[field];
                            delete logEntry[field];
                        }
                    }

                    // Log the processed entry
                    log.info(logEntry, 'Processed log entry');
                }

                callback();  // Indicate that the task is complete
            } catch (error) {
                log.error(error);
                callback(error);  // Retry the task if an error occurred
            }
        });

        this.queue.drain = () => {
            log.info('All logs have been processed');
        };
    }

    processLogs(logEntries) {
        for (let entry of logEntries) {
            this.queue.push(entry);  // Add each log to the queue
        }
    }
}
