```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int RNTI_MIN = 0, RNTI_MAX = 1023; // Default range for validation

void updateRNTIRange(int newMin, int newMax) {
    pthread_mutex_lock(&lock);
    RNTI_MIN = newMin;
    RNTI_MAX = newMax;
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* createList(int M) {
    srand(time(NULL)); // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(M * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < M; ++i) {
        list[i].RX_UE_INFORMATION_TAG = i + 1; // Set a unique tag

        int RNTI;
        do {
            RNTI = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN; // Generate a random RNTI within the valid range
        } while (isDuplicate(list, i, RNTI)); // Ensure no duplicates

        list[i].RNTI = RNTI;
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
    pthread_mutex_unlock(&lock);

    return list;
}

int isDuplicate(NFAPI_CRC_INDICATION_PDU_T* list, int size, int RNTI) {
    for (int i = 0; i < size; ++i) {
        if (list[i].RNTI == RNTI) {
            return 1; // Duplicate found
        }
    }

    return 0; // No duplicate found
}
