// crypto_module_loader.c
#include <dlfcn.h>
#include "crypto_module.h"
#include "crypto_module_loader.h"

CryptoModule* loadModule(const char* moduleName) {
    void* handle = dlopen(moduleName, RTLD_LAZY);
    if (!handle) return NULL;

    CryptoModule* (*getModule)(void) = (CryptoModule* (*)(void))dlsym(handle, "getModule");
    char* error = dlerror();
    if (error != NULL) {
        // Handle the error...
        return NULL;
    }

    CryptoModule* module = getModule();
    module->cleanup = handle;
    return module;
}

void unloadModule(CryptoModule* module) {
    dlclose(module->cleanup);
    free(module);
}
```

