                    continue; // Skip this file and move on to the next one
                }
            }
        }

        closedir (dir);
    } else {
        fprintf(stderr, "Could not open directory: %s\n", strerror(errno));
        return -1; // Return error code
    }

    return 0; // Success
}
```
