```c
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/resource.h>
#include <signal.h>

typedef struct {
    int id;
    char* command;
    int priority;
    double cpu_usage;
    double memory_usage;
} CommandInfo;

void* executeCommand(void *arg) {
    CommandInfo *info = (CommandInfo*) arg;

    // Execute the command in a separate namespace using fork and exec.
    pid_t pid = fork();
    if (pid == 0) {  // Child process
        execl("/bin/sh", "sh", "-c", info->command, NULL);
        _exit(0);  // If exec fails, exit the child process.
    } else if (pid < 0) {
        printf("Failed to fork.\n");
        return NULL;
    }

    int status = 0;
    waitpid(pid, &status, 0);  // Wait for the command to finish.

    struct rusage usage;
    getrusage(RUSAGE_CHILDREN, &usage);  // Get resource usage information.

    info->cpu_usage = (double) usage.ru_utime.tv_sec + ((double) usage.ru_utime.tv_usec / 1000000);
    info->memory_usage = (double) usage.ru_maxrss;

    return NULL;
}

void* manageCommands(void *arg) {
    CommandInfo commands[] = {{1, "ls", 2}, {2, "sleep 5", 1}};
    int num_commands = sizeof(commands) / sizeof(CommandInfo);

    pthread_t threads[num_commands];
    for (int i = 0; i < num_commands; ++i) {
        pthread_create(&threads[i], NULL, executeCommand, &commands[i]);
    }

    // Wait for all commands to finish.
    for (int i = 0; i < num_commands; ++i) {
        pthread_join(threads[i], NULL);
    }

    return commands;  // Return the array of command info structures.
}

void sigHandler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    exit(0);
}

int main() {
    void* result = NULL;

    // Set up a signal handler for graceful shutdown.
    struct sigaction action;
    action.sa_handler = sigHandler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);  // Handle SIGINT (Ctrl+C)

    pthread_t thread;
    pthread_create(&thread, NULL, manageCommands, NULL);
    pthread_join(thread, &result);

    CommandInfo* commands = (CommandInfo*) result;
    int num_commands = sizeof(commands) / sizeof(CommandInfo);

    // Print the command info structures.
    for (int i = 0; i < num_commands; ++i) {
        printf("ID: %d, CPU usage: %f, Memory usage: %f\n", commands[i].id, 
               commands[i].cpu_usage, commands[i].memory_usage);
    }

    return 0;
}
```
This code is a simplified example and does not include all the requested features. It's recommended to use an existing job scheduler or container orchestration system for production-grade solutions. The code also lacks error handling, proper resource management, priority scheduling, timeout mechanism, and other advanced features.
