#include <stdio.h>
#include <string.h>
#include <json-c/json.h>
#include <curl/curl.h>
#include <pthread.h>

// Define a mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

struct memory {
    char *response;
    size_t size;
};

size_t callback(void *data, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct memory *mem = (struct memory *)userp;

    char *ptr = realloc(mem->response, mem->size + realsize + 1);
    if(ptr == NULL)
        return 0;  

    mem->response = ptr;
    memcpy(&(mem->response[mem->size]), data, realsize);
    mem->size += realsize;
    mem->response[mem->size] = 0;

    return realsize;
}

void *handle_request(void *arg) {
    char error[1056];
    struct memory chunk = {0};

    CURL *curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com");

        // Set callback function and data pointer for response handling
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        // Set error buffer and error handling function
        curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, error);

        CURLcode res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("%lu bytes retrieved\n", (long)chunk.size);
        }

        curl_easy_cleanup(curl);
    }

    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    // Create two threads to handle requests concurrently
    if (pthread_create(&thread1, NULL, &handle_request, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    if (pthread_create(&thread2, NULL, &handle_request, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    // Wait for threads to finish
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
```
This code creates two threads that handle HTTP requests concurrently. It uses libcurl to send the request and retrieve the response, and it uses a mutex for thread safety. The callback function is used to handle the response data. Please note that this is just a basic example and does not include all the functionalities you requested such as JSON parsing, error handling, database operations etc.
