                        {
                            T item = (T)bf.Deserialize(ms);

                            if (!ValidateItem(item))
                            {
                                Console.WriteLine("Invalid data encountered during deserialization.");
                                continue;
                            }

                            AddItem(item);
                        }
                    }
                }

                return; // Successfully loaded and deserialized the file
            }
            catch (WebException ex) when ((ex.Response as HttpWebResponse)?.StatusCode == HttpStatusCode.ServiceUnavailable)
            {
                Console.WriteLine("External service is currently unavailable, retrying...");

                // Wait for a bit before retrying
