#include <pthread.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG* crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* list = NULL;
int listSize = 0;

void* customAlloc(size_t size) {
    pthread_mutex_lock(&lock);
    void* block = malloc(size);
    if (block == NULL && list != NULL) {
        for (int i = 0; i < listSize; ++i) {
            if (list[i].crc_tag != NULL) {
                free(list[i].crc_tag);
                list[i].crc_tag = NULL;
                block = malloc(size);
                if (block != NULL) break;
            }
        }
    }
    pthread_mutex_unlock(&lock);
    return block;
}

void addToList(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T* newStruct = customAlloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newStruct == NULL) {
        // handle error: memory allocation failed
        return;
    }

    CRC_INDICATION_REL8_TAG* newTag = customAlloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (newTag == NULL) {
        free(newStruct); // clean up the allocated memory
        // handle error: memory allocation failed
        return;
    }

    pthread_mutex_lock(&lock);
    newStruct->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newStruct->RNTI = RNTI;
    newTag->CRCFLAG = CRCFLAG;
    newStruct->crc_tag = newTag;
    ++listSize;
    list = customAlloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * listSize);
    if (list == NULL) {
        // handle error: memory allocation failed
        return;
    }
    list[listSize - 1] = *newStruct;
    pthread_mutex_unlock(&lock);

    free(newStruct); // clean up the allocated memory
}
```
