```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

#define HASH_SIZE 10007 // Prime number for hash table size
int hashTable[HASH_SIZE];
pthread_mutex_t hashLock = PTHREAD_MUTEX_INITIALIZER;

void initHashTable() {
    memset(hashTable, -1, sizeof(hashTable));
}

int insertIntoHashTable(int rnti) {
    int index = abs(rnti % HASH_SIZE); // Hash function

    pthread_mutex_lock(&hashLock);
    if (hashTable[index] == -1 || hashTable[index] == rnti) {
        hashTable[index] = rnti;
        pthread_mutex_unlock(&hashLock);
        return 0; // Success
    } else {
        pthread_mutex_unlock(&hashLock);
        return -1; // Duplicate RNTI
    }
}

DynamicArray *createDynamicArray() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (array == NULL) {
        return NULL;
    }

    array->capacity = 10000; // Initial capacity
    array->count = 0;
    array->array = malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (array->array == NULL) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void addToArray(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (insertIntoHashTable(element->RNTI) != 0) {
        // Duplicate RNTI, ignore the element
        return;
    }

    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        // Double capacity when full
        array->capacity *= 2;
        array->array = realloc(array->array, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    }

    array->array[array->count++] = element;

    pthread_mutex_unlock(&array->lock);
}

void freeArray(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->array[i]);
    }

    pthread_mutex_destroy(&array->lock);
    free(array->array);
    free(array);
}
```
This code provides a basic implementation of the requirements. It uses a dynamic array to store elements, and a hash table with a simple hash function for efficient duplicate detection. The `addToArray` function checks if an RNTI is already in the hash table before adding it to the array. If there's a collision (i.e., two different RNTIs havehed to the same index), it logs an error and continues processing, ignoring the new element.
"]

