        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UnionFind {
    int *parent, *rank;
    int n;
} UnionFind;

UnionFind* newUnionFind(int n) {
    UnionFind* uf = (UnionFind*) malloc(sizeof(UnionFind));
    uf->n = n;
    uf->parent = (int*) malloc(n * sizeof(int));
    uf->rank = (int*) calloc(n, sizeof(int));
    for (int i = 0; i < n; ++i) {
        uf->parent[i] = i;
    }
    return uf;
}

int find(UnionFind* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void unionUnionFind(UnionFind* uf, int x, int y) {
    int xroot = find(uf, x);
    int yroot = find(uf, y);
    if (uf->rank[xroot] < uf->rank[yroot]) {
        uf->parent[xroot] = yroot;
    } else if (uf->rank[xroot] > uf->rank[yroot]) {
        uf->parent[yroot] = xroot;
    } else {
        uf->parent[yroot] = xroot;
        uf->rank[xroot]++;
    }
}

void processNFARelations(int* cellIdentities, int size) {
    clock_t startTime = clock();

    NFAPI_CRC_INDICATION_PDU_T *pduArray = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    UnionFind* uf = newUnionFind(size);

    for (int i = 0; i < size; ++i) {
        pduArray[i].RX_UE_INFORMATION_TAG = cellIdentities[i];
        pduArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = cellIdentities[i] % 2;
    }

    for (int i = 0; i < size; ++i) {
        for (int j = i + 1; j < size; ++j) {
            if (find(uf, i) != find(uf, j)) {
                unionUnionFind(uf, i, j);
            }
        }
    }

    int disjointSets = 0;
    for (int i = 0; i < size; ++i) {
        if (uf->parent[i] == i) {
            ++disjointSets;
        }
    }

    clock_t endTime = clock();
    double timeTaken = ((double)(endTime - startTime)) / CLOCKS_PER_SEC * 1000.0;
    printf("Time taken: %f ms\n", timeTaken);
}
