#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

static int contextCount = 0;

CipherContext* initializeNetworkCipherContext(const char *passphrase) {
    CipherContext *cipher = malloc(sizeof(CipherContext));
    if (!cipher) return NULL;

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)passphrase, strlen(passphrase), hash);

    memset(cipher->key, 0, sizeof(cipher->key));
    memset(cipher->iv, 0, sizeof(cipher->iv));
    memcpy(cipher->key, hash, SHA256_DIGEST_LENGTH);

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv)) {
        free(cipher);
        return NULL;
    }

    contextCount++;
    return cipher;
}

void cleanupNetworkCipherContext(CipherContext *cipher) {
    if (!cipher) return;

    EVP_CIPHER_CTX_free(cipher->ctx);
    free(cipher);

    contextCount--;
}
```
This code creates a new cipher context with an AES-256-CBC encryption using a SHA-256 hash of the provided passphrase as key. It also keeps track of the number of active contexts to help manage resources and thread safety. 

