["This task is quite complex and requires a deep understanding of C programming, memory management, concurrency control, error handling, and system dependencies. Here's an example of how you might start implementing this function in C:

```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>
#include <limits.h>

typedef struct {
    int value;
} record_t;

typedef struct {
    long* offsets;
    int* keys;
    record_t** records;
    size_t capacity;
    pthread_mutex_t lock;
} data_structures_t;

data_structures_t* init_data_structures(size_t initial_capacity) {
    assert(initial_capacity > 0);

    data_structures_t* ds = malloc(sizeof(data_structures_t));
    if (ds == NULL) return NULL;

    ds->offsets = calloc(initial_capacity, sizeof(long));
    ds->keys = calloc(initial_capacity, sizeof(int));
    ds->records = malloc(initial_capacity * sizeof(record_t*));
    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL) {
        free_data_structures(ds);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        ds->records[i] = malloc(sizeof(record_t));
        if (ds->records[i] == NULL) {
            free_data_structures(ds);
            return NULL;
        }
    }

    ds->capacity = initial_capacity;
    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void resize_data_structures(data_structures_t* ds, size_t new_capacity) {
    assert(new_capacity > ds->capacity);

    long* new_offsets = realloc(ds->offsets, new_capacity * sizeof(long));
    int* new_keys = realloc(ds->keys, new_capacity * sizeof(int));
    record_t** new_records = realloc(ds->records, new_capacity * sizeof(record_t*));

    if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
        free_data_structures(ds);
        exit(EXIT_FAILURE); // Out of memory
    }

    for (size_t i = ds->capacity; i < new_capacity; ++i) {
        new_records[i] = malloc(sizeof(record_t));
        if (new_records[i] == NULL) {
            free_data_structures(ds);
            exit(EXIT_FAILURE); // Out of memory
        }
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->capacity = new_capacity;
}

void free_data_structures(data_structures_t* ds) {
    if (ds == NULL) return;

    for (size_t i = 0; i < ds->capacity; ++i) {
        free(ds->records[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}
```
