['Here is the Java code for your problem:

```java
import java.security.MessageDigest;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ListModifier {
    private static final Logger logger = LoggerFactory.getLogger(ListModifier.class);

    public static class Config {
        int performanceThreshold;
        boolean loggingEnabled;

        // constructor, getters and setters omitted for brevity
    }

    public static Pair<String, ForwardList<String>> modifyAndHash(ForwardList<String> list, String target, String toInsert, Config config) {
        int insertionPoint = -1;

        if (config.performanceThreshold > 0 && list.size() > config.performanceThreshold) {
            // If performance threshold is set and the list size exceeds it, 
            // use a more efficient algorithm for large lists

            Map<String, Integer> indexMap = new HashMap<>();
            int i = 0;
            for (String s : list) {
                indexMap.put(s, i++);
            }

            if (indexMap.containsKey(target)) {
                insertionPoint = indexMap.get(target);
            } else {
                // If target is not found in the map, append to end of list
                insertionPoint = list.size();
            }
        } else {
            // For small lists or when performance threshold is not set, 
            // use a simple linear search algorithm

            int i = 0;
            for (String s : list) {
                if (s.equals(target)) {
                    insertionPoint = i;
                    break;
                }
                i++;
            }
        }

        // Insert the string after the first occurrence of target or at end of list
        if (insertionPoint != -1) {
            list.add(insertionPoint + 1, toInsert);
        } else {
            list.addLast(toInsert);
        }

        // Calculate MD5 hash of the inserted string
        String md5Hex = DigestUtils.md5Hex(toInsert);

        if (config.loggingEnabled) {
            logger.info("Inserted '{}' after first occurrence of '{}'. New list: {}", toInsert, target, list);
        }

        return new Pair<>(md5Hex, list);
    }
}
```
This code uses the `ForwardList` class from Apache Commons Collections library for its forward-linked list implementation. It also uses SLF4J and Logback for logging and DigestUtils from Apache Commons Codec for MD5 hash calculation. The `Config` inner class is used to encapsulate configuration options, including performance thresholds and logging settings.
