        log_error("Password is too short");
        return NULL;
    }

    *iv = malloc(EVP_MAX_IV_LENGTH);
    if (*iv == NULL) {
        log_error("Failed to allocate memory for IV");
        return NULL;
    }

    // Generate a secure random IV
    if (RAND_bytes(*iv, EVP_MAX_IV_LENGTH) != 1) {
        log_error("Failed to generate secure random IV");
        free(*iv);
        *iv = NULL;
        return NULL;
    }

    // Initialize the cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        log_error("Failed to create new cipher context");
        free(*iv);
        *iv = NULL;
        return NULL;
    }

    // Derive the AES key using PBKDF2 with HMAC-SHA256
    unsigned char* derivedKey = malloc(EVP_MAX_KEY_LENGTH);
    if (derivedKey == NULL) {
        log_error("Failed to allocate memory for derived key");
        EVP_CIPHER_CTX_free(ctx);
        free(*iv);
        *iv = NULL;
        return NULL;
    }

    if (EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char*)password, strlen(password), 1, derivedKey, NULL) == 0) {
        log_error("Failed to derive AES key");
        free(*iv);
        *iv = NULL;
        EVP_CIPHER_CTX_free(ctx);
        free(derivedKey);
        return NULL;
    }

    // Initialize the cipher with the derived key and IV
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, derivedKey, *iv) != 1) {
        log_error("Failed to initialize cipher");
        free(*iv);
        *iv = NULL;
        EVP_CIPHER_CTX_free(ctx);
        free(derivedKey);
        return NULL;
    }

    // Clean up the derived key as it's no longer needed
    memset(derivedKey, 0, EVP_MAX_KEY_LENGTH);
    free(derivedKey);

    return ctx;
}
