void add(NFAPI_CRC_INDICATION_PDU_T element) {
    if (size >= MAX_SIZE) {
        printf("Error: Maximum size reached.\n");
        return;
    }

    Node* newNode = malloc(sizeof(Node));
    newNode->data = element;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            if (current->data.RNTI == element.RNTI) {
                printf("Error: Duplicate RNTI found.\n");
                free(newNode);
                return;
            }
            current = current->next;
        }

        if (current->data.RNTI == element.RNTI) {
            printf("Error: Duplicate RNTI found.\n");
            free(newNode);
            return;
        }

        current->next = newNode;
    }

    size++;
}

void serialize() {
    FILE* file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Error: Could not open file for writing.\n");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}
