// Global lock for thread safety
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// List of structures
NFAPI_CRC_INDICATION_PDU_T* list = NULL;
size_t list_capacity = 0;
size_t list_size = 0;

void manage_structures(const void* data, size_t size) {
    pthread_mutex_lock(&list_lock);

    // Check if we need to resize the list
    if (list_size + size > list_capacity) {
        size_t new_capacity = list_capacity == 0 ? 1 : list_capacity * 2;

        NFAPI_CRC_INDICATION_PDU_T* new_list = my_malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            // Handle allocation failure
            pthread_mutex_unlock(&list_lock);
            return;
        }

        memcpy(new_list, list, list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        my_free(list);

        list = new_list;
        list_capacity = new_capacity;
    }

    // Copy the data into the list
    memcpy(&list[list_size], data, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list_size += size;

    pthread_mutex_unlock(&list_lock);
}
```
This function uses a global lock to ensure thread safety. It checks if the new data would exceed the current capacity of the list, and if so, it doubles the capacity. If the allocation fails, it unlocks the mutex and returns without modifying the list. After copying the data into the list, it increments the size counter.

