    if (*offsets == NULL) {
        return -3; // Memory allocation failure
    }

    *keys = calloc(record_count, sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -3; // Memory allocation failure
    }

    *records = malloc(sizeof(Record) * record_count);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -3; // Memory allocation failure
    }

    srand(time(NULL));
    for (int i = 0; i < record_count; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = i + 1;
        (*records)[i].value = rand() % value_range;
    }

    fclose(file);
    return 0; // Success
}
