#include <time.h>

typedef struct packet {
    void* payload;
    time_t timestamp;
    int metadata;
} Packet;

typedef struct node {
    Packet* packet;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addPacket(Packet* packet) {
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    newNode->packet = packet;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void updatePacket(int id, Packet* updated) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        if (current->packet->metadata == id) {
            free(current->packet);
            current->packet = updated;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

Packet* getPacketByTimestampRange(time_t start, time_t end) {
    Packet* result = NULL;

    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        if (current->packet->timestamp >= start && current->packet->timestamp <= end) {
            result = current->packet;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);

    return result;
}
```
This code uses a linked list to store packets. It also uses a mutex for thread safety, ensuring that only one thread can access the list at a time. This is necessary because multiple threads may be trying to add or update packets simultaneously. 

