['Here is a basic implementation of your request using C++17, libcurl for networking, OpenSSL for cryptography, nlohmann/json for JSON parsing, and spdlog for logging. This code does not include the local library function to get Pokemon weaknesses as it's not provided in the task description.

```cpp
#include <string>
#include <curl/curl.h>
#include <openssl/evp.h>
#include <nlohmann/json.hpp>
#include <spdlog/spdlog.h>

std::string getPokemonWeaknesses(const std::string& pokemonName, const std::string& apiEndpoint) {
    CURL* curl = curl_easy_init();
    if (!curl) {
        throw std::runtime_error("Failed to initialize libcurl");
    }

    std::string url = apiEndpoint + "/" + pokemonName;
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());

    std::string response;
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* contents, size_t size, size_t nmemb, void* userp) -> size_t {
        ((std::string*)userp)->append((char*)contents, size * nmemb);
        return size * nmemb;
    });
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        throw std::runtime_error("Failed to perform libcurl request: " + std::string(curl_easy_strerror(res)));
    }

    long responseCode;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &responseCode);
    if (responseCode != 200) {
        throw std::runtime_error("Unexpected HTTP response code: " + std::to_string(responseCode));
    }

    curl_easy_cleanup(curl);

    nlohmann::json jsonResponse;
    try {
        jsonResponse = nlohmann::json::parse(response);
    } catch (const nlohmann::json::parse_error& e) {
        throw std::runtime_error("Failed to parse JSON response: " + std::string(e.what()));
    }

    // Assume the weaknesses are in a field called 'weaknesses'
    std::vector<std::string> weaknesses = jsonResponse["weaknesses"].get<std::vector<std::string>>();

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        throw std::runtime_error("Failed to create cipher context");
    }

    // Assume the DES algorithm with ECB mode for simplicity
    EVP_EncryptInit(ctx, EVP_des_ecb(), nullptr, nullptr);

    std::string encryptedWeaknesses;
    for (const auto& weakness : weaknesses) {
        int outlen1, outlen2;
        if (!EVP_EncryptUpdate(ctx, reinterpret_cast<unsigned char*>(&encryptedWeaknesses[0]), &outlen1, 
            reinterpret_cast<const unsigned char*>(weakness.c_str()), weakness.length()) ||
            !EVP_EncryptFinal(ctx, reinterpret_cast<unsigned char*>(&encryptedWeaknesses[0]) + outlen1, &outlen2)) {
                throw std::runtime_error("Failed to encrypt weakness");
        }
    }

    EVP_CIPHER_CTX_free(ctx);

    return encryptedWeaknesses;
}
```
This code is a basic example and does not include all the features you requested, such as handling timeouts, retries, logging, or integration with a local library function to get Pokemon weaknesses. It also doesn't handle potential edge cases like network disruptions or JSON parsing errors. You would need to add these features in a production-ready codebase.
