        shapes = realloc(shapes, allocatedMemory + CHUNK_SIZE);
        if (!shapes) {
            printf("Error: Memory allocation failed.\n");
            return;
        }

        allocatedMemory += CHUNK_SIZE;
    }

    // Add new shape to the array
    shapes[shapeCount].point = point;
    shapes[shapeCount].color = color;
    shapes[shapeCount].area = area;
    shapeCount++;
}
