['Here is a basic implementation of your requirements in C++ using OpenSSL for MD5 hashing and Boost libraries for threading and asynchronous operations. This code does not include all the features you mentioned due to complexity, but it should give you an idea about how to start implementing such a program. 

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <chrono>
#include <random>
#include <openssl/md5.h>
#include <boost/thread.hpp>
#include <boost/asio.hpp>

std::string generate_unique_id() {
    auto timestamp = std::to_string(std::chrono::system_clock::now().time_since_epoch().count());
    const std::string charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890";
    std::default_random_engine generator(std::chrono::system_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<int> distribution(0, charset.size() - 1);
    std::string random_str(32, ' ');
    for (size_t i = 0; i < 32; i++) {
        random_str[i] = charset[distribution(generator)];
    }
    return timestamp + "_" + random_str;
}

std::string compute_md5(const std::string& str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str.c_str(), str.size(), (unsigned char*)&digest);    
    char mdString[33];
    for(int i = 0; i < 16; i++)
         sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    return std::string(mdString);
}

void process_file(const std::string& filename, const std::string& unique_id) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file");
    }

    MD5_CTX mdContext;
    MD5_Init(&mdContext);

    const size_t buffer_size = 1024 * 1024; // 1MB buffer
    char* buffer = new char[buffer_size];
    while (!file.eof()) {
        file.read(buffer, buffer_size);
        std::streamsize bytesRead = file.gcount();
        if (bytesRead > 0) {
            MD5_Update(&mdContext, buffer, bytesRead);
        }
    }

    delete[] buffer;
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &mdContext);

    std::stringstream md5string;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        md5string << std::hex << std::setw(2) << std::setfill('0') << static_cast<unsigned int>(digest[i]);
    }

    std::cout << "File: " << filename << ", Unique ID: " << unique_id << ", MD5 Hash: " << md5string.str() << std::endl;
}

int main() {
    boost::asio::thread_pool pool(4); // 4 threads in the thread pool

    for (const auto& filename : filenames) {
        const auto unique_id = generate_unique_id();
        boost::asio::post(pool, [filename, unique_id]() { process_file(filename, unique_id); });
    }

    pool.join(); // wait for all tasks to finish

    return 0;
}
