using System.Xml;
using System.Xml.Linq;

public class XmlParser
{
    private readonly XDocument _document;

    public XmlParser(string xml)
    {
        _document = XDocument.Parse(xml);
    }

    public XElement GetSingleElementByName(string tagName, string namespaceUri)
    {
        return _document.Descendants()
            .FirstOrDefault(e => e.Name.LocalName == tagName && e.Name.NamespaceName == namespaceUri);
    }

    public List<XElement> GetAllElementsByName(string tagName, string namespaceUri)
    {
        return _document.Descendants()
            .Where(e => e.Name.LocalName == tagName && e.Name.NamespaceName == namespaceUri)
            .ToList();
    }

    public string GetAttributeByName(string elementName, string attributeName, string namespaceUri)
    {
        var element = _document.Descendants()
            .FirstOrDefault(e => e.Name.LocalName == elementName && e.Name.NamespaceName == namespaceUri);

        return element?.Attribute(XName.Get(attributeName, namespaceUri))?.Value;
    }
}
```

