["Here is a basic implementation of such utility function using Node.js Stream API. This example does not handle backpressure or fragmentation issues as they are complex topics that require more detailed understanding of your specific use case and data flow. 

```javascript
const { Transform } = require('stream');

class ConcatenateStream extends Transform {
    constructor(options) {
        super(options);
        this._buffer = Buffer.alloc(0);
        this._bytesTransferred = 0;
        this._memoryUsageThreshold = options.threshold || 1024 * 1024; // Default to 1MB
    }

    _transform(chunk, encoding, callback) {
        if (this._buffer.length + chunk.length > this._memoryUsageThreshold) {
            return callback(new Error('Memory usage threshold exceeded'));
        }

        this._bytesTransferred += chunk.length;
        this._buffer = Buffer.concat([this._buffer, chunk]);
        callback();
    }

    getBytes() {
        return this._bytesTransferred;
    }

    getMemoryUsage() {
        return process.memoryUsage().heapUsed;
    }
}

function createConcatenateStream(options) {
    return new ConcatenateStream(options);
}

module.exports = createConcatenateStream;
```

