import json
from threading import Lock

class JSONParser(object):
    _registry = {}
    _lock = Lock()

    @staticmethod
    def register_factory(id, factory):
        with JSONParser._lock:
            if id in JSONParser._registry:
                raise ValueError("Duplicate ID")
            JSONParser._registry[id] = factory

    @staticmethod
    def create_instance(id, *args, **kwargs):
        with JSONParser._lock:
            if id not in JSONParser._registry:
                raise ValueError("Unknown ID")
            return JSONParser._registry[id](*args, **kwargs)

    @staticmethod
    def to_json(obj):
        return json.dumps(obj)

    @staticmethod
    def from_json(s):
        return json.loads(s)
