    new_pdu->DL_USER_INFORMATION_TAG = DL_USER_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->CRC_indicator = CRC_indicator;
    new_pdu->next = list->head;

    list->head = new_pdu;

    pthread_mutex_unlock(&list->lock);
}

DL_CI_PDU* get_pdu(DL_CI_List *list, int index) {
    pthread_mutex_lock(&list->lock);

    DL_CI_PDU *current = list->head;
    for (int i = 0; current != NULL && i < index; i++) {
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return current;
}

void free_list(DL_CI_List *list) {
    pthread_mutex_lock(&list->lock);

    DL_CI_PDU *current = list->head;
    while (current != NULL) {
        DL_CI_PDU *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```
This code creates a linked list of DL CI PDUs, where each node contains the data for one PDU. The `add_pdu` function adds a new PDU to the beginning of the list, and the `get_pdu` function retrieves a PDU by its index in the list.

Please note that this is a basic example and does not include all the requirements mentioned above (like error handling for memory allocation failures, optimization for high-throughput environments, etc.). It's recommended to use a more robust data structure like a hash table or binary search tree if you need efficient iteration and data retrieval operations.
