['Here is a basic implementation of the task in C# using `System.Security.Cryptography` for MD5 hashing and `Microsoft.Extensions.ObjectPool` for object pooling. This code assumes that each line contains at least three fields, where the last two are numeric values. 

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.ObjectPool;

public class FileProcessor
{
    private readonly ObjectPool<StringBuilder> _stringBuilderPool;
    private static MD5 _md5 = MD5.Create();

    public FileProcessor(ObjectPoolProvider objectPoolProvider)
    {
        _stringBuilderPool = objectPoolProvider.CreateStringBuilderPool();
    }

    public string ProcessAndHashFileContent(string filePath)
    {
        var hashResult = new StringBuilder();

        using (var reader = new StreamReader(filePath))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                var fields = line.Split(',');

                if (fields.Length < 3 || !double.TryParse(fields[^2], out _) || !double.TryParse(fields[^1], out _))
                {
                    throw new FormatException("Invalid format in file.");
                }

                var average = (Convert.ToDouble(fields[^2]) + Convert.ToDouble(fields[^1])) / 2;
                fields[^1] = average.ToString();

                var builder = _stringBuilderPool.Get();
                try
                {
                    foreach (var field in fields)
                    {
                        builder.Append(field).Append(',');
                    }

                    builder.Remove(builder.Length - 1, 1); // Remove trailing comma
                    hashResult.AppendLine(builder.ToString());
                }
                finally
                {
                    _stringBuilderPool.Return(builder);
                }
            }
        }

        lock (_md5)
        {
            var bytes = Encoding.UTF8.GetBytes(hashResult.ToString());
            var hashBytes = _md5.ComputeHash(bytes);

            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }
}
```
This code reads the file line by line, processes each line, and appends it to a `StringBuilder` pooled object. After processing all lines, it calculates the MD5 hash of the concatenated string using a lock to ensure thread safety. The MD5 hash is then converted to its hexadecimal representation.
']

