import java.security.*;
import javax.xml.bind.DatatypeConverter;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;

public class HashingLibrary {
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);

    public Future<String> hashMD5Async(final String input) {
        return executor.submit(() -> hashWithAlgorithm(input, "MD5"));
    }

    public Future<String> hashSHA256Async(final String input) {
        return executor.submit(() -> hashWithAlgorithm(input, "SHA-256"));
    }

    private static String hashWithAlgorithm(String input, String algorithm) {
        try {
            MessageDigest md = MessageDigest.getInstance(algorithm);
            byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));
            return DatatypeConverter.printHexBinary(digest).toLowerCase();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException("Unsupported algorithm: " + algorithm, e);
        }
    }
}
```
