    if (list == NULL) return NULL;

    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroyList(List *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addElement(List *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newData == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;  // Failed to allocate memory
        }

        list->data = newData;
        list->capacity = newCapacity;
    }

    memcpy(&list->data[list->size], &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}
