int bufferIndex = 0;
pthread_mutex_t bufferMutex = PTHREAD_MUTEX_INITIALIZER;

void log_event_with_format(const char *format, ...) {
    pthread_mutex_lock(&bufferMutex);

    va_list args;
    va_start(args, format);

    LogEntry newLog;
    time(&newLog.timestamp);
    vsnprintf(newLog.message, MAX_MESSAGE_LENGTH, format, args);

    logBuffer[bufferIndex] = newLog;
    bufferIndex = (bufferIndex + 1) % MAX_BUFFER_SIZE;

    va_end(args);

    pthread_mutex_unlock(&bufferMutex);
}
