        freeContext(context, numSessions);
        return NULL;
    }

    context->connectionStatus = networkCondition > 0 ? 1 : 0;

    return context;
}

void freeContext(UEContext* context, int count) {
    for (int i = 0; i < count; ++i) {
        if (context->sessions[i] != NULL) {
            free(context->sessions[i]);
        }
    }

