typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
} List;

List* list_create(size_t initialCapacity) {
    List *list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->capacity = initialCapacity;
    list->size = 0;
    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return list;
}

void list_destroy(List *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int list_append(List *list, NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newData == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->capacity = newCapacity;
        list->data = newData;
    }

    list->data[list->size++] = value;

    pthread_mutex_unlock(&list->lock);
    return 0;
}
```
This code creates a dynamically resizing array that can be safely accessed from multiple threads. It uses a mutex to ensure that only one thread can modify the list at a time, preventing data races and deadlocks. The list doubles in size each time it needs to resize, which is a simple way of achieving good performance while minimizing memory overhead.

