#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int account_id;
    double amount;
    char currency[4];
    time_t timestamp;
} Financial_Transaction;

typedef struct Node {
    Financial_Transaction transaction;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_transaction(Financial_Transaction transaction) {
    pthread_mutex_lock(&lock);

    Node* new_node = malloc(sizeof(Node));
    new_node->transaction = transaction;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}

void update_transaction(int account_id, Financial_Transaction new_transaction) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        if (current->transaction.account_id == account_id) {
            current->transaction = new_transaction;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

double get_balance(int account_id) {
    pthread_mutex_lock(&lock);

    double balance = 0.0;
    Node* current = head;
    while (current != NULL) {
        if (current->transaction.account_id == account_id) {
            balance += current->transaction.amount;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);

    return balance;
}
```
