void insert(int val) {
    pthread_mutex_lock(&lock);

    Record *newNode = malloc(sizeof(Record));
    if (newNode == NULL) {
        // handle error
        return;
    }
    newNode->value = val;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void delete(int val) {
    pthread_mutex_lock(&lock);

    Record *temp = head, *prev = NULL;
    while (temp != NULL && temp->value != val) {
        prev = temp;
        temp = temp->next;
    }
    if (temp == NULL) {
        // handle error
        return;
    }

    if (prev != NULL) {
        prev->next = temp->next;
    } else {
        head = temp->next;
    }
    free(temp);

    pthread_mutex_unlock(&lock);
}
```
