["Here is a basic implementation of your request in C++ using `std::chrono` for timestamps and `std::random_device` for random numbers. This code does not handle race conditions or cleanup after execution due to complexity, but it should give you a good starting point. 

```cpp
#include <chrono>
#include <random>
#include <vector>

class CombatAction {
public:
    enum ActionType { ACTION1 = 5, ACTION2 = 7, ACTION3 = 10 };

    CombatAction() : lastExecutionTime(std::chrono::system_clock::now()) {}

    bool canExecute() const {
        return std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now() - lastExecutionTime).count() >= cooldown;
    }

    void execute() {
        if (canExecute()) {
            // Execute action here

            lastExecutionTime = std::chrono::system_clock::now();
        }
    }

private:
    ActionType cooldown;
    std::chrono::time_point<std::chrono::system_clock> lastExecutionTime;
};

void executeCombatAction(std::vector<CombatAction>& actions) {
    static thread_local std::random_device rd;
    static thread_local std::mt19937 gen(rd());
    static thread_local std::uniform_int_distribution<> dis(0, actions.size() - 1);

    int actionIndex = dis(gen);
    if (actions[actionIndex].canExecute()) {
        actions[actionIndex].execute();
    }
}
```
