    int ID;
    time_t timestamp;
    Measurement_Report* reports;
    int reportCount;
} UE_Status_Report;

typedef struct DynamicArray {
    pthread_mutex_t lock;
    UE_Status_Report** array;
    int size;
    int capacity;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    arr->array = NULL;
    arr->size = 0;
    arr->capacity = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void addReport(DynamicArray* arr, UE_Status_Report* report) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        // Reallocate array with double capacity
        int newCapacity = (arr->capacity == 0) ? 1 : arr->capacity * 2;
        UE_Status_Report** newArray = realloc(arr->array, sizeof(UE_Status_Report*) * newCapacity);

        if (newArray == NULL && arr->size > 0) {
            // Reallocation failed, free old array and return
            free(arr->array);
            pthread_mutex_unlock(&arr->lock);
            return;
        }

        arr->capacity = newCapacity;
        arr->array = newArray;
    }

    // Add report to array
    arr->array[arr->size] = report;
    arr->size++;

    pthread_mutex_unlock(&arr->lock);
}

// Implement other functions as needed...
