            std::uniform_real_distribution<float> floatDist;
            static MTGenerator* instance;
            static std::mutex mtx;

        public:
            MTGenerator(unsigned long long seed = 0, float minFloat = 0.0f, float maxFloat = 1.0f) : 
                gen(seed), intDist(0, INT_MAX), floatDist(minFloat, maxFloat) {}

            ~MTGenerator() { delete instance; }

            static MTGenerator* getInstance(unsigned long long seed = 0, float minFloat = 0.0f, float maxFloat = 1.0f) {
                std::lock_guard<std::mutex> lock(mtx);
                if (instance == nullptr) {
                    instance = new MTGenerator(seed, minFloat, maxFloat);
                }
                return instance;
            }

            int getRandomInt(int min = 0, int max = INT_MAX) {
                if (min > max) throw std::invalid_argument("Minimum value is greater than maximum");
                std::uniform_int_distribution<int> dist(min, max);
                return dist(gen);
            }

            float getRandomFloat(float min = 0.0f, float max = 1.0f) {
                if (min > max) throw std::invalid_argument("Minimum value is greater than maximum");
                std::uniform_real_distribution<float> dist(min, max);
                return dist(gen);
            }

            void setSeed(unsigned long long seed) {
                gen.seed(seed);
            }
    };

    MTGenerator* MTGenerator::instance = nullptr;
    std::mutex MTGenerator::mtx;
}
