    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed!\n");
        exit(0);  // Exit program if memory allocation fails.
    }
    newNode->data = *createData(tag, rnti, crc);
    newNode->next = NULL;
    return newNode;
}

// Function to insert a node at the end of list
void insertNodeAtTail(int tag, int rnti, int crc) {
    if (head == NULL) {  // If list is empty, make this node as head.
        head = createNode(tag, rnti, crc);
        return;
    }
    Node* temp = head;
    while (temp->next != NULL) {  // Traverse till the last node.
        if (temp->data.RNTI == rnti) {
            printf("Duplicate RNTI found, not inserting!\n");
            return;
        }
        temp = temp->next;
    }
    if (temp->data.RNTI != rnti) {  // If last node's RNTI is different from new node's RNTI, add the new node at end.
        temp->next = createNode(tag, rnti, crc);
    } else {
        printf("Duplicate RNTI found, not inserting!\n");
    }
}
