using System.Text;

public class AesDecryptionService
{
    private static readonly Encoding _encoding = Encoding.UTF8;

    public byte[] DecryptCbcWithAes(byte[] ciphertext, string key, string iv, PaddingMode padding)
    {
        try
        {
            using (var aesAlgorithm = new AesManaged())
            {
                aesAlgorithm.KeySize = 256; // or any other valid size
                aesAlgorithm.BlockSize = 128; // or any other valid size
                aesAlgorithm.Mode = CipherMode.CBC;
                aesAlgorithm.Padding = padding;

                var keyBytes = _encoding.GetBytes(key);
                if (keyBytes.Length != aesAlgorithm.KeySize / 8)
                    throw new ArgumentException("Invalid Key Length", nameof(key));

                var ivBytes = _encoding.GetBytes(iv);
                if (ivBytes.Length != aesAlgorithm.BlockSize / 8)
                    throw new ArgumentException("Invalid IV Size", nameof(iv));

                using (var decryptor = aesAlgorithm.CreateDecryptor(keyBytes, ivBytes))
                {
                    return PerformCryptography(ciphertext, decryptor);
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message); // replace with your logging mechanism
            return null;
        }
    }

    private byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransform)
    {
        using (var memoryStream = new MemoryStream())
        {
            using (var cryptoStream = new CryptoStream(memoryStream, cryptoTransform, CryptoStreamMode.Write))
            {
                cryptoStream.Write(data, 0, data.Length);
                cryptoStream.FlushFinalBlock();

                return memoryStream.ToArray();
            }
        }
    }
}
```
This code uses the `AesManaged` class from .NET's built-in cryptography library to perform AES encryption and decryption. It accepts a ciphertext, key, IV, and padding mode as parameters, validates them, and then performs the decryption using these values. If any of the inputs are invalid or an error occurs during decryption, it logs the error message and returns `null`.
