    queue->buffer = calloc(maxSize, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (queue->buffer == NULL) {
        free(queue);
        return NULL;
    }

    queue->head = 0;
    queue->tail = 0;
    queue->count = 0;
    queue->maxSize = maxSize;
    pthread_mutex_init(&queue->mutex, NULL);
    sem_init(&queue->semaphore, 0, 0);

    return queue;
}

void enqueue(Queue* queue, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->count == queue->maxSize) {
        sem_wait(&queue->semaphore);
    }

    queue->buffer[queue->tail] = data;
    queue->tail = (queue->tail + 1) % queue->maxSize;
    queue->count++;

    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->semaphore);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(Queue* queue) {
    NFAPI_CRC_INDICATION_PDU_T* data = NULL;

    pthread_mutex_lock(&queue->mutex);

    while (queue->count == 0) {
        sem_wait(&queue->semaphore);
    }

    data = queue->buffer[queue->head];
    queue->head = (queue->head + 1) % queue->maxSize;
    queue->count--;

    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->semaphore);

    return data;
}
```
This code creates a thread-safe queue and provides functions to enqueue and dequeue elements. The `enqueue` function will block if the queue is full, and the `dequeue` function will block if the queue is empty. 

