#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add(int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if(newNode == NULL) {
        // Handle out of memory error
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->data.RNTI = RNTI;
    newNode->data.CRCFLAG = CRCFLAG;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void remove(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* temp = head, *prev = NULL;

    if (temp != NULL && temp->data.RNTI == RNTI) {
        head = temp->next;  
        free(temp);              
        return;
    }

    while (temp != NULL && temp->data.RNTI != RNTI) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // No such RNTI found

    prev->next = temp->next;
    free(temp); 

    pthread_mutex_unlock(&lock);
}

void updateCRCFLAG(int RNTI, int newCRCFLAG) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while (temp != NULL && temp->data.RNTI != RNTI) 
        temp = temp->next;

    if(temp == NULL) { // No such RNTI found
        pthread_mutex_unlock(&lock);
        return;
    }

    temp->data.CRCFLAG = newCRCFLAG;

    pthread_mutex_unlock(&lock);
}
