```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int antenna_ports;
    int bandwidth_part_identifiers;
    int configuration_status_flag;
} LTE_PHY_Layer_Configuration;

typedef struct Node {
    char* radio_equipment_ID;
    char* network_cell_identifier;
    LTE_PHY_Layer_Configuration config;
    struct Node* next;
} Node;

#define TABLE_SIZE 10007 // A prime number for better distribution
Node** hashTable;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned long hash(const char* str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % TABLE_SIZE;
}

Node* createNode(const char* radio_equipment_ID, const char* network_cell_identifier, LTE_PHY_Layer_Configuration config) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return NULL; // Handle memory allocation failure

    node->radio_equipment_ID = strdup(radio_equipment_ID);
    node->network_cell_identifier = strdup(network_cell_identifier);
    node->config = config;
    node->next = NULL;

    return node;
}

void insertNode(const char* radio_equipment_ID, const char* network_cell_identifier, LTE_PHY_Layer_Configuration config) {
    pthread_mutex_lock(&lock);

    Node* node = createNode(radio_equipment_ID, network_cell_identifier, config);
    if (node == NULL) return; // Handle memory allocation failure

    unsigned long index = hash(network_cell_identifier);
    node->next = hashTable[index];
    hashTable[index] = node;

    pthread_mutex_unlock(&lock);
}

LTE_PHY_Layer_Configuration* lookupNode(const char* network_cell_identifier) {
    pthread_mutex_lock(&lock);

    unsigned long index = hash(network_cell_identifier);
    Node* node;
    for (node = hashTable[index]; node != NULL; node = node->next) {
        if (strcmp(node->network_cell_identifier, network_cell_identifier) == 0) {
            pthread_mutex_unlock(&lock);
            return &node->config;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL; // Node not found
}

void removeNode(const char* network_cell_identifier) {
    pthread_mutex_lock(&lock);

    unsigned long index = hash(network_cell_identifier);
    Node** link = &hashTable[index];
    while (*link != NULL) {
        if (strcmp((*link)->network_cell_identifier, network_cell_identifier) == 0) {
            Node* nodeToRemove = *link;
            *link = nodeToRemove->next;

            free(nodeToRemove->radio_equipment_ID);
            free(nodeToRemove->network_cell_identifier);
            free(nodeToRemove);
        } else {
            link = &(*link)->next;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
This code is a basic implementation and does not handle all the engineering challenges mentioned above. It's recommended to use a more robust solution for production-level code, such as using a concurrent hash map library or implementing your own concurrent data structure with appropriate locking mechanisms.
