void insert_array(DynamicArray *a, LTE_PHY_Layer_Configuration element) {
    pthread_mutex_lock(&a->lock);

    if (a->used == a->size) {
        a->size *= 2;
        a->array = (LTE_PHY_Layer_Configuration*)realloc(a->array, a->size * sizeof(LTE_PHY_Layer_Configuration));
    }

    element.timestamp = time(NULL);
    a->array[a->used++] = element;

    pthread_mutex_unlock(&a->lock);
}

void delete_array(DynamicArray *a, size_t index) {
    pthread_mutex_lock(&a->lock);

    if (index < a->used) {
        for (size_t i = index; i < a->used - 1; ++i) {
