DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) return NULL; // Error checking

    arr->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    arr->array = malloc(initial_capacity * sizeof(MAC_TransmissionParameters));
    if (arr->array == NULL) { // Error checking
        free(arr);
        return NULL;
    }

    arr->size = 0;
    arr->capacity = initial_capacity;

    return arr;
}

int add_to_dynamic_array(DynamicArray* arr, MAC_TransmissionParameters value) {
    pthread_mutex_lock(&arr->lock); // Lock for thread safety

    if (arr->size == arr->capacity) { // If array is full, double its capacity
        size_t new_capacity = arr->capacity * 2;
        MAC_TransmissionParameters* new_array = realloc(arr->array, new_capacity * sizeof(MAC_TransmissionParameters));

        if (new_array == NULL) { // Error checking
            pthread_mutex_unlock(&arr->lock);
            return -1;
        }

        arr->array = new_array;
        arr->capacity = new_capacity;
    }

    memcpy(&(arr->array[arr->size]), &value, sizeof(MAC_TransmissionParameters)); // Copy value to array
    (arr->size)++;

    pthread_mutex_unlock(&arr->lock); // Unlock for thread safety

    return 0;
}
```
