#include <stdlib.h>
#include <pthread.h>
#define MAX_RNTI 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *head;
    int used[MAX_RNTI];
} LinkedList;

void init(LinkedList *list) {
    list->head = NULL;
    for (int i = 0; i < MAX_RNTI; i++) {
        list->used[i] = 0;
    }
    pthread_mutex_init(&list->lock, NULL);
}

void insert(LinkedList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&list->lock);
    if (RNTI < MAX_RNTI && list->used[RNTI] == 0) {
        NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        newNode->RNTI = RNTI;
        newNode->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        newNode->CRCFLAG = CRCFLAG;
        newNode->next = list->head;
        list->head = newNode;
        list->used[RNTI] = 1;
    }
    pthread_mutex_unlock(&list->lock);
}

void dump(LinkedList *list) {
    FILE *logFile = fopen("linkedList.log", "w");
    NFAPI_CRC_INDICATION_PDU_T *node = list->head;
    while (node != NULL) {
        fprintf(logFile, "%d %d %d %d\n", node->RX_UE_INFORMATION_TAG, node->RNTI, node->CRC_INDICATION_REL8_TAG, node->CRCFLAG);
        node = node->next;
    }
    fclose(logFile);
}
```
