#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    char source_ip[16];
    char dest_ip[16];
    unsigned int size;
} PacketLog;

typedef struct {
    PacketLog* logs;
    int count;
    int capacity;
} DynamicArray;

DynamicArray* create_array(int initialCapacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    array->logs = malloc(initialCapacity * sizeof(PacketLog));
    if (array->logs == NULL) {
        printf("Memory allocation failed.\n");
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initialCapacity;
    return array;
}

void add_log(DynamicArray* array, PacketLog log) {
    if (array->count == array->capacity) {
        int newCapacity = array->capacity * 2;
        PacketLog* newLogs = realloc(array->logs, newCapacity * sizeof(PacketLog));

        if (newLogs == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }

        array->capacity = newCapacity;
        array->logs = newLogs;
    }

    array->logs[array->count] = log;
    array->count++;
}

PacketLog* get_log(DynamicArray* array, int packetId) {
    for (int i = 0; i < array->count; ++i) {
        if (array->logs[i].packet_id == packetId) {
            return &array->logs[i];
        }
    }

    printf("Packet ID not found.\n");
    return NULL;
}

void update_log(DynamicArray* array, PacketLog log) {
    for (int i = 0; i < array->count; ++i) {
        if (array->logs[i].packet_id == log.packet_id) {
            array->logs[i] = log;
            return;
        }
    }

    printf("Packet ID not found.\n");
}

void free_array(DynamicArray* array) {
    free(array->logs);
    free(array);
}
```
This code creates a dynamic array to store the logs. It also provides functions for adding, getting and updating logs. The `create_array` function allocates memory for the initial capacity of the array. If more space is needed, it doubles the size of the array using `realloc`. 

The `add_log` function adds a new log to the end of the array. If there's not enough space, it doubles the size of the array and copies all existing logs into the new array. 

The `get_log` function retrieves a log by its packet ID. It iterates through the array until it finds a log with the specified packet ID or reaches the end of the array. If no such log is found, it prints an error message and returns NULL. 

The `update_log` function updates a log based on its packet ID. It does the same as `get_log` but also replaces the existing log with the new one if it's found. 

Finally, the `free_array` function frees all memory allocated for the array when it's no longer needed.
