    NetworkConfig config;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(NetworkConfig config) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return;
    }

    memcpy(&new_node->config, &config, sizeof(NetworkConfig));
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}

void retrieve() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        printf("IP: %s\n", current->config.ip);
        printf("Subnet Mask: %s\n", current->config.subnet_mask);
        printf("Default Gateway: %s\n", current->config.default_gateway);
        printf("MAC Address: %s\n", current->config.mac_address);

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
