#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>

typedef struct {
    // Define your structure here
} MAC_TransmissionParameters;

typedef struct {
    atomic_int size;
    atomic_int capacity;
    pthread_mutex_t lock;
    MAC_TransmissionParameters* array;
} DynamicArray;

DynamicArray* create_dynamic_array(int initialCapacity) {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) return NULL;

    atomic_init(&arr->size, 0);
    atomic_init(&arr->capacity, initialCapacity);
    pthread_mutex_init(&arr->lock, NULL);

    arr->array = malloc(initialCapacity * sizeof(MAC_TransmissionParameters));
    if (arr->array == NULL) {
        free(arr);
        return NULL;
    }

    return arr;
}

void resize_dynamic_array(DynamicArray* arr, int newCapacity) {
    pthread_mutex_lock(&arr->lock);

    MAC_TransmissionParameters* newArray = malloc(newCapacity * sizeof(MAC_TransmissionParameters));
    if (newArray == NULL) return;

    for (int i = 0; i < atomic_load(&arr->size); ++i) {
        newArray[i] = arr->array[i];
    }

    free(arr->array);
    arr->array = newArray;
    atomic_store(&arr->capacity, newCapacity);

    pthread_mutex_unlock(&arr->lock);
}

void add_to_dynamic_array(DynamicArray* arr, MAC_TransmissionParameters value) {
    int size = atomic_fetch_add(&arr->size, 1);
    if (size >= atomic_load(&arr->capacity)) {
        resize_dynamic_array(arr, atomic_load(&arr->capacity) * 2);
    }

    pthread_mutex_lock(&arr->lock);
    arr->array[size] = value;
    pthread_mutex_unlock(&arr->lock);
}
