['Here is a basic implementation of a hash map in C using an array for storage. This code does not include all the features you mentioned but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    int receivePower;
    float snr;
    float evm;
} LTEPHYLayerStats_t;

typedef struct Node {
    char key[10]; // Assuming keys are strings of length 9 or less
    LTEPHYLayerStats_t value;
    struct Node* next;
} Node;

#define TABLE_SIZE 262144 // Prime number for better distribution in hash table
Node* hashTable[TABLE_SIZE];

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % TABLE_SIZE;
}

void insert(const char* key, LTEPHYLayerStats_t value) {
    unsigned long index = hash(key);

    Node* node = malloc(sizeof(Node));
    strcpy(node->key, key);
    node->value = value;
    node->next = hashTable[index];
    hashTable[index] = node;
}

LTEPHYLayerStats_t* get(const char* key) {
    unsigned long index = hash(key);

    Node* node = hashTable[index];
    while (node != NULL) {
        if (strcmp(node->key, key) == 0)
            return &(node->value);
        node = node->next;
    }

    return NULL; // Not found
}
```
This code uses a simple hash function to distribute keys across the array. It also handles collisions by using linked lists for each bucket in the hash table. 

