#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

int resolve_hostname(const char *hostname, u_char ip[], int type) {
    struct addrinfo hints;
    struct addrinfo *result = NULL;
    int ret;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    switch (type) {
        case 1:
            hints.ai_family = AF_INET; // Force IPv4
            break;
        case 2:
            hints.ai_family = AF_INET6; // Force IPv6
            break;
        default:
            hints.ai_family = AF_UNSPEC; // Auto-detect
    }

    ret = getaddrinfo(hostname, NULL, &hints, &result);
    if (ret != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(ret));
        return -1; // Error code
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *) result->ai_addr;
    struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *) result->ai_addr;

    if (result->ai_family == AF_INET) { // IPv4
        memcpy(ip, &(ipv4->sin_addr), sizeof(struct in_addr));
    } else if (result->ai_family == AF_INET6) { // IPv6
        memcpy(ip, &(ipv6->sin6_addr), sizeof(struct in6_addr));
    } else {
        fprintf(stderr, "Unknown address family\n");
        freeaddrinfo(result);
        return -1; // Error code
    }

    freeaddrinfo(result);
    return 0; // Success
}
```
