    NR_Uplink_Scheduling_GRANT_TAG tag;
    int UE_ID;
} NR_Uplink_Scheduling_GRANT;

#define MAX_ENTRIES 10000
#define CACHE_SIZE 1000

NR_Uplink_Scheduling_GRANT* cache[CACHE_SIZE];
int cache_index = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void handle_memory_allocation_failure() {
    // Handle memory allocation failure gracefully
}

NR_Uplink_Scheduling_GRANT* get_entry(int UE_ID) {
    pthread_mutex_lock(&lock);

    NR_Uplink_Scheduling_GRANT* entry = NULL;
    for (int i = 0; i < cache_index; ++i) {
        if (cache[i]->UE_ID == UE_ID) {
            entry = cache[i];
            break;
        }
    }

    pthread_mutex_unlock(&lock);
    return entry;
}

void add_entry(NR_Uplink_Scheduling_GRANT* grant) {
    pthread_mutex_lock(&lock);

    if (cache_index >= CACHE_SIZE) {
        handle_memory_allocation_failure();
    } else {
        cache[cache_index++] = grant;
    }

    pthread_mutex_unlock(&lock);
}

void remove_entry(int UE_ID) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < cache_index; ++i) {
        if (cache[i]->UE_ID == UE_ID) {
            free(cache[i]);

            // Shift all elements after the removed one to fill the gap
            for (int j = i; j < cache_index - 1; ++j) {
                cache[j] = cache[j + 1];
            }

            --cache_index;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
This code provides a basic thread-safe implementation of a dynamic array with caching. It uses a simple cache to store recently accessed entries, and it handles memory allocation failures by calling `handle_memory_allocation_failure()`. The function `get_entry(int UE_ID)` retrieves an entry from the cache if it exists, `add_entry(NR_Uplink_Scheduling_GRANT* grant)` adds a new entry to the cache, and `remove_entry(int UE_ID)` removes an entry from the cache.
