int isPrime(int n) {
    if (n <= 1) return 0;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return 0;
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* createAndPopulateArray(int N, int RX_UE_INFORMATION_TAG, int RNTI) {
