    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        array[i].RNTI = RNTI;

        if (isPrime(RNTI)) {
            array[i].CRC_INDICATION_REL8_TAG = rand();  // set CRCFLAG to a random value if RNTI is prime
        } else {
            array[i].CRC_INDICATION_REL8_TAG = 0;
        }
