    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    size_t count;
    pthread_rwlock_t lock;
} List;

size_t MemoryAllocationFailures = 0;
const int MAX_MEMORY_USAGE = 1024 * 1024 * 500; // 500MB
const int MAX_ENTRIES = MAX_MEMORY_USAGE / sizeof(NFAPI_CRC_INDICATION_PDU_T);
const int MIN_RNTI = 0, MAX_RNTI = 16384;

List* create_list() {
    List* list = malloc(sizeof(List));
    if (list == NULL) {
        log_error("Failed to allocate memory for the list");
        MemoryAllocationFailures++;
        return NULL;
    }

    pthread_rwlock_init(&list->lock, NULL);
    list->head = NULL;
    list->count = 0;
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }

    pthread_rwlock_destroy(&list->lock);
    free(list);
}

void add_entry(List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (data->RNTI < MIN_RNTI || data->RNTI > MAX_RNTI) {
        log_error("Invalid RNTI detected");
        return;
    }

    pthread_rwlock_wrlock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        log_error("Maximum entries limit reached");
        pthread_rwlock_unlock(&list->lock);
        return;
    }

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        log_error("Failed to allocate memory for a node");
        MemoryAllocationFailures++;
        pthread_rwlock_unlock(&list->lock);
        return;
    }

    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    pthread_rwlock_unlock(&list->lock);
}
```

