#include <stdlib.h>
#include <pthread.h>
#include <glib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_PDU_COUNT 1024

GHashTable* hash = NULL;
pthread_mutex_t lock;

void init() {
    pthread_mutex_init(&lock, NULL);
    hash = g_hash_table_new(g_direct_hash, g_direct_equal);
}

int addPDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu == NULL || hash == NULL) return -1;

    pthread_mutex_lock(&lock);
    gpointer oldValue = g_hash_table_lookup(hash, &pdu->RNTI);
    if (oldValue != NULL) {
        // Duplicate RNTI found. Handle it as you wish.
        pthread_mutex_unlock(&lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* newPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newPdu == NULL) {
        pthread_mutex_unlock(&lock);
        return -1; // Failed to allocate memory.
    }

    *newPdu = *pdu;
    g_hash_table_insert(hash, &newPdu->RNTI, newPdu);
    pthread_mutex_unlock(&lock);
    return 0; // Successfully added.
}

NFAPI_CRC_INDICATION_PDU_T* getPDU(int RNTI) {
    if (hash == NULL) return NULL;

    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = g_hash_table_lookup(hash, &RNTI);
    pthread_mutex_unlock(&lock);
    return pdu;
}

void removePDU(int RNTI) {
    if (hash == NULL) return;

    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = g_hash_table_lookup(hash, &RNTI);
    if (pdu != NULL) {
        g_hash_table_remove(hash, &RNTI);
        free(pdu);
    }
    pthread_mutex_unlock(&lock);
}
