        CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    };

    class NFAPIListManager {
    public:
        static const size_t MAX_PDU_COUNT = 1024;

        NFAPIListManager() : rng_(std::random_device{}()) {}
        ~NFAPIListManager();

        void add(const NFAPI_CRC_INDICATION_PDU_T& pdu);
        bool remove(uint32_t RNTI);
        size_t size() const;

    private:
        std::vector<NFAPI_CRC_INDICATION_PDU_T> list_;
        mutable std::mutex mtx_;
        static std::mt19937 rng_;

        bool isFull() const { return list_.size() >= MAX_PDU_COUNT; }
    };

    NFAPIListManager::~NFAPIListManager() = default;

    void NFAPIListManager::add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mtx_);

        if (isFull()) throw std::runtime_error("List is full");

        auto it = std::find_if(list_.begin(), list_.end(), [&pdu](const NFAPI_CRC_INDICATION_PDU_T& item) { return item.RNTI == pdu.RNTI; });
