    char filename[256];
    napi_get_cb_info(env, info, &argc, NULL, NULL, NULL);

    if (argc < 1 || napi_get_value_string_utf8(env, argv[0], filename, 256, NULL) != napi_ok) {
        napi_throw_type_error(env, NULL, "Wrong arguments");
        return NULL;
    }

    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        napi_throw_error(env, NULL, "File not found");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    char* buffer = malloc(size + 1);
    if (buffer == NULL) {
        napi_throw_error(env, NULL, "Memory allocation failed");
        return NULL;
    }

    fread(buffer, 1, size, file);
    fclose(file);

    napi_value result;
    NAPI_CALL(env, napi_create_string_utf8(env, buffer, size, &result));
    free(buffer);

    return result;
}
