```c
#include <pthread.h>
#include <stdlib.h>

typedef struct {
    // MAC_HEADER and MAC_FRAME fields here...
} NICP_MESSAGE;

typedef struct {
    // ETH_FRAME_INFO fields here...
} ETH_FRAME_INFO;

typedef struct Node {
    NICP_MESSAGE* message;
    ETH_FRAME_INFO* frameInfo;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int maxSize = 1000; // Maximum size of the collection.

void addMessage(NICP_MESSAGE* message, ETH_FRAME_INFO* frameInfo) {
    pthread_mutex_lock(&lock);

    if (head == NULL) {
        head = malloc(sizeof(Node));
        head->message = message;
        head->frameInfo = frameInfo;
        head->next = NULL;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            if (current == head && current->next == head) break; // Avoid infinite loop.
            current = current->next;
        }

        if (current != head) {
            Node* newNode = malloc(sizeof(Node));
            newNode->message = message;
            newNode->frameInfo = frameInfo;
            newNode->next = NULL;
            current->next = newNode;
        }
    }

    pthread_mutex_unlock(&lock);
}

void removeMessage(NICP_MESSAGE* message) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL && current->message != message) {
        if (current == head && current->next == head) break; // Avoid infinite loop.
        current = current->next;
    }

    if (current != NULL) {
        Node* temp = current->next;
        free(current);
        current = temp;
    }

    pthread_mutex_unlock(&lock);
}
```
This code uses a linked list to manage the collection of messages. It also uses a mutex for thread safety, which ensures that only one thread can access and modify the collection at any given time, preventing data corruption. 

Please note that this is a very basic implementation and does not include all the features you mentioned (like dynamic allocation of ETH_FRAME_INFO structures, handling variable message sizes etc.). You would need to add these features according to your specific requirements. Also, please make sure to handle memory deallocation properly when removing messages or when cleaning up the collection.
