["Here is a basic implementation of such a system in C using a hash table for efficient lookup by `rnti`. This solution assumes that you have access to a thread-safe hash table library or can implement one yourself. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    int rnti;
    // other fields...
} LTE_PHY_PacketInfo;

// Hash table node
typedef struct Node {
    LTE_PHY_PacketInfo* packet;
    struct Node* next;
} Node;

// Hash table
typedef struct {
    pthread_mutex_t lock;
    Node** buckets;
    int size;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable* ht = malloc(sizeof(HashTable));
    assert(ht != NULL);

    ht->buckets = calloc(size, sizeof(Node*));
    assert(ht->buckets != NULL);

    pthread_mutex_init(&ht->lock, NULL);
    ht->size = size;

    return ht;
}

unsigned int hash(int rnti, int size) {
    // Simple hash function for demonstration purposes. 
    // Replace with a more efficient one in production code.
    return rnti % size;
}

void add_packet(HashTable* ht, LTE_PHY_PacketInfo* packet) {
    unsigned int index = hash(packet->rnti, ht->size);

    pthread_mutex_lock(&ht->lock);

    Node* node = malloc(sizeof(Node));
    assert(node != NULL);

    node->packet = packet;
    node->next = ht->buckets[index];
    ht->buckets[index] = node;

    pthread_mutex_unlock(&ht->lock);
}

LTE_PHY_PacketInfo* get_packet(HashTable* ht, int rnti) {
    unsigned int index = hash(rnti, ht->size);

    pthread_mutex_lock(&ht->lock);

    Node* node;
    for (node = ht->buckets[index]; node != NULL; node = node->next) {
        if (node->packet->rnti == rnti) {
            pthread_mutex_unlock(&ht->lock);
            return node->packet;
        }
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL;  // Packet not found
}
```
