#include <pthread.h>

typedef struct {
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    int PORT_NUMBER;
} TCP_PACKET_STATS_T;

typedef struct {
    TCP_PACKET_STATS_T **array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} Array;

void initArray(Array *a, size_t initialSize) {
    a->array = (TCP_PACKET_STATS_T **)malloc(initialSize * sizeof(TCP_PACKET_STATS_T*));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insertArray(Array *a, TCP_PACKET_STATS_T *element) {
    pthread_mutex_lock(&a->lock);

    if (a->used == a->size) {
        a->size *= 2;
        a->array = (TCP_PACKET_STATS_T **)realloc(a->array, a->size * sizeof(TCP_PACKET_STATS_T*));
    }

    for (int i = 0; i < a->used; ++i) {
        if (!strcmp(element->SOURCE_IP, a->array[i]->SOURCE_IP) && 
            !strcmp(element->DESTINATION_IP, a->array[i]->DESTINATION_IP) && 
            element->PORT_NUMBER == a->array[i]->PORT_NUMBER) {
            pthread_mutex_unlock(&a->lock);
            return;
        }
    }

    a->array[a->used++] = element;

    pthread_mutex_unlock(&a->lock);
}

void freeArray(Array *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
    pthread_mutex_destroy(&a->lock);
}
