typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

List* createList() {
    List* list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroyList(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int addElement(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) return -1; // Out of memory

    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

int removeElement(List* list, int index) {
    if (index < 0 || list->head == NULL) return -1; // Invalid index or empty list

    pthread_mutex_lock(&list->mutex);

    Node dummyHead = { .next = list->head };
    Node* current = &dummyHead;

    for (int i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (current == NULL || current->next == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Invalid index or end of list reached
    }

    Node* temp = current->next;
    current->next = temp->next;
    free(temp);

    if (index == 0) {
        list->head = dummyHead.next; // Update head if necessary
    }

    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

int updateElement(List* list, int index, NFAPI_CRC_INDICATION_PDU_T data) {
    if (index < 0 || list->head == NULL) return -1; // Invalid index or empty list

    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    for (int i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Invalid index or end of list reached
    }

    current->data = data;

    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}
```
