typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    LTE_PHY_MEASUREMENTS_T *measurements;
} MeasurementArray;

int initMeasurementArray(MeasurementArray *array, size_t initialCapacity) {
    array->capacity = initialCapacity;
    array->size = 0;
    array->measurements = malloc(initialCapacity * sizeof(LTE_PHY_MEASUREMENTS_T));

    if (array->measurements == NULL) {
        return -1; // Failed to allocate memory
    }

    pthread_mutex_init(&array->lock, NULL);

    return 0; // Success
}

void addMeasurement(MeasurementArray *array, LTE_PHY_MEASUREMENTS_T measurement) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        // Double the capacity when full
        array->capacity *= 2;
        array->measurements = realloc(array->measurements, array->capacity * sizeof(LTE_PHY_MEASUREMENTS_T));

        if (array->measurements == NULL) {
            // Failed to allocate memory, handle error here...
        }
    }

    array->measurements[array->size++] = measurement;

    pthread_mutex_unlock(&array->lock);
}

LTE_PHY_MEASUREMENTS_T getLastMeasurement(MeasurementArray *array) {
    LTE_PHY_MEASUREMENTS_T result = {0, 0}; // Default value

    pthread_mutex_lock(&array->lock);

    if (array->size > 0) {
        result = array->measurements[array->size - 1];
    }

    pthread_mutex_unlock(&array->lock);

    return result;
}

void freeMeasurementArray(MeasurementArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->measurements);
}
```
