['Here is an example implementation using a linked list to manage dynamic allocations. The function uses pthread mutex locks to ensure thread safety, and periodically cleans up unused message structures based on the `cleanup_interval` parameter. 

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct LTE_ENB_RRC_MESSAGE {
    // Add your structure fields here
} LTE_ENB_RRC_MESSAGE;

typedef struct Node {
    LTE_ENB_RRC_MESSAGE *message;
    time_t last_accessed;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t cleanup_interval = 60; // Clean up unused messages every 60 seconds

void addMessage(LTE_ENB_RRC_MESSAGE *message) {
    Node *newNode = malloc(sizeof(Node));
    newNode->message = message;
    newNode->last_accessed = time(NULL);

    pthread_mutex_lock(&lock);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
}

LTE_ENB_RRC_MESSAGE *getMessage() {
    if (head == NULL) return NULL; // No messages available

    LTE_ENB_RRC_MESSAGE *message = head->message;
    Node *temp = head;
    head = head->next;
    free(temp);

    return message;
}

void cleanupMessages() {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&lock);
    Node *currentNode = head, *previousNode = NULL;
    while (currentNode != NULL) {
        if (difftime(currentTime, currentNode->last_accessed) > cleanup_interval) {
            // Remove the node from the list and free its memory
            if (previousNode == NULL) head = currentNode->next;
            else previousNode->next = currentNode->next;

            Node *temp = currentNode;
            currentNode = currentNode->next;
            free(temp);
        } else {
            // Move to the next node
            previousNode = currentNode;
            currentNode = currentNode->next;
        }
    }
    pthread_mutex_unlock(&lock);
}
```
This code provides a basic implementation of a thread-safe linked list for managing dynamic allocations. It uses a mutex lock to ensure that only one thread can access the linked list at a time, preventing race conditions and ensuring thread safety. The `cleanupMessages` function periodically removes unused message structures from the list based on their last accessed time.
']

