typedef struct DynamicArray {
    pthread_mutex_t lock;
    TrafficEvent** events;
    size_t capacity;
    size_t length;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array->capacity = 10;
    array->length = 0;
    array->events = malloc(sizeof(TrafficEvent*) * array->capacity);
    if (array->events == NULL) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void addEvent(DynamicArray* array, TrafficEvent* event) {
    pthread_mutex_lock(&array->lock);

    if (array->length == array->capacity) {
        array->capacity *= 2;
        array->events = realloc(array->events, sizeof(TrafficEvent*) * array->capacity);
    }

    array->events[array->length++] = event;

    pthread_mutex_unlock(&array->lock);
}

// Other functions like updateEvent and getEventsWithinRange are similar.
