    ProcessedData* results[count];

    // Create a thread for each string to be processed and encrypted
    for (size_t i = 0; i < count; ++i) {
        if(pthread_create(&threads[i], NULL, processAndEncrypt, &data[i])) {
            fprintf(stderr, "Error creating thread\n");
            return; // or handle error appropriately
        }
