['Here is a basic implementation in C for your requirements. This code does not include all the features you mentioned like custom memory pool or checksum validation but it gives an idea about how to manage linked list with dynamic allocation and serialization/deserialization. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createList(int n) {
    srand(time(0));
    Node *head = NULL, *tail = NULL;

    for (int i = 0; i < n; ++i) {
        Node* new_node = malloc(sizeof(Node));

        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        new_node->data.RX_UE_INFORMATION_TAG = i;
        new_node->data.RNTI = rand();
        new_node->data.CRC_INDICATION_REL8_TAG = 0;
        new_node->data.CRCFLAG = rand() % 2;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    return head;
}

void serializeList(Node* head, const char *filename) {
    FILE *file = fopen(filename, "wb");

    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    for (Node* node = head; node != NULL; node = node->next) {
        if (fwrite(&node->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            perror("Failed to write data");
            break;
        }
    }

    fclose(file);
}

Node* deserializeList(const char *filename) {
    FILE *file = fopen(filename, "rb");

    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    Node *head = NULL, *tail = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;

    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        Node* new_node = malloc(sizeof(Node));

        if (!new_node) {
            perror("Memory allocation failed");
            break;
        }

        new_node->data = data;

        if (!head) {
            head = tail = new_node;
