['Here is a basic implementation of your requirements using C language. It uses a linked list for managing configurations and pthreads for thread safety. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_PHY_TEST_CONFIG_T {
    int frequency;
    char modulation[20]; // assuming a max length of 19 characters for the modulation scheme
    struct LTE_PHY_TEST_CONFIG_T *next;
} LTE_PHY_TEST_CONFIG_T;

typedef struct {
    LTE_PHY_TEST_CONFIG_T *head;
    pthread_mutex_t lock;
} ConfigList;

ConfigList configList = {NULL, PTHREAD_MUTEX_INITIALIZER};

void addConfiguration(int frequency, char* modulation) {
    LTE_PHY_TEST_CONFIG_T *newNode = malloc(sizeof(LTE_PHY_TEST_CONFIG_T));
    newNode->frequency = frequency;
    strncpy(newNode->modulation, modulation, sizeof(newNode->modulation) - 1);
    newNode->next = NULL;

    pthread_mutex_lock(&configList.lock);
    if (configList.head == NULL) {
        configList.head = newNode;
    } else {
        LTE_PHY_TEST_CONFIG_T *current = configList.head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&configList.lock);
}

void removeConfiguration(int frequency) {
    pthread_mutex_lock(&configList.lock);
    LTE_PHY_TEST_CONFIG_T *current = configList.head;
    LTE_PHY_TEST_CONFIG_T *previous = NULL;

    while (current != NULL) {
        if (current->frequency == frequency) {
            if (previous == NULL) {
                configList.head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&configList.lock);
}

void updateModulationScheme(int frequency, char* modulation) {
    pthread_mutex_lock(&configList.lock);
    LTE_PHY_TEST_CONFIG_T *current = configList.head;

    while (current != NULL) {
        if (current->frequency == frequency) {
            strncpy(current->modulation, modulation, sizeof(current->modulation) - 1);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&configList.lock);
}
```
This code provides a basic implementation of the requirements you specified. It uses a linked list to manage configurations and pthreads for thread safety. The `addConfiguration` function adds a new configuration at the end of the list, the `removeConfiguration` function removes an existing configuration by frequency, and the `updateModulationScheme` function updates the modulation scheme for a specific frequency.
