```c
#include <stdio.h>
#include <dlfcn.h>
#include <pthread.h>

typedef struct {
    void *handle;
    char *(*hash_func)(const char*);
} crypto_algorithm_t;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

crypto_algorithm_t load_algorithm(const char *path, const char *symbol) {
    crypto_algorithm_t algorithm;

    // Load the library
    algorithm.handle = dlopen(path, RTLD_LAZY);
    if (!algorithm.handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        return algorithm;
    }

    // Get the hash function symbol
    dlerror();  // Clear any existing error
    *(void **)(&algorithm.hash_func) = dlsym(algorithm.handle, symbol);
    char *error = dlerror();
    if (error != NULL) {
        fprintf(stderr, "Failed to load symbol: %s\n", error);
        return algorithm;
    }

    return algorithm;
}

char *execute_algorithm(crypto_algorithm_t algorithm, const char *input) {
    pthread_mutex_lock(&lock);
    char *result = (*algorithm.hash_func)(input);
    pthread_mutex_unlock(&lock);

    return result;
}
```
This code uses the dynamic linking library (dlfcn) to load and execute cryptographic algorithms at runtime. It also includes a mutex for thread-safe operations. 

