    manager->events = malloc(sizeof(TrafficEvent*) * initialCapacity);
    pthread_mutex_init(&manager->lock, NULL);
}

void addEvent(EventManager* manager, TrafficEvent* event) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        manager->events = realloc(manager->events, sizeof(TrafficEvent*) * manager->capacity);
    }

    manager->events[manager->count++] = event;

    pthread_mutex_unlock(&manager->lock);
}

// This function is not thread safe and assumes that the UIDs are unique. 
TrafficEvent* getEventByUID(EventManager* manager, int uid) {
    for (size_t i = 0; i < manager->count; ++i) {
        TrafficEvent* event = manager->events[i];

        for (int j = 0; j < sizeof(event->uids)/sizeof(int); ++j) {
            if (event->uids[j] == uid) {
                return event;
            }
        }
    }

    return NULL;
}
```
