public static ConcurrentBag<NFAPI_CRC_INDICATION_PDU_T> ParseAndLogNfaPdu(string xml, string elementName)
{
    var pdus = new ConcurrentBag<NFAPI_CRC_INDICATION_PDU_T>();

    try
    {
        XmlDocument doc = new XmlDocument();
        doc.LoadXml(xml);

        XPathNavigator navigator = doc.CreateNavigator();
        XPathNodeIterator iterator = navigator.Select(elementName);

        while (iterator.MoveNext())
        {
            var pdu = new NFAPI_CRC_INDICATION_PDU_T()
            {
                RX_UE_INFORMATION_TAG = iterator.Current?.GetAttribute("RX_UE_INFORMATION_TAG", string.Empty),
