typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createList(int n) {
    srand(time(0));
    Node *head = NULL, *temp = NULL;

    for (int i = 0; i < n; ++i) {
        temp = malloc(sizeof(Node));

        if (!temp) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        temp->data.RX_UE_INFORMATION_TAG = i;
        temp->data.RNTI = rand();
        temp->data.CRC_INDICATION_REL8_TAG = rand() % 2;
        temp->next = head;
        head = temp;
    }

    return head;
}

void serializeList(Node* head, const char *filename) {
    FILE *file = fopen(filename, "wb");

    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    while (head) {
        if (fwrite(&head->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            perror("Failed to write data");
            exit(EXIT_FAILURE);
        }

        head = head->next;
    }

    fclose(file);
}

Node* deserializeList(const char *filename) {
    FILE *file = fopen(filename, "rb");

    if (!file) {
        perror("Failed to open file for reading");
        exit(EXIT_FAILURE);
    }

    Node *head = NULL, *temp = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;

    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        temp = malloc(sizeof(Node));

        if (!temp) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        temp->data = data;
        temp->next = head;
        head = temp;
    }

    fclose(file);
    return head;
}
```
