#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherInstance;

void initialize(CipherInstance* instance, const char* password, int ivLength) {
    // Generate a salt
    unsigned char salt[8];
    RAND_bytes(salt, sizeof(salt));

    // Derive key using SHA-256 and the given password
    PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), salt, sizeof(salt), 1000, EVP_MAX_KEY_LENGTH, instance->key);

    // Generate IV
    RAND_bytes(instance->iv, ivLength);

    // Initialize cipher context
    instance->ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(instance->ctx, EVP_aes_256_cbc(), NULL, instance->key, instance->iv);
}

void encrypt(CipherInstance* instance, const unsigned char* plaintext, int plaintextLength, unsigned char* ciphertext) {
    // Encrypt the data
    int len;
    EVP_EncryptUpdate(instance->ctx, ciphertext, &len, plaintext, plaintextLength);
}

void decrypt(CipherInstance* instance, const unsigned char* ciphertext, int ciphertextLength, unsigned char* plaintext) {
    // Decrypt the data
    int len;
    EVP_DecryptUpdate(instance->ctx, plaintext, &len, ciphertext, ciphertextLength);
}

void cleanup(CipherInstance* instance) {
    // Clean up and free resources
    OPENSSL_cleanse(instance->key, sizeof(instance->key));
    OPENSSL_cleanse(instance->iv, sizeof(instance->iv));
    EVP_CIPHER_CTX_free(instance->ctx);
}
