typedef struct {
    GHashTable* table;
    pthread_mutex_t lock;
} MessageStore;

MessageStore store = { .table = NULL, .lock = PTHREAD_MUTEX_INITIALIZER };

void init_store(int max_size) {
    if (store.table == NULL) {
        pthread_mutex_lock(&store.lock);
        if (store.table == NULL) {
            store.table = g_hash_table_new_full(g_str_hash, g_str_equal, free, NULL);
            g_hash_table_set_max_load(store.table, max_size);
        }
        pthread_mutex_unlock(&store.lock);
    }
}

void add_message(const char* ue_id, NFAPI_MESSAGE_PDU_T* message) {
    if (store.table == NULL) init_store(1024); // Default max size

    pthread_mutex_lock(&store.lock);
    gpointer old_message = g_hash_table_lookup(store.table, ue_id);
    if (old_message == NULL) {
        NFAPI_MESSAGE_PDU_T* new_message = malloc(sizeof(NFAPI_MESSAGE_PDU_T));
        memcpy(new_message, message, sizeof(NFAPI_MESSAGE_PDU_T));
        g_hash_table_insert(store.table, strdup(ue_id), new_message);
    } else {
        // Handle conflict resolution here
    }
    pthread_mutex_unlock(&store.lock);
}

NFAPI_MESSAGE_PDU_T* get_message(const char* ue_id) {
    if (store.table == NULL) return NULL;

    pthread_mutex_lock(&store.lock);
    NFAPI_MESSAGE_PDU_T* message = g_hash_table_lookup(store.table, ue_id);
    pthread_mutex_unlock(&store.lock);

    return message;
}

void destroy_store() {
    if (store.table != NULL) {
        pthread_mutex_lock(&store.lock);
        g_hash_table_destroy(store.table);
        store.table = NULL;
        pthread_mutex_unlock(&store.lock);
    }
}
```
