} NetworkInterfaceStatistics;

typedef struct {
    NetworkInterfaceStatistics* stats;
    size_t count;
    size_t max_size;
} StatisticsManager;

void init_manager(StatisticsManager* manager, size_t initial_size) {
    manager->stats = (NetworkInterfaceStatistics*) malloc(initial_size * sizeof(NetworkInterfaceStatistics));
    manager->count = 0;
    manager->max_size = initial_size;
}

void add_statistic(StatisticsManager* manager, NetworkInterfaceStatistics stat) {
    if (manager->count == manager->max_size) {
        // Reallocate memory when the maximum size is reached
        manager->max_size *= 2;
        manager->stats = (NetworkInterfaceStatistics*) realloc(manager->stats, manager->max_size * sizeof(NetworkInterfaceStatistics));
    }

    // Add new statistic to the end of the array
    manager->stats[manager->count++] = stat;
}

void update_statistic(StatisticsManager* manager, int index, NetworkInterfaceStatistics stat) {
    if (index >= 0 && index < manager->count) {
        // Update existing statistic at the specified index
        manager->stats[index] = stat;
    }
}

double calculate_average(int* values, size_t count) {
    double sum = 0.0;

    for (size_t i = 0; i < count; ++i) {
        sum += values[i];
    }

    return sum / count;
}

double calculate_average_packet_count(StatisticsManager* manager, time_t start_time, time_t end_time) {
    int packet_sum = 0;
    size_t count = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->stats[i].timestamp >= start_time && manager->stats[i].timestamp <= end_time) {
            packet_sum += manager->stats[i].packet_count;
            ++count;
        }
    }

    return calculate_average(&packet_sum, count);
}

double calculate_average_byte_count(StatisticsManager* manager, time_t start_time, time_t end_time) {
    int byte_sum = 0;
    size_t count = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->stats[i].timestamp >= start_time && manager->stats[i].timestamp <= end_time) {
            byte_sum += manager->stats[i].byte_count;
            ++count;
        }
    }

    return calculate_average(&byte_sum, count);
}
```
