enum class EventSeverity { Low, Medium, High };

struct NetworkEvent {
    std::chrono::time_point<std::chrono::system_clock> Timestamp;
    EventSeverity Severity;
    std::string EventDetails;
};

class DynamicEventProcessor {
private:
    struct GeneratorConfig {
        int seed;
        double minValue, maxValue;
        bool isInteger;
    };

    std::vector<NetworkEvent> events;
    std::mutex mtx;
    std::map<std::string, GeneratorConfig> generators;

public:
    void addEvent(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mtx);
        events.push_back(event);
    }

    void removeOldEvents(std::chrono::duration<double> duration) {
        auto now = std::chrono::system_clock::now();

        std::lock_guard<std::mutex> lock(mtx);
        events.erase(std::remove_if(events.begin(), events.end(), [&](const NetworkEvent& event) {
            return now - event.Timestamp > duration;
        }), events.end());
    }

    std::vector<NetworkEvent> getEventsBySeverity(EventSeverity severity) const {
        std::lock_guard<std::mutex> lock(mtx);

        std::vector<NetworkEvent> result;
        for (const auto& event : events) {
            if (event.Severity == severity) {
                result.push_back(event);
            }
        }
        return result;
    }

    void addGenerator(const std::string& name, int seed, double minValue, double maxValue, bool isInteger) {
        std::lock_guard<std::mutex> lock(mtx);
        generators[name] = GeneratorConfig{seed, minValue, maxValue, isInteger};
    }

    void adjustGeneratorRange(const std::string& name, double newMinValue, double newMaxValue) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = generators.find(name);
        if (it != generators.end()) {
            GeneratorConfig& config = it->second;

            // Ensure that the new range does not overlap with previously generated values
            if (config.minValue < newMinValue || config.maxValue > newMaxValue) {
                throw std::runtime_error("New range overlaps with previously generated values");
            }

            config.minValue = newMinValue;
            config.maxValue = newMaxValue;
        } else {
            throw std::runtime_error("Generator not found");
        }
    }

    std::string serializeConfig(const std::string& name) const {
        auto it = generators.find(name);
        if (it != generators.end()) {
            const GeneratorConfig& config = it->second;

            return "Generator: " + name + 
                   ", Seed: " + std::to_string(config.seed) + 
                   ", MinValue: " + std::to_string(config.minValue) + 
                   ", MaxValue: " + std::to_string(config.maxValue);
        } else {
            throw std::runtime_error("Generator not found");
        }
    }

    virtual ~DynamicEventProcessor() = default;
};
```
