    if (stat(configFile, &buffer) != 0) {
        return NULL;  // File does not exist
    }

    srand((unsigned int)time(NULL));

    long* offsets = malloc(sizeof(long));
    if (!offsets) {
        return NULL;  // Memory allocation failed
    }

    int* keys = malloc(sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;  // Memory allocation failed
    }

    record** records = malloc(sizeof(record*));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;  // Memory allocation failed
    }

    for (int i = 0; i < sizeof(records)/sizeof(records[0]); ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            free(offsets);
            free(keys);
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;  // Memory allocation failed
        }

        records[i]->value = minValue + rand() % ((maxValue + 1) - minValue);
    }

    return records;
}
