        return NULL;
    }

    header_t *new_header = malloc(sizeof(header_t));
    strncpy(new_header->source_ip, source, 15);
    strncpy(new_header->dest_ip, dest, 15);
    new_header->sequence = sequence;

    return new_header;
}

void add_header(const char *source, const char *dest, unsigned int sequence) {
    pthread_mutex_lock(&lock);

    header_t *new_header = create_header(source, dest, sequence);
    if (new_header == NULL) {
        return;
    }

    node_t *current;
    node_t *node = malloc(sizeof(node_t));
    node->header = new_header;
    node->next = NULL;

    if (head == NULL) {
        head = node;
    } else {
        current = head;
        while (current->next != NULL) {
            current = current->next;
        }

        current->next = node;
    }

    pthread_mutex_unlock(&lock);
}

void remove_header(const char *source, const char *dest, unsigned int sequence) {
    pthread_mutex_lock(&lock);

    node_t *temp = head;
    node_t *prev = NULL;

    while (temp != NULL && 
           strcmp(temp->header->source_ip, source) != 0 && 
           strcmp(temp->header->dest_ip, dest) != 0 && 
           temp->header->sequence != sequence) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    if (prev != NULL) {
        prev->next = temp->next;
    } else {
        head = temp->next;
    }

    free(temp->header);
    free(temp);

    pthread_mutex_unlock(&lock);
}
