        $token = bin2hex(random_bytes(16));

        // Store the token in the cache with an expiration time
        $this->cache->set('authToken:' . $userId, $token, $expiryTime);

        return $token;
    }

    public function hashPassword($userId, $password) {
        // Fetch the user's salt from the database
        $salt = $this->db->get('salt:' . $userId);

        // Hash the password with the salt using a secure algorithm
        $hashedPassword = password_hash($password . $salt, PASSWORD_DEFAULT);

        return $hashedPassword;
    }

    public function verifyPassword($userId, $hashedPassword, $plainPassword) {
        // Fetch the user's salt from the database
        $salt = $this->db->get('salt:' . $userId);

        // Verify the password against the hashed password
        if (password_verify($plainPassword . $salt, $hashedPassword)) {
            return true;
        } else {
            return false;
        }
    }
}
