typedef struct MeasurementObject {
    // Define your measurement object here
} MeasurementObject;

MeasurementObject* measurements[10];
int num_measurements = 0;
sem_t semaphore;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* initialize_measurement(void* arg) {
    int index = *((int*)arg);

    // Acquire lock to ensure thread-safety
    pthread_mutex_lock(&mutex);

    if (index >= num_measurements) {
        // Handle error: Index out of bounds
        exit(1);
    }

    MeasurementObject* measurement = measurements[index];

    // Release lock
    pthread_mutex_unlock(&mutex);

    // Initialize and configure the measurement object here

    sem_post(&semaphore);  // Signal completion of initialization
}

void initialize_measurements() {
    if (num_measurements > 10) {
        // Handle error: Too many measurements
        exit(1);
    }

    for (int i = 0; i < num_measurements; ++i) {
        int* index = malloc(sizeof(*index));
        *index = i;

        pthread_t thread;
        if (pthread_create(&thread, NULL, initialize_measurement, index)) {
            // Handle error: Failed to create thread
            exit(1);
        }
    }

    for (int i = 0; i < num_measurements; ++i) {
        sem_wait(&semaphore);  // Wait for all threads to complete initialization
    }
}
```
This code creates a separate thread for each measurement object and uses a semaphore to signal when each thread has completed its initialization. The main thread waits on the semaphore until all threads have finished, ensuring that all measurements are accurately captured before proceeding. 

