typedef struct TCP_CONNECTION_INFO {
    // fields for the connection info
} TCP_CONNECTION_INFO;

typedef struct Node {
    TCP_CONNECTION_INFO* data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add(TCP_CONNECTION_INFO* info) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->data = info;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void remove(TCP_CONNECTION_INFO* info) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    Node* prev = NULL;

    while (temp != NULL && temp->data != info) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // not found

    if (prev == NULL) { 
        head = temp->next; // removing the first node
    } else {
        prev->next = temp->next;
    }

    free(temp);

    pthread_mutex_unlock(&lock);
}
