```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    char remote_ip[16];
    int port;
    char local_ip[16];
    char state[20];
} connection_t;

typedef struct node {
    connection_t *connection;
    struct node *next;
} node_t;

node_t *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_connection(char* remote_ip, int port, char* local_ip, char* state) {
    pthread_mutex_lock(&lock);

    node_t *current;
    for (current = head; current != NULL; current = current->next) {
        if (strcmp(current->connection->remote_ip, remote_ip) == 0 && 
            current->connection->port == port) {
            // Duplicate connection found. Handle it accordingly.
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    node_t *newNode = malloc(sizeof(node_t));
    newNode->connection = malloc(sizeof(connection_t));
    strcpy(newNode->connection->remote_ip, remote_ip);
    newNode->connection->port = port;
    strcpy(newNode->connection->local_ip, local_ip);
    strcpy(newNode->connection->state, state);

    if (head == NULL) {
        head = newNode;
    } else {
        node_t *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}
```
