typedef struct Sender {
    int sender_id;
    Message* messages;
    UT_hash_handle hh;
} Sender;

Sender* senders = NULL;
pthread_mutex_t senders_lock = PTHREAD_MUTEX_INITIALIZER;

void add_message(int sender_id, char* payload) {
    Message* message = malloc(sizeof(Message));
    message->sender_id = sender_id;
    message->timestamp = time(NULL);
    message->payload = strdup(payload);

    pthread_mutex_lock(&list_lock);
    message->next = message_list;
    message_list = message;
    pthread_mutex_unlock(&list_lock);

    Sender* sender;
    HASH_FIND_INT(senders, &sender_id, sender);
    if (!sender) {
        sender = malloc(sizeof(Sender));
        sender->sender_id = sender_id;
        sender->messages = NULL;

        pthread_mutex_lock(&senders_lock);
        HASH_ADD_INT(senders, sender_id, sender);
        pthread_mutex_unlock(&senders_lock);
    }

    message->next = sender->messages;
    sender->messages = message;
}

void remove_sender_messages(int sender_id) {
    Sender* sender;
    pthread_mutex_lock(&senders_lock);
    HASH_FIND_INT(senders, &sender_id, sender);

    if (sender) {
        Message* message = sender->messages;
        while (message) {
            Message* next = message->next;

            pthread_mutex_lock(&list_lock);
            if (message_list == message) {
                message_list = next;
            } else {
                Message* prev = message_list;
                while (prev->next != message) {
                    prev = prev->next;
                }
                prev->next = next;
            }
            pthread_mutex_unlock(&list_lock);

            free(message->payload);
            free(message);

            message = next;
        }

        HASH_DELETE(hh, senders, sender);
        free(sender);
    }

    pthread_mutex_unlock(&senders_lock);
}

Message* get_oldest_message(int sender_id) {
    Sender* sender;
    HASH_FIND_INT(senders, &sender_id, sender);

    if (sender) {
        Message* oldest = NULL;
        time_t oldest_timestamp = 0;

        for (Message* message = sender->messages; message != NULL; message = message->next) {
            if (!oldest || message->timestamp < oldest_timestamp) {
                oldest = message;
                oldest_timestamp = message->timestamp;
            }
        }

        return oldest;
    } else {
        return NULL;
    }
}
