#include <stdlib.h>
#include <pthread.h>

#define MAX_NFAPI_CRC_INDICATIONS 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
} DynamicList;

DynamicList* createList() {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (list == NULL) return NULL;

    list->count = 0;
    list->capacity = MAX_NFAPI_CRC_INDICATIONS;
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);

    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyList(DynamicList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}

int addElement(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);

        if (newData == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Error: Out of memory
        }

        list->data = newData;
        list->capacity = newCapacity;
    }

    list->data[list->count++] = element;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}
