["Here is a basic implementation in C using a hash table for managing messages. This code does not include all the features you mentioned like concurrency control, logging mechanism, error handling etc. These are complex topics that require careful design and testing to ensure correctness and performance. 

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    int sender_id;
    time_t timestamp;
    char* payload;
} Message;

Message* create_message(int sender_id, const char* payload) {
    Message* msg = malloc(sizeof(Message));
    if (msg == NULL) return NULL;

    msg->sender_id = sender_id;
    msg->timestamp = time(NULL);
    msg->payload = strdup(payload);

    return msg;
}

void destroy_message(Message* msg) {
    free(msg->payload);
    free(msg);
}

typedef struct MessageNode {
    Message* message;
    struct MessageNode* next;
} MessageNode;

MessageNode* create_node(int sender_id, const char* payload) {
    MessageNode* node = malloc(sizeof(MessageNode));
    if (node == NULL) return NULL;

    node->message = create_message(sender_id, payload);
    node->next = NULL;

    return node;
}

void destroy_node(MessageNode* node) {
    destroy_message(node->message);
    free(node);
}

typedef struct {
    MessageNode** table;
    size_t capacity;
} HashTable;

HashTable* create_table(size_t capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->capacity = capacity;
    table->table = calloc(capacity, sizeof(MessageNode*));

    return table;
}

void destroy_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        MessageNode* node = table->table[i];
        while (node != NULL) {
            MessageNode* next = node->next;
            destroy_node(node);
            node = next;
        }
    }

    free(table->table);
    free(table);
}

void add_message(HashTable* table, int sender_id, const char* payload) {
    size_t index = sender_id % table->capacity;
    MessageNode* node = create_node(sender_id, payload);

    if (table->table[index] == NULL) {
        table->table[index] = node;
    } else {
        MessageNode* current = table->table[index];
        while (current->next != NULL) {
            current = current->next;
        }

        current->next = node;
    }
}
