#include <openssl/evp.h>
#include <iostream>

EVP_CIPHER_CTX* performOperation(std::forward_list<std::string>& list, const std::string& target, const std::string& value, const std::string& operation) {
    EVP_CIPHER_CTX *ctx = nullptr;
    auto it = std::find(list.begin(), list.end(), target);

    if (it != list.end()) {
        // Perform the specified operation on the target string
        if (operation == "encrypt") {
            ctx = EVP_CIPHER_CTX_new();
            if (!EVP_EncryptInit(ctx, EVP_aes_256_cbc(), nullptr, nullptr)) {
                std::cerr << "Failed to initialize encryption context" << std::endl;
                return nullptr;
            }
        } else if (operation == "decrypt") {
            ctx = EVP_CIPHER_CTX_new();
            if (!EVP_DecryptInit(ctx, EVP_aes_256_cbc(), nullptr, nullptr)) {
                std::cerr << "Failed to initialize decryption context" << std::endl;
                return nullptr;
            }
        } else {
            std::cerr << "Unsupported operation: " << operation << std::endl;
            return nullptr;
        }
    } else {
        // Append the value string to the end of the list
        list.push_front(value);
    }

    return ctx;
}
```
