['Here is a basic implementation of `aggregateNetworkMetrics` in C. This is a simplified version and does not include all the features mentioned above, but it should give you an idea of how to start implementing such a function. 

```c
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/resource.h>

typedef struct {
    unsigned long bytesReceived;
    unsigned long bytesTransmitted;
    double packetLossRate;
    double averageLatency;
    double throughput;
} NetworkMetrics;

void early_error(const char* msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(1);
}

NetworkMetrics aggregateNetworkMetrics() {
    struct rusage usage;
    clock_t start = clock();

    NetworkMetrics metrics = {0};
    FILE *file = fopen("/path/to/metrics/file", "r");
    if (file == NULL) {
        early_error("Failed to open file.");
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        unsigned long bytesReceived;
        unsigned long bytesTransmitted;
        double packetLossRate;
        double averageLatency;
        double throughput;

        if (sscanf(line, "%lu %lu %lf %lf %lf", &bytesReceived, &bytesTransmitted, &packetLossRate, &averageLatency, &throughput) != 5) {
            early_error("Failed to parse line.");
        }

        metrics.bytesReceived += bytesReceived;
        metrics.bytesTransmitted += bytesTransmitted;
        metrics.packetLossRate += packetLossRate;
        metrics.averageLatency += averageLatency;
        metrics.throughput += throughput;
    }

    fclose(file);

    getrusage(RUSAGE_SELF, &usage);
    printf("CPU time: %ld\n", usage.ru_utime.tv_usec);
    printf("Memory usage: %ld\n", usage.ru_maxrss);
    printf("Execution time: %f\n", (double)(clock() - start)/CLOCKS_PER_SEC);

    return metrics;
}
```
This code reads network performance data from a file, parses it and populates the `NetworkMetrics` structure. It also measures CPU usage, memory usage and execution time using system-specific APIs. 

