["Here is an example of how you might start implementing such a library in C. This code does not cover all requirements, but it provides a starting point for creating a robust semaphore management library. 

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <unistd.h>

// Define the semaphore struct
typedef struct {
    sem_t *sem;
    int value;
} Semaphore;

// Initialize a semaphore with an initial value
Semaphore* init_sem(int value) {
    Semaphore *s = malloc(sizeof(Semaphore));
    if (s == NULL) return NULL;

    s->value = value;
    s->sem = malloc(sizeof(sem_t));
    if (s->sem == NULL || sem_init(s->sem, 0, value) != 0) {
        free(s);
        return NULL;
    }

    return s;
}

// Wait on a semaphore
void wait_sem(Semaphore *s) {
    if (s == NULL || s->value <= 0) return;

    sem_wait(s->sem);
    s->value--;
}

// Signal a semaphore
void signal_sem(Semaphore *s) {
    if (s == NULL) return;

    sem_post(s->sem);
    s->value++;
}

// Delete a semaphore
void delete_sem(Semaphore *s) {
    if (s == NULL) return;

    sem_destroy(s->sem);
    free(s->sem);
    free(s);
}
```
This is a basic implementation of a semaphore in C. It uses the POSIX semaphore library to manage semaphores, which should work on most Unix-like systems. However, this code does not include any logging framework or error handling mechanism, nor does it support dynamic adjustment of semaphore initial values based on runtime parameters.

