namespace RandomGen {
    std::mutex AdvancedMersenneTwister::mutex_;
    AdvancedMersenneTwister* AdvancedMersenneTwister::instance = nullptr;

    AdvancedMersenneTwister* AdvancedMersenneTwister::getInstance(unsigned int seed) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (instance == nullptr) {
            instance = new AdvancedMersenneTwister(seed);
        }
        return instance;
    }

    unsigned int AdvancedMersenneTwister::nextUInt() {
        std::lock_guard<std::mutex> lock(mutex_);
        return mt();
    }

    double AdvancedMersenneTwister::nextDouble() {
        std::lock_guard<std::mutex> lock(mutex_);
        return std::generate_canonical<double, 10>(mt);
    }

    void AdvancedMersenneTwister::resetSeed(unsigned int new_seed) {
        std::lock_guard<std::mutex> lock(mutex_);
        mt.seed(new_seed);
    }
}
