typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* head = NULL;
int totalIndications = 0;
int crcErrors = 0;
double averageErrorRate = 0.0;

void addNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) exit(-1); // handle allocation failure

    newNode->data = data;
    newNode->next = head;
    newNode->prev = NULL;

    if(head != NULL) {
        head->prev = newNode;
    }

    head = newNode;
}

void removeNode(Node* node) {
    if(node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        head = node->next;
    }

    if(node->next != NULL) {
        node->next->prev = node->prev;
    }

    free(node);
}

void processIndication(NFAPI_CRC_INDICATION_PDU_T indication) {
    addNode(indication);
    totalIndications++;

    if(indication.CRCFLAG == 1) {
        crcErrors++;
    }

    averageErrorRate = (double)crcErrors / totalIndications;
}

void serializeListToFile(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if(file == NULL) exit(-1); // handle file opening failure

    Node* node = head;
    while(node != NULL) {
        fwrite(&(node->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        node = node->next;
    }

    fclose(file);
}

void deserializeListFromFile(const char* filename) {
