    arr->capacity = 16;
    arr->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * arr->capacity);
}

void add(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T value) {
    if (atomic_load(&arr->count) == atomic_load(&arr->capacity)) {
        atomic_store(&arr->capacity, atomic_load(&arr->capacity) * 2);
        arr->data = realloc(arr->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * atomic_load(&arr->capacity));
    }

    size_t index = atomic_fetch_add(&arr->count, 1);
    arr->data[index] = value;
}

void removeByRNTI(DynamicArray *arr, int RNTI) {
    for (size_t i = 0; i < atomic_load(&arr->count); ++i) {
