#include <arpa/inet.h>

typedef struct {
    int socket;
    char ip[INET_ADDRSTRLEN];
    int port;
} Connection;

Connection* connections = NULL;
int connectionCount = 0;
int maxConnections = 1024; // You should set this based on your system's limits.

void addConnection(int socket, const char* ip, int port) {
    if (connectionCount >= maxConnections) {
        printf("Maximum number of connections reached.\n");
        return;
    }

    Connection* newArray = realloc(connections, sizeof(Connection) * (connectionCount + 1));
    if (!newArray) {
        perror("Failed to allocate memory for connection.");
        return;
    }
    connections = newArray;

    Connection* conn = &connections[connectionCount];
    conn->socket = socket;
    strncpy(conn->ip, ip, INET_ADDRSTRLEN);
    conn->port = port;

    connectionCount++;
}

void removeConnection(int index) {
    if (index < 0 || index >= connectionCount) {
        printf("Invalid connection index.\n");
        return;
    }

    close(connections[index].socket); // Close the socket.

    for (int i = index; i < connectionCount - 1; ++i) {
        connections[i] = connections[i + 1]; // Shift elements to fill the gap.
    }

    Connection* newArray = realloc(connections, sizeof(Connection) * (connectionCount - 1));
    if (!newArray) {
        perror("Failed to allocate memory for connection.");
        return;
    }
    connections = newArray;

    connectionCount--;
}

void checkIdleConnections() {
    // This is a placeholder. You would need to implement actual idle checking here.
    for (int i = 0; i < connectionCount; ++i) {
        if (isConnectionIdle(connections[i].socket)) {
            removeConnection(i);
            --i; // Decrement index so we don't skip a connection after shifting elements.
        }
    }
}
