int maxConcurrentProcessed = 10; // default value, can be adjusted at runtime

void* create_and_populate_crc_indications(void *arg) {
    int N = *((int *) arg);
    if (N == 0) return NULL;

    sem_wait(&semaphore); // wait for the semaphore
    pthread_mutex_lock(&mutex); // lock mutex to ensure thread safety

    if(maxConcurrentProcessed <= 0){
        pthread_mutex_unlock(&mutex); // unlock mutex before returning
        return NULL;
    }

    maxConcurrentProcessed--;
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    srand(time(NULL)); // initialize random seed

    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = i; // set a valid value here, you may need to fetch from external data source
        list[i].CRCFLAG = rand() % 2; // randomly set CRCFLAG
    }

    pthread_mutex_unlock(&mutex); // unlock mutex after modifying shared data
    sem_post(&semaphore); // signal the semaphore

