typedef struct {
    char* mac_id;
    // Add other security parameters here...
} SecurityConfig;

typedef struct {
    char* mac_id;
    SecurityConfig config;
} MACEntity;

typedef struct {
    MACEntity** entities;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray array = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

int addOrUpdate(char* mac_id, SecurityConfig config) {
    pthread_mutex_lock(&array.lock);

    for (size_t i = 0; i < array.count; ++i) {
        if (strcmp(mac_id, array.entities[i]->mac_id) == 0) {
            // Update existing entity
            free(array.entities[i]->config);
            array.entities[i]->config = config;

            pthread_mutex_unlock(&array.lock);
            return 1;
        }
    }

    // Add new entity
    MACEntity* newEntity = malloc(sizeof(MACEntity));
    if (newEntity == NULL) {
        pthread_mutex_unlock(&array.lock);
        return -1;
    }

    newEntity->mac_id = strdup(mac_id);
    if (newEntity->mac_id == NULL) {
        free(newEntity);
        pthread_mutex_unlock(&array.lock);
        return -1;
    }

    newEntity->config = config;

    array.entities = realloc(array.entities, (array.count + 1) * sizeof(MACEntity*));
    if (array.entities == NULL) {
        free(newEntity->mac_id);
        free(newEntity);
        pthread_mutex_unlock(&array.lock);
        return -1;
    }

    array.entities[array.count] = newEntity;
    ++array.count;

    pthread_mutex_unlock(&array.lock);
    return 0;
}
