List *createList() {
    List *list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->array = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (list->array == NULL) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = 1;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void addElement(List *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (pthread_mutex_lock(&list->lock)) {
        // handle error
        return;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->array[i]->RNTI == element->RNTI) {
            // log error and continue
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    if (list->count >= list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T **newArray = realloc(list->array, 2 * list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (newArray == NULL) {
            // handle error
            pthread_mutex_unlock(&list->lock);
            return;
        }

        list->array = newArray;
        list->capacity *= 2;
    }

    list->array[list->count++] = element;

    pthread_mutex_unlock(&list->lock);
}

void resetList(List *list) {
    if (pthread_mutex_lock(&list->lock)) {
        // handle error
        return;
    }

    for (size_t i = 0; i < list->count; ++i) {
        free(list->array[i]);
    }

    free(list->array);
    list->array = NULL;
    list->count = 0;
    list->capacity = 0;

    pthread_mutex_unlock(&list->lock);
}
