#include <stdio.h>
#include <pthread.h>
#include <time.h>

typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;

struct Logger {
    FILE *file;
    pthread_mutex_t lock;
};

void logger_init(struct Logger *logger) {
    logger->file = fopen("log.txt", "a");
    pthread_mutex_init(&logger->lock, NULL);
}

void logger_destroy(struct Logger *logger) {
    fclose(logger->file);
    pthread_mutex_destroy(&logger->lock);
}

void log_message(struct Logger *logger, LogLevel level, const char *message) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    pthread_mutex_lock(&logger->lock);
    fprintf(logger->file, "[%02d:%02d:%02d] ", timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    switch (level) {
        case DEBUG:
            fprintf(logger->file, "[DEBUG] ");
            break;
        case INFO:
            fprintf(logger->file, "[INFO] ");
            break;
        case WARNING:
            fprintf(logger->file, "[WARNING] ");
            break;
        case ERROR:
            fprintf(logger->file, "[ERROR] ");
            break;
    }

    fprintf(logger->file, "%s\n", message);
    pthread_mutex_unlock(&logger->lock);
}
```
