#include <string.h>

typedef struct PacketLossIndication {
    int sequenceNumber;
    int statusFlag;
    struct PacketLossIndication *next;
} PacketLossIndication;

typedef struct FrameStats {
    pthread_mutex_t lock;
    long timestamp;
    PacketLossIndication *packets;
} FrameStats;

FrameStats* initializeAndPopulate(int numCells, int numPacketsPerCell) {
    // Allocate memory for the array of FrameStats structures
    FrameStats *frameStats = malloc(numCells * sizeof(FrameStats));

    for (int i = 0; i < numCells; ++i) {
        frameStats[i].timestamp = 0;

        // Initialize the mutex for each cell's FrameStats structure
        pthread_mutex_init(&frameStats[i].lock, NULL);

        // Allocate memory for the linked list of PacketLossIndication structures
        frameStats[i].packets = malloc(numPacketsPerCell * sizeof(PacketLossIndication));

        for (int j = 0; j < numPacketsPerCell; ++j) {
            // Initialize each PacketLossIndication structure
            frameStats[i].packets[j].sequenceNumber = j + 1;
            frameStats[i].packets[j].statusFlag = 0;

            if (j < numPacketsPerCell - 1) {
                // Set the next pointer for each PacketLossIndication structure, except for the last one
                frameStats[i].packets[j].next = &frameStats[i].packets[j + 1];
            } else {
                // The last PacketLossIndication structure should have a NULL next pointer
                frameStats[i].packets[j].next = NULL;
            }
        }
    }

    return frameStats;
}
