#include <openssl/x509.h>
#include <openssl/pem.h>
#include <stdio.h>

X509 *load_certificate(const char *filepath, int strict) {
    FILE *fp = fopen(filepath, "rb");
    if (fp == NULL) {
        printf("Failed to open file: %s\n", filepath);
        return NULL;
    }

    X509 *certificate = NULL;
    char *ext = strrchr(filepath, '.');
    if (strcmp(ext, ".pem") == 0) {
        certificate = PEM_read_X509(fp, NULL, NULL, NULL);
    } else if (strcmp(ext, ".der") == 0) {
        certificate = d2i_X509_fp(fp, NULL);
    } else if (strcmp(ext, ".p7b") == 0 || strcmp(ext, ".pkcs7") == 0) {
        STACK_OF(PKCS7) * pkcs7Stack = PKCS7_read_der_fp(fp);
        if (sk_PKCS7_num(pkcs7Stack) > 0) {
            PKCS7 *pkcs7 = sk_PKCS7_value(pkcs7Stack, 0);
            certificate = PKCS7_get0_signers(pkcs7, NULL, 0)[0];
        }
    } else {
        printf("Unsupported file type: %s\n", ext);
    }

    fclose(fp);

    if (certificate == NULL) {
        printf("Failed to load certificate from file: %s\n", filepath);
        if (strict) {
            exit(1);
        }
    }

    return certificate;
