        newNode->next = NULL;

        if (head == NULL) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    return head;
}

int isUnique(NFAPI_CRC_INDICATION_PDU_T *head, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
