int safe_divide(size_t a, size_t b) {
    if (b == 0 || a > SIZE_MAX / b) {
        return -1;
    } else {
        return a / b;
    }
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_structures(size_t max_size, int *RX_UE_INFORMATION_TAG, int *RNTI) {
    if (max_size == 0 || RX_UE_INFORMATION_TAG == NULL || RNTI == NULL) {
        return -1; // Invalid input parameters
    }

    pthread_mutex_lock(&lock);

    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int num_structs = safe_divide(max_size, struct_size);

    if (num_structs == -1) {
        pthread_mutex_unlock(&lock);
        return -1; // Integer overflow during calculation
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(num_structs * struct_size);
    if (array == NULL) {
        pthread_mutex_unlock(&lock);
        return -1; // Failed to allocate memory
    }

