        // Check if the IP address is within a valid range (for example, 192.168.0.0 to 192.168.255.255)
        if (strncmp("192.168.", ip, 7) != 0) {
            printf("Invalid IP address: %s\n", ip);
            free(net_conf);
            return NULL;
        }

        // If no default gateway is provided, set it to "none"
        if (default_gateway == NULL) {
            strcpy(net_conf[i].ip, ip);
            strcpy(net_conf[i].subnet_mask, subnet_mask);
            strcpy(net_conf[i].default_gateway, "none");
        } else {
            strcpy(net_conf[i].ip, ip);
            strcpy(net_conf[i].subnet_mask, subnet_mask);
            strcpy(net_conf[i].default_gateway, default_gateway);
