        free(temp);

        sem_wait(&semaphore);

        return;
    }

    while (temp != NULL && temp->data->transactionId != transactionId) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // Message not found

    prev->next = temp->next;

    free(temp->data);
