int maxContexts = 5000; // Maximum number of contexts

// Function to add a UE Context
void addUeContext(UeContext context) {
    pthread_mutex_lock(&lock);

    if (getCount() >= maxContexts) {
        printf("Maximum number of contexts reached. Can't add more.\n");
        return;
    }

    Node* newNode = malloc(sizeof(Node));
    newNode->context = context;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

// Function to update a UE Context
void updateUeContext(int pduSessionId, UeContext updatedContext) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while (temp != NULL) {
        if (temp->context.pduSessionId == pduSessionId) {
            temp->context = updatedContext;
            break;
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}

// Function to delete a UE Context
void deleteUeContext(int pduSessionId) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    Node* prev = NULL;

    while (temp != NULL && temp->context.pduSessionId != pduSessionId) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // Context not found

    if (prev != NULL) prev->next = temp->next;

    if (head == temp) head = temp->next;

    free(temp);

    pthread_mutex_unlock(&lock);
}

// Function to get the count of UE Contexts
int getCount() {
    int count = 0;
    Node* temp = head;
    while (temp != NULL) {
        count++;
        temp = temp->next;
    }
    return count;
}
