    // Allocate memory for the array of pointers to messages
    UDP_TRANSPORT_MESSAGE** messages = malloc(count * sizeof(UDP_TRANSPORT_MESSAGE*));

    if (messages == NULL) {
        return NULL; // Allocation failed
    }

    for (size_t i = 0; i < count; ++i) {
        messages[i] = malloc(sizeof(UDP_TRANSPORT_MESSAGE));

        if (messages[i] == NULL) {
            // Allocation failed, clean up and return NULL
            for (--i; i >= 0; --i) {
                free(messages[i]);
            }

            free(messages);
            return NULL;
        }

        messages[i]->source_port = rand() % UINT16_MAX; // Random source port
        messages[i]->destination_port = rand() % UINT16_MAX; // Random destination port

        // Allocate memory for the payload
        messages[i]->payload = malloc(payloadSize);

        if (messages[i]->payload == NULL) {
            // Allocation failed, clean up and return NULL
            free(messages[i]);

            for (--i; i >= 0; --i) {
                free(messages[i]);
