import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MD5Hasher {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);  // Adjust according to your needs.
    private final HashSet<String> hashes = new HashSet<>();

    public void processStream(InputStream stream) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(stream));

        String line;
        try {
            while ((line = reader.readLine()) != null) {
                executor.submit(() -> computeAndStoreMD5(line));
            }
        } catch (IOException e) {
            // Handle exception.
        }
    }

    private void computeAndStoreMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));

            String hash = bytesToHex(digest);

            synchronized (hashes) {  // Ensure thread safety.
                if (!hashes.contains(hash)) {
                    hashes.add(hash);

                    // Write to persistent storage.
                } else {
                    System.out.println("Duplicate hash detected: " + hash);
                }
            }
        } catch (Exception e) {
            // Handle exception.
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```
