pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int* rntiPool;
int poolSize = 1000; // predefined threshold for unique RNTI values
int currentIndex = 0;

void initRNTIPool() {
    srand(time(NULL));
    rntiPool = malloc(poolSize * sizeof(int));
    for (int i = 0; i < poolSize; ++i) {
        rntiPool[i] = i + 1; // assuming RNTI values start from 1
    }
}

int getRNTI() {
    pthread_mutex_lock(&lock);
    if (currentIndex >= poolSize) {
        pthread_mutex_unlock(&lock);
        return -1; // no more RNTI values available in the pool
    }
    int rnti = rntiPool[currentIndex++];
    pthread_mutex_unlock(&lock);
    return rnti;
}

int allocateArray(NFAPI_CRC_INDICATION_PDU_T** array, int N) {
    *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) return -1; // memory allocation failed

    for (int i = 0; i < N; ++i) {
        int rnti = getRNTI();
        if (rnti == -1) return -2; // no more unique RNTI values available

        (*array)[i].RX_UE_INFORMATION_TAG = 0;
        (*array)[i].RNTI = rnti;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // randomly set CRCFLAG
    }

    return 0; // allocation successful
}
```
