DynamicList* createList(size_t initialCapacity) {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (list == NULL) return NULL;

    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->capacity = initialCapacity;

    return list;
}

void destroyList(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addElement(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (element.RNTI > 0xFFFF) return -1; // RNTI out of range

    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newData == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }

        list->data = newData;
        list->capacity = newCapacity;
    }

    list->data[list->size++] = element;

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}
