int maxSize = 1024; // Define your maximum size limit here

void managePackets(UDP_PACKET *packet) {
    pthread_mutex_lock(&lock);

    Node *newNode = (Node*) malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure here
        return;
    }

    newNode->packet = packet;
    newNode->next = head;
    head = newNode;

    int size = 0;
    Node *temp = head;
    while (temp != NULL) {
        temp = temp->next;
        size++;
    }

    if (size > maxSize) {
        // Remove the last node and free its memory
        Node *prevNode = head;
        Node *currentNode = head;

        while (currentNode->next != NULL) {
            prevNode = currentNode;
            currentNode = currentNode->next;
        }

        prevNode->next = NULL;
        free(currentNode);
    }

    pthread_mutex_unlock(&lock);
}
```
