typedef struct {
    size_t max_size;
    size_t current_size;
    TCP_CONNECTION_STATS_T *connections;
    pthread_mutex_t lock;
} ConnectionList;

ConnectionList* create_list(size_t initial_size, size_t max_size) {
    ConnectionList *list = malloc(sizeof(ConnectionList));
    if (list == NULL) return NULL;

    list->max_size = max_size;
    list->current_size = 0;
    list->connections = calloc(initial_size, sizeof(TCP_CONNECTION_STATS_T));
    if (list->connections == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_connection(ConnectionList *list, TCP_CONNECTION_STATS_T connection) {
    pthread_mutex_lock(&list->lock);

    if (list->current_size >= list->max_size) {
        size_t new_size = list->max_size * 2;
        TCP_CONNECTION_STATS_T *new_connections = realloc(list->connections, new_size * sizeof(TCP_CONNECTION_STATS_T));
        if (new_connections == NULL) {
            pthread_mutex_unlock(&list->lock);
            return;
        }

        list->max_size = new_size;
        list->connections = new_connections;
    }

    list->connections[list->current_size++] = connection;

    pthread_mutex_unlock(&list->lock);
}
```
