public class Deserializer {
    public static <T> T deserialize(byte[] data, byte signature, Class<T> expectedClass) throws RuntimeException {
        if (data[0] != signature) {
            throw new RuntimeException("Mismatched signature. Expected: " + signature + ", Actual: " + data[0]);
        }

        try(ByteArrayInputStream bis = new ByteArrayInputStream(Arrays.copyOfRange(data, 1, data.length));
            ObjectInputStream in = new ObjectInputStream(bis)) {

            Object obj = in.readObject();

            if (!expectedClass.isInstance(obj)) {
                throw new RuntimeException("Mismatched class. Expected: " + expectedClass.getName() 
                    + ", Actual: " + obj.getClass().getName());
            }

            return expectedClass.cast(obj);
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }
}
```
