#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int eventType;
    time_t timestamp;
    int sourceID;
    char* payload;
} NetworkEvent;

NetworkEvent* allocateEvents(int N, size_t payloadSize) {
    if (N <= 0 || payloadSize < 1) return NULL;

    // Calculate total memory needed for events and round up to nearest multiple of 32 bytes
    const int alignment = 32;
    size_t eventSize = sizeof(NetworkEvent);
    size_t totalMemoryNeeded = N * (eventSize + payloadSize) + alignment - 1;
    totalMemoryNeeded &= ~(alignment - 1);

    // Allocate memory and align to 32 bytes boundary
    void* rawMemory = malloc(totalMemoryNeeded);
    if (!rawMemory) return NULL;
    NetworkEvent* events = (NetworkEvent*) (((size_t) rawMemory + alignment - 1) & ~(alignment - 1));

    // Initialize each event with a payload of the specified size
    for (int i = 0; i < N; ++i) {
        NetworkEvent* event = &events[i];

        // Set timestamp and source ID to default values, adjust as needed
        event->timestamp = time(NULL);
        event->sourceID = 0;

        // Allocate memory for payload
        char* payload = (char*) malloc(payloadSize);
        if (!payload) {
            freeEvents(events, N);
            return NULL;
        }
        event->payload = payload;
    }

    return events;
}

void freeEvents(NetworkEvent* events, int N) {
    // Free each event's payload and then the array itself
    for (int i = 0; i < N; ++i) {
        NetworkEvent* event = &events[i];
        if (event->payload) free(event->payload);
    }
    free(events);
}
```
