#include <stdatomic.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // fields here...
} NFAPI_CRC_INDICATION_PDU_T;

// Lock-free linked list node
typedef struct Node {
    atomic_int lock;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to insert a new node into the list
void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = malloc(sizeof(Node));
    node->data = data;

    // Acquire lock on head node
    while (atomic_exchange(&head->lock, 1) != 0);

    node->next = head;
    atomic_store(&head, node);

    // Release lock on head node
    atomic_store(&node->lock, 0);
}

// Function to delete a node from the list
void delete(Node* node) {
    Node* prev = NULL;
    Node* curr = head;

    while (curr != node && curr != NULL) {
        atomic_exchange(&curr->lock, 1);

        prev = curr;
        curr = curr->next;

        atomic_store(&prev->lock, 0);
    }

    if (curr == node) {
        // Acquire lock on previous node and current node
        while (atomic_exchange(&prev->lock, 1) != 0 || atomic_exchange(&node->lock, 1) != 0);

        prev->next = node->next;

        // Release lock on previous node and current node
        atomic_store(&prev->lock, 0);
        atomic_store(&node->lock, 0);

        free(node);
    }
}
```

