```C
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
} DynamicArray;

DynamicArray* create_array(size_t initialCapacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) return NULL;

    arr->capacity = initialCapacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    arr->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return (arr->data == NULL) ? NULL : arr;
}

void destroy_array(DynamicArray* arr) {
    pthread_mutex_destroy(&arr->lock);
    free(arr->data);
    free(arr);
}

int add_element(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newData = realloc(arr->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newData == NULL) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Overflow condition
        }

        arr->data = newData;
        arr->capacity = newCapacity;
    }

    arr->data[arr->size++] = element;

    pthread_mutex_unlock(&arr->lock);
    return 0; // Success
}

int remove_element(DynamicArray *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);

    if (index >= arr->size) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Index out of bounds
    }

    memmove(arr->data + index, arr->data + index + 1, (arr->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    --arr->size;

    pthread_mutex_unlock(&arr->lock);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);

    if (index >= arr->size) {
        pthread_mutex_unlock(&arr->lock);
        return NULL; // Index out of bounds
    }

    NFAPI_CRC_INDICATION_PDU_T element = arr->data[index];

    pthread_mutex_unlock(&arr->lock);
    return &element;
}
```
This code provides a basic dynamic array implementation with thread safety. It uses a mutex to ensure that only one thread can access or modify the array at any given time, preventing race conditions and data corruption. The `add_element` function automatically resizes the array when it is full, minimizing the number of reallocations required.
"]

