namespace http = boost::beast::http;  // from <boost/beast/http.hpp>
using tcp = boost::asio::ip::tcp;     // from <boost/asio/ip/tcp.hpp>

class HttpClient {
public:
    HttpClient(const std::string& host, const std::string& port) : resolver_(ioc_), socket_(ioc_) {
        auto const results = resolver_.resolve(host, port);
        boost::asio::connect(socket_, results.begin(), results.end());
    }

    http::response<http::dynamic_body> Get(const std::string& target) {
        // Send the HTTP request to the remote host
        http::request<http::empty_body> req{http::verb::get, target, 11};
        req.set(http::field::host, host);
        req.prepare_payload();
        http::write(socket_, req);

        // This buffer is used for reading and must be persisted
        boost::beast::flat_buffer buffer;

        // Declare a container to hold the response
        http::response<http::dynamic_body> res;

        // Receive the HTTP response
        http::read(socket_, buffer, res);

        return res;
    }

    http::response<http::dynamic_body> Post(const std::string& target, const std::string& body) {
        // Send the HTTP request to the remote host
        http::request<http::string_body> req{http::verb::post, target, 11};
        req.set(http::field::host, host);
        req.body() = body;
        req.prepare_payload();
        http::write(socket_, req);

        // This buffer is used for reading and must be persisted
        boost::beast::flat_buffer buffer;

        // Declare a container to hold the response
        http::response<http::dynamic_body> res;

        // Receive the HTTP response
        http::read(socket_, buffer, res);

        return res;
    }

private:
    boost::asio::io_context ioc_;
    tcp::resolver resolver_;
    tcp::socket socket_;
};
```

