} Node;

typedef struct {
    pthread_mutex_t lock;
    Node** table;
    size_t size;
    size_t capacity;
} HashTable;

HashTable* create_table(size_t capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->capacity = capacity;
    table->size = 0;
    table->table = calloc(capacity, sizeof(Node*));
    if (table->table == NULL) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->table[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node->context);
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->table);
    free(table);
}

int insert(HashTable* table, UEContext* context) {
    size_t index = context->UE_ID % table->capacity; // Simple hash function

    pthread_mutex_lock(&table->lock);
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return -1;

    node->context = context;
    node->next = table->table[index];
    table->table[index] = node;
    table->size++;
    pthread_mutex_unlock(&table->lock);

    return 0;
}

UEContext* get(HashTable* table, int UE_ID) {
    size_t index = UE_ID % table->capacity; // Simple hash function

    pthread_mutex_lock(&table->lock);
    Node* node = table->table[index];
    while (node != NULL && node->context->UE_ID != UE_ID) {
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return node ? node->context : NULL;
}

int delete(HashTable* table, int UE_ID) {
    size_t index = UE_ID % table->capacity; // Simple hash function

    pthread_mutex_lock(&table->lock);
    Node** link = &table->table[index];
    while (*link != NULL && (*link)->context->UE_ID != UE_ID) {
        link = &(*link)->next;
    }

    if (*link == NULL) return -1; // Not found

    Node* node = *link;
    *link = node->next;
    free(node->context);
    free(node);
    table->size--;
    pthread_mutex_unlock(&table->lock);

    return 0;
}
```
This code uses a simple hash function and does not handle collisions. For real-world use, you would want to use a more robust hashing algorithm and collision resolution strategy (like chaining or open addressing). Also, this code assumes that the UE ID is unique for each context. If it's not, you need to adjust the get() and delete() functions accordingly.
