typedef struct CacheNode {
    LTE_PDCP_CONTEXT_T data;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct {
    pthread_mutex_t lock;
    int size;
    int capacity;
    CacheNode *head, *tail;
} LRUCache;

LRUCache* createCache(int capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->head = cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

LTE_PDCP_CONTEXT_T readCache(LRUCache *cache, int UE_ID) {
    LTE_PDCP_CONTEXT_T result = {0};
    pthread_mutex_lock(&cache->lock);
    for (CacheNode *node = cache->head; node != NULL; node = node->next) {
        if (node->data.UE_ID == UE_ID) {
            result = node->data;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return result;
}

void writeCache(LRUCache *cache, LTE_PDCP_CONTEXT_T data) {
    pthread_mutex_lock(&cache->lock);
    if (cache->size == cache->capacity) {
        CacheNode *node = cache->tail;
        cache->tail = node->prev;
        free(node);
        if (cache->tail != NULL) {
            cache->tail->next = NULL;
        } else {
            cache->head = NULL;
        }
        --cache->size;
    }
    CacheNode *new_node = malloc(sizeof(CacheNode));
    new_node->data = data;
    new_node->next = cache->head;
    if (cache->head != NULL) {
        cache->head->prev = new_node;
    } else {
        cache->tail = new_node;
    }
    cache->head = new_node;
    ++cache->size;
    pthread_mutex_unlock(&cache->lock);
}
