    int qos_level;
} PacketHeader;

typedef struct Node {
    PacketHeader *header;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addPacket(PacketHeader *header) {
    pthread_mutex_lock(&lock);

    Node *new_node = malloc(sizeof(Node));
    new_node->header = header;
    new_node->next = NULL;

    if (head == NULL || head->header->qos_level < header->qos_level) {
        new_node->next = head;
        head = new_node;
    } else {
        Node *current = head;

        while (current->next != NULL && current->next->header->qos_level >= header->qos_level) {
            current = current->next;
        }

        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&lock);
}

void updatePacket(PacketHeader *header) {
    pthread_mutex_lock(&lock);

    Node *current = head;

    while (current != NULL && current->header != header) {
        current = current->next;
    }

    if (current != NULL) {
        memcpy(current->header, header, sizeof(PacketHeader));
    }

    pthread_mutex_unlock(&lock);
}
```
