#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int checksum = 0;

void addElement(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) {
        // Handle memory allocation failure gracefully
        return;
    }

    pthread_mutex_lock(&lock);
    newNode->data = data;
    newNode->next = head;
    head = newNode;
    checksum += data.CRCFLAG; // Update the checksum
    pthread_mutex_unlock(&lock);
}

void removeElement(int RNTI) {
    if(head == NULL) return;

    pthread_mutex_lock(&lock);
    Node* temp = head;
    Node* prev = NULL;

    while(temp != NULL && temp->data.RNTI != RNTI) {
        prev = temp;
        temp = temp->next;
    }

    if(temp == NULL) return; // Element not found

    checksum -= temp->data.CRCFLAG; // Update the checksum

    if(prev != NULL) {
        prev->next = temp->next;
    } else {
        head = temp->next;
    }

    free(temp); // Release memory
    pthread_mutex_unlock(&lock);
}

void updateElement(int RNTI, NFAPI_CRC_INDICATION_PDU_T newData) {
    Node* temp = head;

    while(temp != NULL && temp->data.RNTI != RNTI) {
        temp = temp->next;
    }

    if(temp == NULL) return; // Element not found

    pthread_mutex_lock(&lock);
    checksum -= temp->data.CRCFLAG; // Update the checksum
    temp->data = newData;
    checksum += newData.CRCFLAG; // Update the checksum
    pthread_mutex_unlock(&lock);
}

int getChecksum() {
    int sum = 0;

    pthread_mutex_lock(&lock);
    sum = checksum;
    pthread_mutex_unlock(&lock);

    return sum;
}
```
