['Here is a basic implementation using libcurl for HTTP requests and pthreads for concurrency. This example does not include error handling for simplicity. In a real-world scenario, you would want to add proper error checking and handle edge cases. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    int RNTI;
    // other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char* url;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    int maxRetries;
} UploadJob;

void *uploadFile(void *arg) {
    UploadJob *job = (UploadJob *) arg;
    CURL *curl;
    FILE *fp;

    fp = fopen(job->url, "wb"); // open file for writing binary data
    if(!fp) return NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    int retryCount = 0;
    while (retryCount < job->maxRetries) {
        // write PDU to file
        fwrite(&job->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);

        curl_easy_setopt(curl, CURLOPT_URL, job->url);
        curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L);
        curl_easy_setopt(curl, CURLOPT_READDATA, fp);

        // perform upload
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            retryCount++;
            continue;
        } else {
            break;
        }
    }

    fclose(fp);
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    return NULL;
}

void processAndUploadPDUs(NFAPI_CRC_INDICATION_PDU_T *pdus, int pduCount, char **urls, int maxRetries) {
    pthread_t threads[pduCount];
    UploadJob jobs[pduCount];

    for (int i = 0; i < pduCount; i++) {
        jobs[i].url = urls[i];
        jobs[i].pdu = pdus[i];
        jobs[i].maxRetries = maxRetries;

        // create a new thread for each upload job
        if (pthread_create(&threads[i], NULL, uploadFile, &jobs[i])) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for (int i = 0; i < pduCount; i++) {
        // wait for all threads to finish
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return;
        }
    }
}
```
This code creates a separate thread for each file upload. It uses libcurl's easy interface to perform the HTTP PUT request and retry on failure up to `maxRetries` times. The function returns when all threads have finished executing. 

Please note that this is a basic implementation and does not include error handling or logging mechanisms, which would be necessary for a production-level application. Also, it assumes that the URLs are valid file paths, which may not be the case in a real-world scenario. You might want to add proper error checking and handle edge cases as needed.
