void* processAndStoreLog(void* arg) {
    LOG_EVENT_RECORD* record = (LOG_EVENT_RECORD*)arg;

    // Determine severity level based on predefined thresholds
    SeverityLevel severity = INFO; // placeholder, replace with actual logic

    int retryCount = 0;
    while(retryCount < 3) { // configurable limit of 3 retries
        if (storeLogInDatabase(record, severity)) {
            pthread_mutex_lock(&report.lock);
            ++report.count[severity];
            pthread_mutex_unlock(&report.lock);
            break;
        } else {
            ++retryCount;
        }
    }

    if (retryCount == 3) {
        // Log or handle error here, e.g., fprintf(stderr, "Failed to store log after 3 retries\n");
    }

    return NULL;
}

SummaryReport batchProcessAndStoreLogs(LOG_EVENT_RECORD* records, int recordCount) {
    pthread_t threads[recordCount];

    for (int i = 0; i < recordCount; ++i) {
        pthread_create(&threads[i], NULL, processAndStoreLog, &records[i]);
    }

    for (int i = 0; i < recordCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    return report;
}
