    float TX_POWER_LEVEL;
    int CHANNEL_QUALITY_INDICATOR;
    time_t timestamp;
} LTE_PHY_MEASUREMENTS_T;

typedef struct {
    LTE_PHY_MEASUREMENTS_T *data;
    size_t capacity;
    atomic_size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* createList(size_t initialCapacity) {
    DynamicList *list = malloc(sizeof(DynamicList));
    list->data = malloc(initialCapacity * sizeof(LTE_PHY_MEASUREMENTS_T));
    list->capacity = initialCapacity;
    atomic_init(&list->size, 0);
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void addToList(DynamicList *list, LTE_PHY_MEASUREMENTS_T measurement) {
    pthread_mutex_lock(&list->lock);

    size_t currentSize = atomic_load(&list->size);
    if (currentSize == list->capacity) {
        // Resize the list
        list->data = realloc(list->data, 2 * list->capacity * sizeof(LTE_PHY_MEASUREMENTS_T));
        list->capacity *= 2;
    }

    list->data[currentSize] = measurement;
    atomic_fetch_add(&list->size, 1);

    pthread_mutex_unlock(&list->lock);
}
```

