    TimePoint time;
    EventType type;
    EventDetails details;
};

class EventManager {
private:
    std::unordered_map<std::string, NetworkEvent> events;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

public:
    void addEvent(const std::string& key, const TimePoint& time, EventType type, const EventDetails& details) {
        NetworkEvent event{time, type, details};

        pthread_mutex_lock(&mutex);
        events[key] = event;
        pthread_mutex_unlock(&mutex);
    }

    void updateEvent(const std::string& key, const TimePoint& time, EventType type, const EventDetails& details) {
        NetworkEvent event{time, type, details};

        pthread_mutex_lock(&mutex);
        events[key] = event;
        pthread_mutex_unlock(&mutex);
    }

    NetworkEvent* getEvent(const std::string& key) {
        pthread_mutex_lock(&mutex);
        auto it = events.find(key);

        if (it != events.end()) {
            pthread_mutex_unlock(&mutex);
            return &it->second;
        } else {
            pthread_mutex_unlock(&mutex);
            return nullptr;
        }
    }
};
```
