void init(DynamicArray* a, size_t initialSize) {
    a->array = (LTE_DL_FRAME_MESSAGE*)malloc(initialSize * sizeof(LTE_DL_FRAME_MESSAGE));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
