void insert(DynamicArray* a, LTE_DL_FRAME_MESSAGE element) {
    pthread_mutex_lock(&a->lock);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (LTE_DL_FRAME_MESSAGE*)realloc(a->array, a->size * sizeof(LTE_DL_FRAME_MESSAGE));
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->lock);
}

void delete(DynamicArray* a, size_t index) {
    pthread_mutex_lock(&a->lock);
    if (index < a->used) {
        for (size_t i = index; i < a->used - 1; ++i) {
            a->array[i] = a->array[i + 1];
        }
        --a->used;
    }
    pthread_mutex_unlock(&a->lock);
}

void updateConfig(DynamicArray* a, size_t index, DL_FRAME_CONFIG newConfig) {
    pthread_mutex_lock(&a->lock);
    if (index < a->used) {
        a->array[index].config = newConfig;
    }
    pthread_mutex_unlock(&a->lock);
}
