using System;
using System.Collections.Generic;
using UnityEngine;

public class RandomValueGenerator
{
    private int min, max;
    private HashSet<string> usedStrings = new HashSet<string>();

    public RandomValueGenerator(int min, int max)
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum");

        this.min = min;
        this.max = max;
    }

    public int GenerateInt() => UnityEngine.Random.Range(min, max + 1);

    public float GenerateFloat() => (float)UnityEngine.Random.Range((double)min, (double)max + 0.99999999F);

    public string GenerateString(int length, string charSet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890")
    {
        if (length <= 0) throw new ArgumentException("Length must be greater than zero");

        string result;
        do
        {
            result = "";
            for (int i = 0; i < length; i++)
                result += charSet[UnityEngine.Random.Range(0, charSet.Length)];
        } while (usedStrings.Contains(result));

        usedStrings.Add(result);
        return result;
    }

    public override string ToString() => $"Min: {min}, Max: {max}";
}
```

