#define MAX_POOL_SIZE 10000
NFAPI_L2_PDU_T *pool[MAX_POOL_SIZE];
int pool_index = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory from the pool
NFAPI_L2_PDU_T* allocate() {
    pthread_mutex_lock(&lock);
    if (pool_index < MAX_POOL_SIZE) {
        NFAPI_L2_PDU_T *pdu = malloc(sizeof(NFAPI_L2_PDU_T));
        pool[pool_index++] = pdu;
        pthread_mutex_unlock(&lock);
        return pdu;
    } else {
        // Handle memory allocation failure
        pthread_mutex_unlock(&lock);
        return NULL;
    }
}

// Function to deallocate memory back to the pool
void deallocate(NFAPI_L2_PDU_T *pdu) {
    pthread_mutex_lock(&lock);
    if (pool_index > 0) {
        memset(pdu, 0, sizeof(NFAPI_L2_PDU_T)); // Clear memory for security
        pool[--pool_index] = NULL;
    } else {
        free(pdu);
    }
    pthread_mutex_unlock(&lock);
}
