    pthread_mutex_lock(&lock);

    Node* previous = NULL;
    Node* current = head;
    while (current != NULL) {
        if (difftime(currentTime, current->data->lastReceptionTime) > timeoutPeriod) {
            // Remove the node from the list.
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }

            free(current->data);
            free(current);
        }

        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
