typedef struct {
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
} DynamicArray;

void initDynamicArray(DynamicArray *array, size_t initialCapacity) {
    array->count = 0;
    array->capacity = initialCapacity;
    array->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&array->lock, NULL);
}

void insertDynamicArray(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].RNTI == value.RNTI) {
            fprintf(stderr, "Duplicate RNTI found: %d\n", value.RNTI);
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    array->data[array->count++] = value;

    pthread_mutex_unlock(&array->lock);
}

void freeDynamicArray(DynamicArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->data);
}
