int hash_function(int rnti) {
    return rnti % HASH_TABLE_SIZE;
}

void init_session_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        session_table.contexts[i] = NULL;
    }
    pthread_mutex_init(&session_table.lock, NULL);
}

void destroy_session_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        if (session_table.contexts[i] != NULL) {
            destroy_session_context(session_table.contexts[i]);
            free(session_table.contexts[i]);
        }
    }
    pthread_mutex_destroy(&session_table.lock);
}

SessionContext* get_session_context(int rnti) {
    int hash = hash_function(rnti);
    pthread_mutex_lock(&session_table.lock);
    SessionContext* context = session_table.contexts[hash];
    if (context == NULL || context->rx_ue_information_tag.rnti != rnti) {
        // Context doesn't exist or is for a different RNTI, create it
        pthread_mutex_unlock(&session_table.lock);
        context = malloc(sizeof(SessionContext));
        init_session_context(context);
        context->rx_ue_information_tag.rnti = rnti;
        // Add other initialization here
        pthread_mutex_lock(&session_table.lock);
        session_table.contexts[hash] = context;
    } else {
        pthread_mutex_unlock(&session_table.lock);
    }
    return context;
}
