["Here's an example of how you might implement this task using C++11 features, including smart pointers and mutexes for thread safety:

```cpp
#include <mutex>
#include <memory>
#include <stdexcept>

struct Node {
    int data;
    std::shared_ptr<Node> next;
    std::weak_ptr<Node> prev;
};

class List {
public:
    void insertAfter(int target, int toInsert, std::mutex& mtx) {
        std::lock_guard<std::mutex> lock(mtx);

        if (head == nullptr) {
            head = std::make_shared<Node>();
            head->data = toInsert;
            return;
        }

        auto current = head;
        while (current != nullptr && current->data != target) {
            current = current->next;
        }

        if (current == nullptr) {
            // append to the end of the list
            auto newNode = std::make_shared<Node>();
            newNode->data = toInsert;

            auto lastNode = head;
            while (lastNode->next != nullptr) {
                lastNode = lastNode->next;
            }

            lastNode->next = newNode;
            newNode->prev = lastNode;
        } else {
            // insert after the target node
            auto newNode = std::make_shared<Node>();
            newNode->data = toInsert;

            if (current->next != nullptr) {
                current->next->prev = newNode;
            }
            newNode->next = current->next;
            newNode->prev = current;
            current->next = newNode;
        }
    }
private:
    std::shared_ptr<Node> head;
};
```

This code defines a doubly linked list with nodes containing integer data. The `insertAfter` function takes a target value, an insertion value, and a mutex for synchronization. It searches the list for the target value, then either appends the insertion value to the end of the list if the target is not found or inserts it after the first occurrence of the target. The function uses a lock_guard to ensure that only one thread can modify the list at a time.

Please note that this code does not include error handling for invalid synchronization tokens, performance thresholds, or race conditions due to the complexity and potential for different use cases. You may need to adjust this code based on your specific requirements.
"]

