['Here is a basic implementation of such function using C language with POSIX threads (pthreads) for thread safety and error handling. This code does not include the resource limit enforcement or performance monitoring as these would require additional complexity that goes beyond the scope of this task. 

```c
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

typedef struct {
    // Define your MAC_FRAME and MAC_HEADER here
} MAC_FRAME, MAC_HEADER;

typedef struct {
    // Define your ETH_FRAME_INFO structure here
} ETH_FRAME_INFO;

typedef struct NICP_MESSAGE {
    MAC_FRAME* mac_frame;
    MAC_HEADER* mac_header;
    ETH_FRAME_INFO** eth_frames;
    int frame_count;
    struct NICP_MESSAGE* next;
} NICP_MESSAGE;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NICP_MESSAGE* head = NULL;

int add_message(MAC_FRAME* mac_frame, MAC_HEADER* mac_header, ETH_FRAME_INFO** eth_frames, int frame_count) {
    if (mac_frame == NULL || mac_header == NULL || eth_frames == NULL || frame_count <= 0) {
        errno = EINVAL;
        return -1;
    }

    NICP_MESSAGE* new_message = malloc(sizeof(NICP_MESSAGE));
    if (new_message == NULL) {
        errno = ENOMEM;
        return -1;
    }

    new_message->mac_frame = mac_frame;
    new_message->mac_header = mac_header;
    new_message->eth_frames = eth_frames;
    new_message->frame_count = frame_count;
    new_message->next = NULL;

    pthread_mutex_lock(&lock);
    if (head == NULL) {
        head = new_message;
    } else {
        NICP_MESSAGE* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_message;
    }
    pthread_mutex_unlock(&lock);

    return 0;
}

int remove_message(NICP_MESSAGE* message) {
    if (message == NULL) {
        errno = EINVAL;
        return -1;
    }

    pthread_mutex_lock(&lock);
    NICP_MESSAGE** prev_next = &head;
    while (*prev_next != message && *prev_next != NULL) {
        prev_next = &((*prev_next)->next);
    }

    if (*prev_next == NULL) {
        errno = ENOENT;
        pthread_mutex_unlock(&lock);
        return -1;
    }

    *prev_next = message->next;
    free(message);
    pthread_mutex_unlock(&lock);

    return 0;
}
```
This code provides a basic thread-safe linked list for managing NICP messages. It uses a mutex to ensure that only one thread can modify the list at a time, preventing data corruption when multiple threads are manipulating the list concurrently. The `add_message` function adds a new message to the end of the list and the `remove_message` function removes a specific message from the list.
']

