#include <pthread.h>

typedef struct LTE_RRC_MES_PDU {
    int UE_CONTEXT_ID;
    int RNTI;
    int MODIFICATION_COMMAND;
    int SEQUENCE_NUMBER;
} LTE_RRC_MES_PDU;

typedef struct DynamicArray {
    LTE_RRC_MES_PDU* array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (LTE_RRC_MES_PDU*)malloc(initialSize * sizeof(LTE_RRC_MES_PDU));
    if(a->array == NULL) exit(-1); // Handle memory allocation failure

    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insertDynamicArray(DynamicArray *a, LTE_RRC_MES_PDU element) {
    pthread_mutex_lock(&a->lock); // Lock the array for thread safety

    if (a->used == a->size) {
        a->size *= 2;
        a->array = (LTE_RRC_MES_PDU*)realloc(a->array, a->size * sizeof(LTE_RRC_MES_PDU));
        if(a->array == NULL) exit(-1); // Handle memory allocation failure
    }

    a->array[a->used++] = element;

    pthread_mutex_unlock(&a->lock); // Unlock the array after modification
}

void freeDynamicArray(DynamicArray *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;

    pthread_mutex_destroy(&a->lock); // Destroy the lock after array is freed
}
```
This code uses a simple dynamic array with thread safety. When an element is inserted, it locks the array to prevent other threads from modifying it at the same time. After modification, it unlocks the array for other threads to use. 

