typedef struct {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_array(size_t initialCapacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) return NULL;

    arr->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (arr->data == NULL) {
        free(arr);
        return NULL;
    }

    arr->capacity = initialCapacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

void destroy_array(DynamicArray *arr) {
    free(arr->data);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int add_element(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(arr->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newData == NULL) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // out of memory
        }

        arr->data = newData;
        arr->capacity = newCapacity;
    }

    arr->data[arr->size++] = element;

    pthread_mutex_unlock(&arr->lock);
    return 0; // success
}

// remove and find functions would be similar, but they might need to search the array for a matching RNTI or CRCFLAG.
```
