['Here is an example of how you might implement this in C using POSIX threads for thread safety and glib for memory management. This code does not include any actual network interface configuration or DNS server retrieval as those are complex tasks that would require platform-specific APIs, which are beyond the scope of a simple function.

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    char *name;
    char *ip_address;
    char *subnet_mask;
    char *gateway;
    GList *dns_servers;
} NetworkConfig;

GHashTable *configs = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_config(char *name, char *ip_address, char *subnet_mask, char *gateway, GList *dns_servers) {
    pthread_mutex_lock(&lock);

    NetworkConfig *new_config = malloc(sizeof(NetworkConfig));
    new_config->name = strdup(name);
    new_config->ip_address = strdup(ip_address);
    new_config->subnet_mask = strdup(subnet_mask);
    new_config->gateway = strdup(gateway);
    new_config->dns_servers = g_list_copy(dns_servers);

    g_hash_table_insert(configs, name, new_config);

    pthread_mutex_unlock(&lock);
}

void update_config(char *name, char *ip_address, char *subnet_mask, char *gateway, GList *dns_servers) {
    pthread_mutex_lock(&lock);

    NetworkConfig *old_config = g_hash_table_lookup(configs, name);
    if (old_config != NULL) {
        free(old_config->name);
        free(old_config->ip_address);
        free(old_config->subnet_mask);
        free(old_config->gateway);
        g_list_free_full(old_config->dns_servers, free);
        free(old_config);
    }

    add_config(name, ip_address, subnet_mask, gateway, dns_servers);

    pthread_mutex_unlock(&lock);
}

void delete_config(char *name) {
    pthread_mutex_lock(&lock);

    NetworkConfig *old_config = g_hash_table_lookup(configs, name);
    if (old_config != NULL) {
        free(old_config->name);
        free(old_config->ip_address);
        free(old_config->subnet_mask);
        free(old_config->gateway);
        g_list_free_full(old_config->dns_servers, free);
        free(old_config);

        g_hash_table_remove(configs, name);
    }

    pthread_mutex_unlock(&lock);
}
```

