DynamicArray* create_dynamic_array(size_t initialCapacity) {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (da == NULL) return NULL;

    da->capacity = initialCapacity;
    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);
    da->array = malloc(initialCapacity * sizeof(MAC_TransmissionParameters));
    if (da->array == NULL) {
        free(da);
        return NULL;
    }

    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    pthread_mutex_destroy(&da->lock);
    free(da->array);
    free(da);
}

int add_to_array(DynamicArray* da, MAC_TransmissionParameters item) {
    pthread_mutex_lock(&da->lock);

    if (da->count == da->capacity) {
        size_t newCapacity = da->capacity * 2;
        MAC_TransmissionParameters* newArray = realloc(da->array, newCapacity * sizeof(MAC_TransmissionParameters));
        if (newArray == NULL) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Error
        }

        da->capacity = newCapacity;
        da->array = newArray;
    }

    da->array[da->count++] = item;

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}
