public class FileHasher {
    private static final int BUFFER_SIZE = 8192; // Use a buffer size that is suitable for your use case

    public String generateMD5Hash(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");

        try (InputStream is = new FileInputStream(filePath)) {
            byte[] buffer = new byte[BUFFER_SIZE];
