    MAC_PDU pdu;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_mac_pdu(MAC_HEADER header, MAC_PAYLOAD payload, TX_POWER_LEVEL tx_power_level) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return;
    }

    newNode->pdu.header = header;
    newNode->pdu.payload = payload;
    newNode->pdu.tx_power_level = tx_power_level;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}

MAC_PDU* get_mac_pdu(int index) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    int count = 0;

    while (current != NULL && count < index) {
        current = current->next;
        count++;
    }

    if (count == index && current != NULL) {
        pthread_mutex_unlock(&lock);
        return &(current->pdu);
    } else {
        pthread_mutex_unlock(&lock);
        return NULL; // Return NULL if the index is out of bounds
    }
}
```
