#include <pthread.h>
#include <jansson.h>
#include <stdlib.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct List {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
} List;

List* createList(size_t initialCapacity) {
    List *list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->capacity = initialCapacity;
    list->size = 0;
    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void addToList(List *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        // Resize the array
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newData == NULL) {
            pthread_mutex_unlock(&list->lock);
            return; // Memory allocation failed
        }

        list->capacity = newCapacity;
        list->data = newData;
    }

    list->data[list->size++] = item;

    pthread_mutex_unlock(&list->lock);
}

// Other functions for removing items, getting an item by index etc. would be similar

void destroyList(List *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
