#include <string.h>

typedef struct Packet {
    int timestamp;
    int sequence_number;
    int payload_size;
    unsigned char* payload;
} Packet;

typedef struct ConnectionRecord {
    int connection_id;
    char* peer_ip;
    Packet* packets;
    struct ConnectionRecord* next;
} ConnectionRecord;

typedef struct ConnectionManager {
    ConnectionRecord* connections;
} ConnectionManager;

unsigned char* calculateSHA256(const unsigned char* payload, size_t len) {
    unsigned char* hash = (unsigned char*)malloc(32); // 256 bits = 32 bytes
    SHA256(payload, len, hash);
    return hash;
}

void addPacketToConnection(ConnectionManager* manager, Packet* packet) {
    ConnectionRecord* record = manager->connections;
    while (record != NULL) {
        if (record->connection_id == packet->timestamp && strcmp(record->peer_ip, "") == 0) { // Assuming timestamp is connection id and peer ip is "" for simplicity
            Packet* newPacket = malloc(sizeof(Packet));
            memcpy(newPacket, packet, sizeof(Packet));
            newPacket->next = record->packets;
            record->packets = newPacket;
            return;
        }
        record = record->next;
    }

    // If no suitable connection found, create a new one
    ConnectionRecord* newConnection = malloc(sizeof(ConnectionRecord));
    newConnection->connection_id = packet->timestamp;
    newConnection->peer_ip = "";
    newConnection->packets = packet;
    newConnection->next = manager->connections;
    manager->connections = newConnection;
}
