['Here is a basic implementation of your requirements in C using pthreads for thread safety. This code does not include all error checking or edge case handling that would be necessary for a production-level application. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} List;

List* createList() {
    List* list = malloc(sizeof(List));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = malloc(sizeof(Node));
    node->data = data;
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        Node* current = list->head;
        while (current != NULL) {
            if (current->data.RNTI == data.RNTI) {
                // Duplicate found, update the existing entry
                current->data = data;
                pthread_mutex_unlock(&list->lock);
                return;
            }
            current = current->next;
        }
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void removeByRNTI(List* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            list->size--;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void printForward(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("RNTI: %d, CRCFLAG: %d\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }
}

void printBackward(List* list) {
    Node* current = list->tail;
    while (current != NULL) {
        printf("RNTI: %d, CRCFLAG: %d\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->prev;
    }
}
```
This code provides a basic implementation of the requirements you specified. It uses a doubly linked list to store the data and pthreads for thread safety. The `insert` function checks for duplicates based on `RNTI`, updating existing entries if necessary. The `removeByRNTI` function removes elements by their `RNTI`. The `printForward` and `printBackward` functions print the list in forward or reverse order respectively.
']

