    NetworkEvent data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;

void addEvent(NetworkEvent event) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->data = event;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeEvent(int index) {
    pthread_mutex_lock(&lock);

    if (head == NULL) {
        printf("List is empty.\n");
        return;
    }

    Node *temp = head;
    if (index == 0) {
        head = temp->next;
        free(temp);
        pthread_mutex_unlock(&lock);
        return;
    }

    for (int i = 0; temp != NULL && i < index - 1; i++)
        temp = temp->next;

    if (temp == NULL || temp->next == NULL) {
        printf("Index out of range.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Node *next = temp->next->next;
    free(temp->next);
    temp->next = next;

    pthread_mutex_unlock(&lock);
}

NetworkEvent getEvent(int index) {
    pthread_mutex_lock(&lock);

    Node *current = head;
    int count = 0;
    while (current != NULL) {
        if (count == index)
            return current->data;
        count++;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void serializeEvents() {
    FILE *file = fopen("events.bin", "wb");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    Node *current = head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NetworkEvent), 1, file);
        current = current->next;
    }

    fclose(file);
}

void deserializeEvents() {
    FILE *file = fopen("events.bin", "rb");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    NetworkEvent event;
    while(fread(&event, sizeof(NetworkEvent), 1, file)) {
        addEvent(event);
    }

    fclose(file);
}
```
