void addEvent(EventArray* arr, NetworkEvent* event) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count == arr->capacity) {
        // Double the capacity when full
        arr->capacity *= 2;
        arr->events = realloc(arr->events, sizeof(NetworkEvent*) * arr->capacity);
    }

    arr->events[arr->count++] = event;

    pthread_mutex_unlock(&arr->lock);
}

// Remove an event from the array by index
