    if (node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    node->rx_ue_info = rx_ue_info;
    node->RNTI = RNTI;
    node->crc_ind_rel8 = crc_ind_rel8;
    node->prev = NULL;
    node->next = NULL;

    return node;
}

void addNode(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* newNode) {
    if (*head == NULL) {
        *head = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *head;

        while (current->next != NULL) {
            // Check for duplicate RNTI and reassign if necessary
            if (current->RNTI == newNode->RNTI) {
                newNode->RNTI = getUniqueRNTI();  // Implement this function to generate a unique RNTI
            }

            current = current->next;
        }

        if (current->RNTI == newNode->RNTI) {
            newNode->RNTI = getUniqueRNTI();  // Implement this function to generate a unique RNTI
        }

        current->next = newNode;
        newNode->prev = current;
    }
}
